def work_area(w, x=None, y=None):
    """(x0, y0, x1, y1)：その位置のモニターの作業領域（タスクバーを除く）。取れなければ画面全体からタスクバー分を引く"""
    if sys.platform.startswith("win"):
        try:
            import ctypes
            from ctypes import wintypes

            class MONITORINFO(ctypes.Structure):
                _fields_ = [("cbSize", wintypes.DWORD), ("rcMonitor", wintypes.RECT),
                            ("rcWork", wintypes.RECT), ("dwFlags", wintypes.DWORD)]
            if x is None:
                x, y = w.winfo_pointerx(), w.winfo_pointery()
            pt = wintypes.POINT(int(x), int(y))
            hmon = ctypes.windll.user32.MonitorFromPoint(pt, 2)   # 2＝いちばん近いモニター
            mi = MONITORINFO()
            mi.cbSize = ctypes.sizeof(MONITORINFO)
            if ctypes.windll.user32.GetMonitorInfoW(hmon, ctypes.byref(mi)):
                r = mi.rcWork
                return r.left, r.top, r.right, r.bottom
        except Exception:
            pass
    sw, sh = w.winfo_screenwidth(), w.winfo_screenheight()
    return 0, 0, sw, sh - (40 if sys.platform.startswith("win") else 28)


def fit_on_screen(w, margin=6):
    """ウインドウ全体が画面（作業領域）の中に入るよう、位置（必要なら大きさ）を直す"""
    try:
        if not w.winfo_exists() or w.state() in ("withdrawn", "iconic", "zoomed"):
            return
        try:
            if not sys.platform.startswith("win") and w.attributes("-zoomed"):   # 最大化しているウインドウはそのまま
                return
        except Exception:
            pass
        w.update_idletasks()
        ww = max(w.winfo_width(), w.winfo_reqwidth()) if w.winfo_width() <= 1 else w.winfo_width()
        wh = max(w.winfo_height(), w.winfo_reqheight()) if w.winfo_height() <= 1 else w.winfo_height()
        x, y = w.winfo_x(), w.winfo_y()
        x0, y0, x1, y1 = work_area(w, x + ww // 2, y + min(wh // 2, 40))
        title_h = 0 if w.overrideredirect() else 30   # タイトルバーの分
        aw, ah = x1 - x0 - 2 * margin, y1 - y0 - 2 * margin - title_h
        nw, nh = min(ww, aw), min(wh, ah)
        nx = min(max(x, x0 + margin), x1 - margin - nw)
        ny = min(max(y, y0 + margin), y1 - margin - title_h - nh)
        if (nw, nh) != (ww, wh):
            w.geometry(f"{int(nw)}x{int(nh)}+{int(nx)}+{int(ny)}")
        elif (nx, ny) != (x, y):
            w.geometry(f"+{int(nx)}+{int(ny)}")
    except Exception:
        pass


def _red_arrow_cur(path):
    """赤い矢印のカーソル（Windows の .cur・32bit）を作る"""
    import struct
    poly = [(0, 0), (0, 22), (6, 16.5), (10, 26), (14, 24.5), (10.5, 15), (17, 15)]

    def inside(px, py):
        c = False
        for i in range(len(poly)):
            (x1, y1), (x2, y2) = poly[i], poly[i - 1]
            if (y1 > py) != (y2 > py) and px < (x2 - x1) * (py - y1) / (y2 - y1 + 1e-9) + x1:
                c = not c
        return c
    N = 32
    fill = [[inside(x + 0.5, y + 0.5) for x in range(N)] for y in range(N)]
    rows = []
    for y in range(N - 1, -1, -1):   # 下の行から
        row = b""
        for x in range(N):
            if fill[y][x]:
                edge = any(not (0 <= x + dx < N and 0 <= y + dy < N and fill[y + dy][x + dx])
                           for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)))
                row += bytes((255, 255, 255, 255)) if edge else bytes((40, 40, 230, 255))   # BGRA：縁は白・中は赤
            else:
                row += bytes((0, 0, 0, 0))
        rows.append(row)
    xor = b"".join(rows)
    andm = b"\x00" * (4 * N)   # 透明は色データの α で
    hdr = struct.pack("<IiiHHIIiiII", 40, N, N * 2, 1, 32, 0, len(xor) + len(andm), 0, 0, 0, 0)
    img = hdr + xor + andm
    data = struct.pack("<HHH", 0, 2, 1) + struct.pack("<BBBBHHII", N, N, 0, 0, 0, 0, len(img), 22) + img
    with open(path, "wb") as f:
        f.write(data)


_RED_CURSOR = None


def red_cursor(widget):
    """タスクの上に乗せたとき（移動・時刻変更できるとき）の赤い矢印カーソル。作れない環境では普通の矢印"""
    global _RED_CURSOR
    if _RED_CURSOR is not None:
        return _RED_CURSOR
    cands = []
    if sys.platform.startswith("win"):
        try:
            import tempfile
            p = os.path.join(tempfile.gettempdir(), "mind_navi_red_arrow.cur")
            _red_arrow_cur(p)
            cands.append("@" + p.replace("\\", "/"))
        except Exception:
            pass
    cands += ["left_ptr red white", "arrow red white", "arrow"]
    cur0 = widget.cget("cursor")
    for c in cands:
        try:
            widget.configure(cursor=c)
            _RED_CURSOR = c
            break
        except Exception:
            continue
    try:
        widget.configure(cursor=cur0)
    except Exception:
        pass
    return _RED_CURSOR or ""


def maximize_window(w):
    """ウインドウを最大化（Windows：zoomed／Mac：画面いっぱい／Linux：-zoomed）。効かないときは画面いっぱいの大きさに"""
    try:
        if sys.platform.startswith("win"):
            w.state("zoomed")
        elif sys.platform == "darwin":
            w.geometry(f"{w.winfo_screenwidth()}x{w.winfo_screenheight() - 60}+0+0")
        else:
            w.attributes("-zoomed", True)
    except Exception:
        w.geometry(f"{w.winfo_screenwidth()}x{w.winfo_screenheight() - 60}+0+0")

    def ensure_big():
        try:
            if w.winfo_exists() and w.winfo_width() < w.winfo_screenwidth() * 0.9 and w.state() != "zoomed":
                w.geometry(f"{w.winfo_screenwidth()}x{w.winfo_screenheight() - 60}+0+0")
        except Exception:
            pass
    try:
        w.after(300, ensure_big)
    except Exception:
        pass


class MindNavi:
    def __init__(self):
        self.nodes = {}   # id -> dict（属性は自由に追加可）
        self.edges = []   # dict(source, target, relation)
        self.view = {"style": "office", "auto_layout": True, "positions": {}}
        self._sp = 1.0
        self._size = lambda n: DEFAULT_SIZE

    # ---------- 基本操作 ----------
    def add_node(self, label="", parent=None, **attrs):
        nid = str(attrs.pop("id", "") or uuid.uuid4().hex[:8])
        kind = "goal" if parent is None else "task"
        t = now()
        node = {"id": nid, "label": label, "kind": kind, "status": "todo",
                "priority": "", "start": "", "due": "", "note": "", "x": 0.0, "y": 0.0,
                "created": t, "updated": t}
        node.update(attrs)
        self.nodes[nid] = node
        if parent is not None:
            self.add_edge(parent, nid, REL_CHILD)
        return nid

    def add_edge(self, source, target, relation=REL_CHILD, **attrs):
        if source == target or source not in self.nodes or target not in self.nodes:
            return
        if self.find_edge(source, target, relation):
            return
        if relation == REL_CHILD:   # 親は1つだけ
            self.edges = [e for e in self.edges
                          if not (e["relation"] == REL_CHILD and e["target"] == target)]
        self.edges.append({"source": source, "target": target, "relation": relation, **attrs})

    def find_edge(self, source, target, relation):
        for e in self.edges:
            if e["source"] == source and e["target"] == target and e["relation"] == relation:
                return e
        return None

    def remove_node(self, nid):
        """ノードを子孫ごと削除"""
        gone = {nid} | self.descendants(nid)
        for g in gone:
            n = self.nodes.pop(g, None)
            if n and n.get("gcal_id"):   # 次の同期で Google 側の予定も削除する
                self.view.setdefault("gcal_trash", []).append(n["gcal_id"])
        self.edges = [e for e in self.edges if e["source"] not in gone and e["target"] not in gone]

    def toggle_link(self, a, b):
        e = self.find_edge(a, b, REL_LINK) or self.find_edge(b, a, REL_LINK)
        if e:
            self.edges.remove(e)
            return False
        self.add_edge(a, b, REL_LINK)
        return True

    def set_parent(self, nid, new_parent):
        if new_parent is not None and (new_parent == nid or new_parent in self.descendants(nid)):
            raise ValueError("自分の下位ノードを親にはできません")
        self.edges = [e for e in self.edges
                      if not (e["relation"] == REL_CHILD and e["target"] == nid)]
        if new_parent is not None:
            self.add_edge(new_parent, nid, REL_CHILD)

    # ---------- 構造の参照 ----------
    @property
    def edges(self):
        return self._edges

    @edges.setter
    def edges(self, v):   # 置き換えたら親子の対応を作り直す
        self._edges = v
        self._edge_cache = None

    def _tree_idx(self):
        """親子の対応を1回だけ作って使い回す（エッジが変わったら作り直す）。描き直しを速くするため"""
        key = (id(self.edges), len(self.edges))
        c = getattr(self, "_edge_cache", None)
        if c is None or c[0] != key:
            par, kids = {}, {}
            for e in self.edges:
                if e["relation"] == REL_CHILD:
                    par.setdefault(e["target"], e["source"])
                    kids.setdefault(e["source"], []).append(e["target"])
            c = self._edge_cache = (key, par, kids)
        return c

    def parent(self, nid):
        return self._tree_idx()[1].get(nid)

    def children(self, nid):
        return list(self._tree_idx()[2].get(nid, ()))

    def child_map(self, visible_only=False):
        """親→子の対応。visible_only=True なら折りたたんだノードの子は含めない"""
        cm = {n: [] for n in self.nodes}
        for e in self.edges:
            if e["relation"] == REL_CHILD and e["source"] in cm:
                if visible_only and is_folded(self.nodes[e["source"]]):
                    continue
                cm[e["source"]].append(e["target"])
        return cm

    def has_undone(self, nid):
        """その枝（自分と下位）に未完了のタスクがあるか"""
        for k in {nid} | self.descendants(nid):
            n = self.nodes[k]
            if n.get("kind") == "task" and n.get("status") != "done":
                return True
        return False

    def pruned_kids(self, nid):
        """「未完了のツリーだけ」で隠している子（未完了タスクを含まない枝）"""
        if not self.nodes[nid].get("hide_done_kids"):
            return []
        return [c for c in self.children(nid) if not self.has_undone(c)]

    def user_hidden(self):
        """「非表示」に設定したノードとその下位"""
        out = set()
        for nid, n in self.nodes.items():
            if n.get("hidden") and nid not in out:
                out |= {nid} | self.descendants(nid)
        return out

    def get_filter(self):
        f = self.view.get("filter") or {}
        return {"undone": bool(f.get("undone")), "pri": [p for p in (f.get("pri") or []) if p in ("1", "2", "3")],
                "keep": [k for k in (f.get("keep") or []) if k in self.nodes]}

    def filter_active(self):
        f = self.get_filter()
        return f["undone"] or bool(f["pri"])

    def node_matches(self, n, f=None):
        """絞り込みの条件に合うタスクか（未完了・優先度）"""
        f = f or self.get_filter()
        if f["undone"] and not (n.get("kind") == "task" and n.get("status") != "done"):
            return False
        if f["pri"] and str(n.get("imp") or "") not in f["pri"]:   # 重要度（順位）で絞り込み
            return False
        return True

    def filter_visible(self):
        """絞り込み中に表示するノード：条件に合うタスクと、そこに至る上位だけ（合わない兄弟の枝は出さない）"""
        f = self.get_filter()
        uh = self.user_hidden()
        vis = set()
        for nid, n in self.nodes.items():
            if nid in uh or nid in vis or not (self.node_matches(n, f) or nid in f["keep"]):
                continue
            vis.add(nid)
            p = self.parent(nid)
            while p and p not in vis:
                vis.add(p)
                p = self.parent(p)
        return vis

    def hidden_nodes(self):
        """表示しないノード：折りたたみの下位・「非表示」設定・絞り込みで外れたもの"""
        hidden = set(self.user_hidden())
        if getattr(self, "hide_inbox", False):   # カレンダーで作った未分類のタスクは、マップでは別枠に出す
            for nid, n in self.nodes.items():
                if n.get("calendar_root") or n.get("adhoc_root"):   # Adhocはマップのどこにも出さない
                    hidden |= {nid} | self.descendants(nid)
        for flag, show in (("lecture_root", "show_lectures"), ("shift_root", "show_shifts")):
            if not self.view.get(show):   # 講義（Lecture）・勤務（Shift）のツリーはマップではふだん出さない
                for nid, n in self.nodes.items():
                    if n.get(flag):
                        hidden |= {nid} | self.descendants(nid)
        for nid, n in self.nodes.items():
            if nid in hidden:
                continue
            if is_folded(n):
                hidden |= self.descendants(nid)
            elif n.get("hide_done_kids"):
                for c in self.pruned_kids(nid):
                    hidden |= {c} | self.descendants(c)
        if self.filter_active():
            vis = self.filter_visible()
            hidden |= {k for k in self.nodes if k not in vis}
        return hidden

    def layout_mode(self, style):
        mode = self.view.get("layouts", {}).get(style)
        return mode if mode in LAYOUTS else DEFAULT_LAYOUT.get(style, "tree")

    def roots(self):
        has_parent = self._tree_idx()[1]
        return [n for n in self.nodes if n not in has_parent]

    # ---------- カテゴリ＝マインドマップのノード（第二階層＋カテゴリにしたノード） ----------
    def ancestors(self, nid):
        out, p = [], self.parent(nid)
        while p and p not in out:
            out.append(p)
            p = self.parent(p)
        return out

    def special_tree(self, nid):
        """カレンダー（未分類）・講義・勤務のまとめのツリーか"""
        for a in [nid] + self.ancestors(nid):
            v = self.nodes.get(a, {})
            if v.get("calendar_root") or v.get("lecture_root") or v.get("shift_root") or v.get("adhoc_root"):
                return True
        return False

    def is_level2(self, nid):
        """第二階層（最上位のすぐ下）のノードか"""
        p = self.parent(nid)
        return bool(p) and self.parent(p) is None

    def category_nodes(self):
        """カテゴリにするノード：第二階層（最上位のすぐ下）と、その中でカテゴリにしたノード（ツリーの順）。
        カレンダー・講義・勤務のまとめは除く"""
        key = lambda k: (_to_float(self.nodes[k].get("y")), _to_float(self.nodes[k].get("x")))
        tops = sorted((k for k in self.roots() if not self.special_tree(k) and self.nodes[k].get("kind") != "note"), key=key)
        lvl2 = [c for r in tops for c in sorted(self.children(r), key=key) if self.nodes[c].get("kind") != "note"]
        out = []
        for r in lvl2:
            out.append(r)
            stack = list(reversed(self.children(r)))
            seen = set()
            while stack:
                k = stack.pop()
                if k in seen:
                    continue
                seen.add(k)
                if self.nodes[k].get("map_category"):
                    out.append(k)
                stack.extend(reversed(self.children(k)))
        return out

    def category_node_of(self, nid):
        """そのタスクのカテゴリのノード（いちばん近い上位のカテゴリ。未分類なら None）"""
        chain = self.ancestors(nid)
        root = chain[-1] if chain else nid
        rv = self.nodes.get(root, {})
        if rv.get("calendar_root"):
            return None
        if rv.get("lecture_root") or rv.get("shift_root") or rv.get("adhoc_root"):
            return root   # 講義（Lecture）・勤務・Adhocはそのまとめをカテゴリに
        for a in chain:   # いちばん近い「カテゴリにしたノード」
            if self.nodes[a].get("map_category") and len(self.ancestors(a)) >= 2:
                return a
        path = list(reversed(chain)) + [nid]   # 最上位 → … → 自分
        return path[1] if len(path) >= 2 else None   # 第二階層。最上位そのものは未分類

    def category_of(self, nid):
        """集計に使うカテゴリ名（＝カテゴリのノードの名前。未分類は「（未分類）」）"""
        c = self.category_node_of(nid)
        return (self.nodes[c].get("label") or "（無題）") if c else "（未分類）"

    def descendants(self, nid):
        out, stack = set(), list(self.children(nid))
        while stack:
            c = stack.pop()
            if c not in out:
                out.add(c)
                stack.extend(self.children(c))
        return out

    def depth(self, nid):
        d, p, seen = 0, self.parent(nid), set()
        while p is not None and p not in seen:
            seen.add(p)
            d += 1
            p = self.parent(p)
        return d

    def progress(self, nid):
        """配下タスクの (完了数, 総数)"""
        tasks = [self.nodes[d] for d in self.descendants(nid) if self.nodes[d].get("kind") == "task"]
        return sum(1 for t in tasks if t.get("status") == "done"), len(tasks)

    # ---------- 自動レイアウト ----------
    def _fx(self, n):
        return _to_float(self.nodes[n].get("x"))

    def _fy(self, n):
        return _to_float(self.nodes[n].get("y"))

    @staticmethod
    def _leaf_counts(root, cm):
        memo = {}

        def count(n, path):
            ch = [c for c in cm.get(n, []) if c not in path]
            memo[n] = sum(count(c, path | {c}) for c in ch) if ch else 1
            return memo[n]
        count(root, frozenset([root]))
        return memo

    def layout(self, style="office", fresh=False, mode=None, sizes=None):
        """自動整列（各ノードの実寸を考慮し、重ならないように配置）。
        mode : tree（樹形）/ both（左右に展開）/ radial（放射状）。省略時はスタイルごとの設定
        fresh: False なら現在の並び順（位置）を尊重する
        sizes: {id: (幅, 高さ)}。省略時は標準サイズ。折りたたんだ下位は親と一緒に動かす"""
        mode = mode or self.layout_mode(style)
        self._sp = {"note": 1.3}.get(style, 1.0)
        sz = sizes or {}
        self._size = lambda n: sz.get(n) or DEFAULT_SIZE
        cm = self.child_map(visible_only=True)
        folded = {n: (self._fx(n), self._fy(n)) for n, v in self.nodes.items()
                  if is_folded(v) and self.children(n)}
        order = {n: i for i, n in enumerate(self.nodes)}
        roots = self.roots()
        if mode == "radial":
            roots.sort(key=lambda r: (self._fx(r), self._fy(r)))
        else:
            roots.sort(key=lambda r: (self._fy(r), self._fx(r)))
        func = {"tree": self._layout_tree, "both": self._layout_mindmap,
                "radial": self._layout_radial}[mode]
        self._place_roots(roots, func, cm, fresh, order, mode)
        hidden = self.hidden_nodes()
        for n, (ox, oy) in folded.items():
            if n in hidden:
                continue
            dx, dy = self._fx(n) - ox, self._fy(n) - oy
            for d in self.descendants(n):
                self.nodes[d]["x"] = round(self._fx(d) + dx, 1)
                self.nodes[d]["y"] = round(self._fy(d) + dy, 1)

    def _place_roots(self, roots, func, cm, fresh, order, mode):
        """最上位ごとのかたまりを、外接矩形が重ならないよう並べる"""
        offset = 0.0
        for r in roots:
            pos = func(r, cm, fresh, order)
            xl = min(x - self._size(n)[0] / 2 for n, (x, y) in pos.items())
            xh = max(x + self._size(n)[0] / 2 for n, (x, y) in pos.items())
            yl = min(y - self._size(n)[1] / 2 for n, (x, y) in pos.items())
            yh = max(y + self._size(n)[1] / 2 for n, (x, y) in pos.items())
            if mode == "radial":
                dx, dy = 60 + offset - xl, 60 - yl
                offset += xh - xl + 90
            else:
                dx, dy = 60 - xl, 50 + offset - yl
                offset += yh - yl + ROOT_GAP * self._sp
            for nid, (x, y) in pos.items():
                self.nodes[nid]["x"], self.nodes[nid]["y"] = round(x + dx, 1), round(y + dy, 1)

    def _sorter(self, fresh, order, key):
        return (lambda n: order.get(n, 0)) if fresh else key

    def _blocks(self, r, cm):
        """各ノードの「帯」の高さ＝自分と下位全体が占める縦幅（兄弟の帯は重ならない）"""
        vg = V_GAP * self._sp
        B = {}

        def calc(n, path):
            ch = [c for c in cm[n] if c not in path]
            h = self._size(n)[1]
            if ch:
                B[n] = max(h, sum(calc(c, path | {c}) for c in ch) + vg * (len(ch) - 1))
            else:
                B[n] = h
            return B[n]
        calc(r, frozenset([r]))
        return B

    def _place_side(self, n, cx, top, sign, cm, B, key, pos, path, hg):
        """n を帯の中央に置き、子を親のすぐ横（親の端から hg）に縦に並べる"""
        vg = V_GAP * self._sp
        w = self._size(n)[0]
        cy = top + B[n] / 2
        pos[n] = (cx, cy)
        ch = sorted([c for c in cm[n] if c not in path], key=key)
        if not ch:
            return
        t = cy - (sum(B[c] for c in ch) + vg * (len(ch) - 1)) / 2
        for c in ch:
            wc = self._size(c)[0]
            self._place_side(c, cx + sign * (w / 2 + hg + wc / 2), t, sign, cm, B, key, pos, path | {c}, hg)
            t += B[c] + vg

    def _layout_tree(self, r, cm, fresh, order):
        B = self._blocks(r, cm)
        pos = {}
        self._place_side(r, 0.0, -B[r] / 2, 1, cm, B, self._sorter(fresh, order, self._fy), pos, {r},
                         H_GAP["tree"])
        return pos

    def _layout_mindmap(self, r, cm, fresh, order):
        B = self._blocks(r, cm)
        rx = self._fx(r)
        right, left, undecided = [], [], []
        for c in cm[r]:
            sd = 0 if fresh else self._fx(c) - rx
            (right if sd > 1 else left if sd < -1 else undecided).append(c)
        for c in undecided:   # 縦幅が小さい側へ振り分け
            if sum(B[x] for x in right) <= sum(B[x] for x in left):
                right.append(c)
            else:
                left.append(c)
        key = self._sorter(fresh, order, self._fy)
        vg = V_GAP * self._sp
        hg = H_GAP["both"]
        rw = self._size(r)[0]
        pos = {r: (0.0, 0.0)}
        for side, sign in ((right, 1), (left, -1)):
            side.sort(key=key)
            t = -(sum(B[c] for c in side) + vg * (len(side) - 1)) / 2
            for c in side:
                wc = self._size(c)[0]
                self._place_side(c, sign * (rw / 2 + hg + wc / 2), t, sign, cm, B, key, pos, {r, c}, hg)
                t += B[c] + vg
        return pos

    def _layout_radial(self, r, cm, fresh, order):
        leaves = self._leaf_counts(r, cm)
        total = leaves[r]
        depth, maxw, maxh = {r: 0}, {}, {}
        stack = [r]
        while stack:   # 階層ごとの最大サイズ
            n = stack.pop()
            for c in cm[n]:
                if c not in depth:
                    depth[c] = depth[n] + 1
                    w, h = self._size(c)
                    maxw[depth[c]] = max(maxw.get(depth[c], 0), w)
                    maxh[depth[c]] = max(maxh.get(depth[c], 0), h)
                    stack.append(c)
        radius, prev = {}, self._size(r)[0] / 2
        for d in sorted(maxw):
            base = prev + maxw[d] / 2 + 46 * self._sp
            need = total * (maxh[d] + 0.35 * maxw[d] + 14) / (2 * math.pi)   # 円周上で重ならない半径
            radius[d] = max(base, need)
            prev = radius[d] + maxw[d] / 2
        rx, ry = self._fx(r), self._fy(r)
        start = -math.pi / 2   # 真上から時計回り

        def ang(n):
            return (math.atan2(self._fy(n) - ry, self._fx(n) - rx) - start) % (2 * math.pi)
        key = self._sorter(fresh, order, ang)
        pos = {r: (0.0, 0.0)}

        def place(n, d, a0, a1, seen):
            ch = sorted([c for c in cm[n] if c not in seen], key=key)
            tot = sum(leaves[c] for c in ch) or 1
            a = a0
            for c in ch:
                span = (a1 - a0) * leaves[c] / tot
                mid, rad = a + span / 2, radius.get(d, 200)
                pos[c] = (rad * math.cos(mid), rad * math.sin(mid))
                place(c, d + 1, a, a + span, seen | {c})
                a += span
        place(r, 1, start, start + 2 * math.pi, {r})
        return pos

    # スタイルごとの位置の記憶
    def store_positions(self, style):
        self.view.setdefault("positions", {})[style] = {
            n: [self._fx(n), self._fy(n)] for n in self.nodes}

    def restore_positions(self, style):
        pos = self.view.get("positions", {}).get(style)
        if not pos:
            return False
        missing = []
        for nid, n in self.nodes.items():
            if nid in pos:
                n["x"], n["y"] = float(pos[nid][0]), float(pos[nid][1])
            else:
                missing.append(nid)
        missing.sort(key=self.depth)
        for i, nid in enumerate(missing):   # 新しく増えたノードは親の近くへ
            p = self.parent(nid)
            if p:
                self.nodes[nid]["x"] = self._fx(p) + 220
                self.nodes[nid]["y"] = self._fy(p) + 40 * (i % 5)
        return True

    # ---------- 保存・読込 ----------
    def to_dict(self):
        return {"app": APP_NAME, "version": FORMAT_VERSION,
                "nodes": list(self.nodes.values()), "edges": self.edges, "view": self.view}

    @classmethod
    def from_dict(cls, d):
        mm = cls()
        for n in d.get("nodes", []):
            n = dict(n)
            for f in FLOAT_FIELDS:
                n[f] = _to_float(n.get(f))
            n["kind"] = LEGACY_KINDS.get(n.get("kind"), n.get("kind") or "task")
            mm.nodes[str(n["id"])] = n
        for e in d.get("edges", []):
            e = dict(e)
            e["source"], e["target"] = str(e["source"]), str(e["target"])   # （読み込み時。キャッシュはまだない）
            e.setdefault("relation", REL_CHILD)
            if e["source"] in mm.nodes and e["target"] in mm.nodes:
                mm.edges.append(e)
        if isinstance(d.get("view"), dict):
            mm.view.update(d["view"])
        return mm

    def save_json(self, path):
        with open(path, "w", encoding="utf-8") as f:
            json.dump(self.to_dict(), f, ensure_ascii=False, indent=2)

    @classmethod
    def load(cls, path):
        if path.lower().endswith(".csv"):
            return cls.import_csv(path)
        with open(path, encoding="utf-8") as f:
            return cls.from_dict(json.load(f))

    def _node_fields(self):
        extra = sorted({k for n in self.nodes.values() for k in n} - set(CORE_FIELDS))
        return CORE_FIELDS + extra

    def _edge_fields(self):
        return sorted({k for e in self.edges for k in e} - {"source", "target", "relation"})

    # ---------- 汎用形式への出力 ----------
    def export_csv(self, base):
        """base_nodes.csv / base_edges.csv を書き出す（Gephi互換ヘッダ）"""
        nodes_path, edges_path = base + "_nodes.csv", base + "_edges.csv"
        fields = self._node_fields()
        with open(nodes_path, "w", newline="", encoding=CSV_ENCODING) as f:
            w = csv.writer(f)
            w.writerow(["Id", "Label"] + fields[2:] + ["depth", "parent"])
            for n in self.nodes.values():
                w.writerow([n.get(k, "") for k in fields]
                           + [self.depth(n["id"]), self.parent(n["id"]) or ""])
        efields = self._edge_fields()
        with open(edges_path, "w", newline="", encoding=CSV_ENCODING) as f:
            w = csv.writer(f)
            w.writerow(["Source", "Target", "Type", "relation"] + efields)
            for e in self.edges:
                w.writerow([e["source"], e["target"], "Directed", e["relation"]]
                           + [e.get(k, "") for k in efields])
        return nodes_path, edges_path

    @classmethod
    def import_csv(cls, nodes_path, edges_path=None):
        if edges_path is None:
            edges_path = nodes_path.replace("_nodes.csv", "_edges.csv")
        mm = cls()
        with open(nodes_path, newline="", encoding="utf-8-sig") as f:
            for row in csv.DictReader(f):
                row = {k: v for k, v in row.items() if k is not None}
                row["id"] = row.pop("Id", row.get("id", ""))
                row["label"] = row.pop("Label", row.get("label", ""))
                row.pop("depth", None)
                row.pop("parent", None)
                for fld in FLOAT_FIELDS:
                    row[fld] = _to_float(row.get(fld))
                row["kind"] = LEGACY_KINDS.get(row.get("kind"), row.get("kind") or "task")
                mm.nodes[row["id"]] = row
        if os.path.exists(edges_path):
            with open(edges_path, newline="", encoding="utf-8-sig") as f:
                for row in csv.DictReader(f):
                    src = row.pop("Source", row.pop("source", ""))
                    tgt = row.pop("Target", row.pop("target", ""))
                    row.pop("Type", None)
                    rel = row.pop("relation", "") or REL_CHILD
                    extra = {k: v for k, v in row.items() if k is not None and v != ""}
                    mm.add_edge(src, tgt, rel, **extra)
        if not any(n.get("x") or n.get("y") for n in mm.nodes.values()):
            mm.layout(fresh=True)
        return mm

    def export_graphml(self, path):
        ns = "http://graphml.graphdrawing.org/xmlns"
        root = ET.Element("graphml", {"xmlns": ns})
        fields = [f for f in self._node_fields() if f != "id"] + ["depth"]
        for f in fields:
            typ = "double" if f in FLOAT_FIELDS else "int" if f == "depth" else "string"
            ET.SubElement(root, "key", {"id": "n_" + f, "for": "node",
                                        "attr.name": f, "attr.type": typ})
        efields = ["relation"] + self._edge_fields()
        for f in efields:
            ET.SubElement(root, "key", {"id": "e_" + f, "for": "edge",
                                        "attr.name": f, "attr.type": "string"})
        g = ET.SubElement(root, "graph", {"id": "G", "edgedefault": "directed"})
        for n in self.nodes.values():
            el = ET.SubElement(g, "node", {"id": n["id"]})
            vals = dict(n, depth=self.depth(n["id"]))
            for f in fields:
                v = vals.get(f, "")
                if v != "" and v is not None:
                    ET.SubElement(el, "data", {"key": "n_" + f}).text = str(v)
        for i, e in enumerate(self.edges):
            el = ET.SubElement(g, "edge", {"id": f"e{i}", "source": e["source"], "target": e["target"]})
            for f in efields:
                v = e.get(f, "")
                if v != "":
                    ET.SubElement(el, "data", {"key": "e_" + f}).text = str(v)
        tree = ET.ElementTree(root)
        ET.indent(tree)
        tree.write(path, encoding="utf-8", xml_declaration=True)
        return path

    def to_networkx(self):
        import networkx as nx
        G = nx.DiGraph()
        for n in self.nodes.values():
            G.add_node(n["id"], **{k: v for k, v in n.items() if k != "id"},
                       depth=self.depth(n["id"]))
        for e in self.edges:
            G.add_edge(e["source"], e["target"], **{k: v for k, v in e.items()
                                                     if k not in ("source", "target")})
        return G

    # ---------- 簡易集計 ----------
    def stats_text(self):
        lines = [f"ノード数: {len(self.nodes)}  /  ツリー辺: "
                 f"{sum(e['relation'] == REL_CHILD for e in self.edges)}  /  関連リンク: "
                 f"{sum(e['relation'] == REL_LINK for e in self.edges)}"]
        kc, sc = {k: 0 for k in KINDS}, {s: 0 for s in STATUSES}
        for n in self.nodes.values():
            kc[n.get("kind")] = kc.get(n.get("kind"), 0) + 1
            sc[n.get("status")] = sc.get(n.get("status"), 0) + 1
        lines.append("種類: " + "  ".join(f"{KINDS.get(k, k)} {v}" for k, v in kc.items()))
        lines.append("状態: " + "  ".join(f"{STATUSES.get(k, k)} {v}" for k, v in sc.items()))
        cats = {}
        for n in self.nodes.values():
            k_ = self.category_of(n["id"])
            cats[k_] = cats.get(k_, 0) + 1
        lines.append("カテゴリ: " + "  ".join(f"{k} {v}" for k, v in sorted(cats.items())))
        if self.nodes:
            lines.append(f"最大の深さ: {max(self.depth(n) for n in self.nodes)}")
        cs = completion_stats(self)
        lines.append("")
        lines.append("完了タスク統計（全期間・カテゴリ別）:")
        for cat in sorted(k for k in cs if k != "全体") + ["全体"]:
            r = cs[cat]
            line = f"  {cat}: 完了 {r['done']}/{r['done'] + r['todo']} ({_pct(r['done'], r['done'] + r['todo'])})"
            if r["rtot"]:
                line += f"  定期 {r['rdone']}/{r['rtot']} ({_pct(r['rdone'], r['rtot'])})"
            lines.append(line)
        lines.append("")
        lines.append("最上位ごとの進捗（配下タスクの完了数/総数）:")
        for r in self.roots():
            d, t = self.progress(r)
            pct = f"{d / t * 100:.0f}%" if t else "-"
            lines.append(f"  {self.nodes[r].get('label', '')}: {d}/{t} ({pct})")
        today = datetime.date.today().isoformat()
        overdue = [n for n in self.nodes.values()
                   if n.get("due") and n.get("due") < today and n.get("status") != "done"]
        if overdue:
            lines.append("")
            lines.append("期限切れ: " + ", ".join(n.get("label", "") for n in overdue))
        return "\n".join(lines)


TaskMap = MindNavi   # 旧名（TaskMap）との互換用
MindMap = MindNavi   # v0.1 との互換用


# =====================================================================
# 予定（カレンダー）と Google カレンダー同期
#   ノードの属性: sched_date (YYYY-MM-DD), sched_start / sched_end (HH:MM)
#   同期用:       gcal_id（Google の予定ID）, gcal_updated（最後に見た更新時刻）, gcal_hash
# =====================================================================
def _hm(s):
    """'HH:MM' → 分。不正なら None"""
    try:
        h, m = s.split(":")
        v = int(h) * 60 + int(m)
        return v if 0 <= v <= 24 * 60 else None
    except (AttributeError, ValueError):
        return None


def _fmt_hm(m):
    m = max(0, min(24 * 60, int(m)))
    return f"{m // 60:02d}:{m % 60:02d}"


def sched_of(n):
    """(date, 開始分, 終了分) か None"""
    d, a, b = _date(n.get("sched_date")), _hm(n.get("sched_start")), _hm(n.get("sched_end"))
    if not d or a is None or b is None:
        return None
    return d, a, max(b, a + CAL_SNAP)


def untimed(n):
    """日付（と繰り返し）はあるが時刻がない＝カレンダーの「終日」欄に出すもの"""
    return bool(_date(n.get("sched_date"))) and sched_of(n) is None


def has_sched(n):
    return bool(sched_of(n) or untimed(n))


def clear_sched(n):
    for k in ("sched_date", "sched_start", "sched_end"):
        n.pop(k, None)


def _local_dt(d, minutes):
    """日付＋分 → この PC のタイムゾーン付き datetime"""
    base = datetime.datetime.combine(d, datetime.time()) + datetime.timedelta(minutes=minutes)
    return base.astimezone()


def _sched_hash(n):
    sc = sched_of(n)
    key = "|".join([n.get("label", ""), n.get("status", ""), n.get("note", ""),
                    "" if not sc else f"{sc[0]}|{sc[1]}|{sc[2]}",
                    json.dumps(n.get("repeat"), sort_keys=True), ",".join(n.get("exdates", [])),
                    json.dumps(n.get("alarm"), sort_keys=True)])
    return format(zlib.crc32(key.encode("utf-8")), "08x")


# ---- 繰り返し（repeat = {freq: daily/weekdays/weekly/monthly, interval, byweekday:[0-6], until}） ----
ROUTINE_CHOICES = {"": "なし", "daily": "デイリー（毎日）", "weekdays": "デイリー（平日）",
                   "weekly": "ウィークリー（毎週）", "monthly": "マンスリー（毎月）"}
REPEAT_NAMES = {"daily": "毎日", "weekdays": "平日", "weekly": "毎週", "monthly": "毎月"}


def repeat_text(n):
    rp = n.get("repeat") or {}
    f = rp.get("freq")
    if not f:
        return ""
    iv = int(rp.get("interval", 1) or 1)
    if f == "weekly":
        t = ("毎週" if iv == 1 else f"{iv}週ごと") + "・".join("月火水木金土日"[w] for w in rp.get("byweekday", []))
    elif f == "daily":
        t = "毎日" if iv == 1 else f"{iv}日ごと"
    elif f == "monthly":
        t = "毎月" if iv == 1 else f"{iv}か月ごと"
    else:
        t = "平日"
    return t + (f"（〜{rp['until'][5:].replace('-', '/')}）" if rp.get("until") else "")


# =====================================================================
# 講義進行表（Excel）の読み取り：追加のライブラリなしで .xlsx を読む
# =====================================================================
PLACE_NONE = "（未分類・あとで決める）"   # タスクの設定「マップの分類」で、ツリーにまだ入れないとき
LECTURE_PATH = os.path.expanduser("~/.taskmap_lectures.json")   # 旧版の保存先（取り込み元。旧名のまま）
LECTURE_COLOR = "#7048e8"   # 集計での講義（カテゴリ「Lecture」＝マップの Lecture のまとめ）の色
LECTURE_ROOT = "Lecture"                              # マップの親ノード名
LECTURE_DEEP = "#5f3dc4"                              # カレンダーでの講義の色（濃い紫）
# 講義の既定アラーム：前日17:00・当日8:45・1時間前・15分前（15分前は警告音）
LECTURE_ALARMS = [{"day": -1, "at": "17:00"}, {"day": 0, "at": "08:45"}, {"before": 60}, {"before": 15, "sound": True}]
ALARM_SOUND_SECS = 20   # 警告音は20秒で自動で止める
LECTURE_PERIODS = [("09:00", "10:30"), ("10:45", "12:15"), ("13:15", "14:45"), ("15:00", "16:30"),
                   ("16:45", "18:15"), ("18:30", "20:00"), ("20:15", "21:45")]   # 5〜7限は予備
_XNS = "{http://schemas.openxmlformats.org/spreadsheetml/2006/main}"
_RNS = "{http://schemas.openxmlformats.org/officeDocument/2006/relationships}"


def _xl_ref(ref):
    """「AB12」→ (12, 28)"""
    m = re.match(r"([A-Z]+)(\d+)", ref)
    col = 0
    for ch in m.group(1):
        col = col * 26 + ord(ch) - 64
    return int(m.group(2)), col


def read_xlsx(path):
    """.xlsx の各シートを [{"name", "cells": {(行, 列): 値}, "merged": [(r1, c1, r2, c2)]}] で返す"""
    with zipfile.ZipFile(path) as z:
        names = set(z.namelist())
        shared = []
        if "xl/sharedStrings.xml" in names:
            for si in ET.fromstring(z.read("xl/sharedStrings.xml")).iter(_XNS + "si"):
                shared.append("".join(t.text or "" for t in si.iter(_XNS + "t") if not _in_phonetic(si, t)))
        wb = ET.fromstring(z.read("xl/workbook.xml"))
        rels = {}
        if "xl/_rels/workbook.xml.rels" in names:
            for r_ in ET.fromstring(z.read("xl/_rels/workbook.xml.rels")):
                rels[r_.get("Id")] = r_.get("Target")
        out = []
        for sh in wb.iter(_XNS + "sheet"):
            tgt = rels.get(sh.get(_RNS + "id"), "")
            tgt = tgt.lstrip("/")
            tgt = tgt if tgt.startswith("xl/") else "xl/" + tgt
            if tgt not in names:
                continue
            root = ET.fromstring(z.read(tgt))
            cells = {}
            for c_ in root.iter(_XNS + "c"):
                t = c_.get("t")
                v = c_.find(_XNS + "v")
                if t == "s" and v is not None:
                    val = shared[int(v.text)]
                elif t == "inlineStr":
                    val = "".join(x.text or "" for x in c_.iter(_XNS + "t"))
                elif v is None or v.text is None:
                    continue
                elif t in ("str", "e"):
                    val = v.text
                elif t == "b":
                    val = v.text == "1"
                else:
                    try:
                        f_ = float(v.text)
                        val = int(f_) if f_.is_integer() else f_
                    except ValueError:
                        val = v.text
                if val == "" or val is None:
                    continue
                cells[_xl_ref(c_.get("r"))] = val
            merged = []
            for m in root.iter(_XNS + "mergeCell"):
                a, b = m.get("ref").split(":") if ":" in m.get("ref") else (m.get("ref"), m.get("ref"))
                (r1, c1), (r2, c2) = _xl_ref(a), _xl_ref(b)
                merged.append((r1, c1, r2, c2))
            out.append({"name": sh.get("name"), "cells": cells, "merged": merged})
        return out


def _in_phonetic(si, t):
    """ふりがな（rPh）の文字は除く"""
    for ph in si.iter(_XNS + "rPh"):
        if any(x is t for x in ph.iter(_XNS + "t")):
            return True
    return False


def _norm(s):
    """比べるための正規化：全角半角をそろえ、空白をすべて除く"""
    return re.sub(r"\s+", "", unicodedata.normalize("NFKC", str(s or "")))


def lecture_class(n):
    """講義のクラス "A" / "B" / "AB"（取り込み時に保存。古いデータはメモの「クラスA・B」から）"""
    c = n.get("lecture_class")
    if c is None:
        m = re.search(r"クラス([AB](?:・[AB])?)", str(n.get("note") or ""))
        c = "".join(sorted(m.group(1).replace("・", ""))) if m else ""
    return c


def parse_lecture_sheet(sheet, who, fiscal_year=None):
    """講義進行表のシートから、who（例「石田 隆志」）の講義を取り出す。
    表の形：A列＝曜日、B列＝時限、見出し行（B列「時限目」）に日にち、1週＝2列（Aクラス・Bクラス）、
    1コマ＝2行（上＝科目、下＝「回.担当者」）。月は上の「◯月」の見出しと曜日から決める。
    戻り値：[{date, period, subject, no, classes, grade, text}]"""
    raw = sheet["cells"]
    cells = dict(raw)
    for r1, c1, r2, c2 in sheet["merged"]:   # 結合セルは全部に同じ値
        v = raw.get((r1, c1))
        if v is None:
            continue
        for r in range(r1, r2 + 1):
            for c in range(c1, c2 + 1):
                cells[(r, c)] = v
    q = _norm(who)
    if not q:
        return []
    texts = [str(v) for (r, c), v in sorted(raw.items()) if r <= 3 and isinstance(v, str)]
    title = " ".join(texts)
    fy = fiscal_year
    m = re.search(r"(\d{4})\s*年度", title)
    if not fy and m:
        fy = int(m.group(1))
    if not fy:
        m = re.match(r"(\d{4})(\d{2})", sheet.get("name") or "")
        if m:
            fy = int(m.group(1)) - (1 if int(m.group(2)) < 4 else 0)
    if not fy:
        fy = datetime.date.today().year - (1 if datetime.date.today().month < 4 else 0)
    m = re.search(r"([0-9０-９]+)\s*年\s*[（(]", title) or re.search(r"学科\s*([0-9０-９]+)\s*年", title)
    grade = (unicodedata.normalize("NFKC", m.group(1)) + "年") if m else ""
    m = re.search(r"(\S+学科)", title)
    dept = m.group(1) if m else ""
    # 月の見出し（「4月」など）
    months = sorted((c, int(unicodedata.normalize("NFKC", v)[:-1])) for (r, c), v in raw.items()
                    if r <= 6 and isinstance(v, str) and re.fullmatch(r"[0-9０-９]{1,2}\s*月", v.strip()))
    if not months:
        return []
    WD = "月火水木金土日"
    blocks = sorted((r, WD.index(str(raw[(r, 1)]).strip()[0])) for (r, c), v in raw.items()
                    if c == 2 and _norm(v) == "時限目" and str(raw.get((r, 1), "")).strip()[:1] in WD)
    last_row = max((r for r, c in raw), default=0)
    found = {}
    for bi, (hr, wd) in enumerate(blocks):
        end = blocks[bi + 1][0] if bi + 1 < len(blocks) else last_row + 1
        heads = sorted((c, v) for (r, c), v in raw.items() if r == hr and c >= 3 and isinstance(v, int) and 1 <= v <= 31)
        if not heads:
            continue
        spans = []
        for i, (hc, day) in enumerate(heads):
            nxt = heads[i + 1][0] if i + 1 < len(heads) else hc + 2
            spans.append((hc, day, list(range(hc, hc + max(1, min(2, nxt - hc))))))
        r = hr + 1
        while r < end:
            per = raw.get((r, 2))
            if not isinstance(per, int):
                r += 1
                continue
            for hc, day, cols in spans:
                mlab = max((mo for c, mo in months if c <= hc), default=months[0][1])
                dt = None
                for mo in (mlab, mlab + 1, mlab - 1):
                    mo2 = (mo - 1) % 12 + 1
                    yr = fy if mo2 >= 4 else fy + 1
                    try:
                        cand = datetime.date(yr, mo2, day)
                    except ValueError:
                        continue
                    if cand.weekday() == wd:
                        dt = cand
                        break
                if dt is None:
                    continue
                for k, col in enumerate(cols):
                    subj = str(cells.get((r, col), "") or "").strip()
                    teach = str(cells.get((r + 1, col), "") or "").strip() if r + 1 < end else ""
                    no, subject = None, subj
                    if q in _norm(teach) and teach != subj:
                        mm_ = re.match(r"\s*([0-9０-９]+)\s*[.．、]", teach)
                        no = int(unicodedata.normalize("NFKC", mm_.group(1))) if mm_ else None
                    elif q in _norm(subj):
                        subject = re.sub(r"[/／\s]*" + r"\s*".join(map(re.escape, re.sub(r"\s+", "", who))) + r"(先生)?", "",
                                         subj).strip(" 　/／") or subj
                    else:
                        continue
                    key = (dt, per, subject)
                    it = found.setdefault(key, {"date": dt, "period": per, "subject": subject, "no": no,
                                                "classes": [], "grade": grade, "dept": dept,
                                                "text": (subj + " / " + teach).strip(" /")})
                    cl = "AB"[k] if len(cols) == 2 else ""
                    if cl and cl not in it["classes"]:
                        it["classes"].append(cl)
            r += 2
    return sorted(found.values(), key=lambda x: (x["date"], x["period"]))


# =====================================================================
# 勤務表（PDF）の読み取り：pdfplumber（位置で読む）→ pypdf（文字の並びで読む）
# =====================================================================
SHIFT_PIP = "pip install pdfplumber"
SHIFT_CONF = os.path.expanduser("~/.taskmap_shift.json")   # 旧版の保存先（取り込み元。旧名のまま）
SHIFT_NORMAL = "H8"   # ふだんの勤務。これ以外は強調して前もって知らせる
SHIFT_ALERT_DAYS = 3
SHIFT_STRONG = "N8,F8"
SPLIT_HINT_NODES = 50    # マップのノードがこれを超える（または画面に入りきらない）と分割候補を☆で示す   # 特に目立たせる勤務（分かりづらいもの）


SHIFT_OFF_NAMES = {"法休": "法定休日", "所休": "所定休日", "年": "年休", "年休": "年休", "夏": "夏季休暇",
                   "張": "出張", "特": "特別休暇", "代": "代休", "振": "振替休日", "病": "病気休暇", "欠": "欠勤",
                   "リ": "リフレッシュ休暇", "研": "研修"}
LEAVE_CODES = ("年", "年休")              # 年休：届のリマインダーを出す
LEAVE_REMIND_DAYS = (7, 6, 5, 4, 3, 2, 1, 0)   # 年休届：1週間前から毎朝（チェックするまで）
LEAVE_HOURLY_DAYS = 3                           # 3日前からは1時間ごとにも知らせる


def shift_name(code):
    """記号 → 表示名（H8 などの勤務はそのまま）"""
    return SHIFT_OFF_NAMES.get(code, code)


def shift_kind(code):
    """work（勤務）／ off（休み）／ other（出張・研修など）"""
    if _is_shift_code(code):
        return "work"
    if code in ("張", "研"):
        return "other"
    return "off"


def _is_shift_code(t):
    """シフトの記号か（H8・N8 など英字＋数字。全角も可）"""
    return bool(re.fullmatch(r"[A-Za-z]{1,3}\d{0,2}", unicodedata.normalize("NFKC", t or "").strip()))


def _shift_ym(text, path):
    """勤務表の年・月：本文の「年 2026」「月 11」→ ファイル名「2026.11月」の順に探す"""
    y = m = None
    t = unicodedata.normalize("NFKC", text or "")
    a = re.search(r"年\s*(20\d{2})", t) or re.search(r"(20\d{2})\s*年", t)
    if a:
        y = int(a.group(1))
    b = re.search(r"(?<![0-9])月\s*(1[0-2]|0?[1-9])(?![0-9日])", t) or re.search(r"(1[0-2]|0?[1-9])\s*月(?![0-9]*日)", t)
    if b:
        m = int(b.group(1))
    f = unicodedata.normalize("NFKC", os.path.basename(path))
    c = re.search(r"(20\d{2})\s*[.\-_/年]\s*(1[0-2]|0?[1-9])(?![0-9])", f)
    if c:
        y, m = y or int(c.group(1)), int(c.group(2))   # ファイル名の月を優先（本文の「月」は見出しと紛れやすい）
    return y, m


def _shift_fix_month(y, m, ndays, wd1):
    """日数と1日の曜日に合う月を選ぶ（読み取った月が合わなければ直す）"""
    if wd1 is None or not y:
        return y, m
    WD = "月火水木金土日"
    cands = []
    for yy in (y, y + 1, y - 1):
        for mm_ in range(1, 13):
            d1 = datetime.date(yy, mm_, 1)
            n_ = ((d1.replace(day=28) + datetime.timedelta(days=4)).replace(day=1) - d1).days
            if WD[d1.weekday()] == wd1 and n_ == ndays:
                cands.append((yy, mm_))
    if (y, m) in cands or not cands:
        return y, m
    same = [c_ for c_ in cands if c_[0] == y]
    return (same or cands)[0]


def parse_shift_pdf(path, who):
    """勤務表 PDF から who の行の記号を日ごとに取り出す。戻り値 (年, 月, {日: 記号}, 読み方)"""
    q = _norm(who)
    try:
        import pdfplumber
    except ImportError:
        pdfplumber = None
    if pdfplumber is not None:
        with pdfplumber.open(path) as pdf:
            for page in pdf.pages:
                words = page.extract_words(use_text_flow=False)
                text = page.extract_text() or ""
                lines = {}
                for w_ in words:
                    lines.setdefault(round(w_["top"]), []).append(w_)
                # 日にちの見出し：1, 2, 3 … と並ぶ行
                cols = None
                for top, ws in sorted(lines.items()):
                    nums = sorted((w_ for w_ in ws if re.fullmatch(r"\d{1,2}", w_["text"])), key=lambda w_: w_["x0"])
                    seq = [int(w_["text"]) for w_ in nums]
                    if len(seq) >= 28 and seq[:28] == list(range(1, 29)):
                        cols = [((w_["x0"] + w_["x1"]) / 2, int(w_["text"])) for w_ in nums]
                        head_top = top
                        break
                if not cols:
                    continue
                pitch = (cols[-1][0] - cols[0][0]) / max(1, len(cols) - 1)
                # 名前の行
                name_top = None
                for top, ws in sorted(lines.items()):
                    if top > head_top and q in _norm("".join(w_["text"] for w_ in sorted(ws, key=lambda w_: w_["x0"]))):
                        name_top = top
                        break
                if name_top is None:
                    continue
                tops = sorted(t_ for t_, ws in lines.items() if t_ > head_top and any(re.fullmatch(r"\d{6,}", w_["text"]) for w_ in ws))
                gaps = [b - a for a, b in zip(tops, tops[1:]) if b - a > 8]
                rowh = sorted(gaps)[len(gaps) // 2] if gaps else 28
                lo, hi = name_top - rowh * 0.35, name_top + rowh * 0.65
                cells = {}
                for ch in sorted(page.chars, key=lambda c_: c_["x0"]):
                    if not (lo <= ch["top"] <= hi) or not ch["text"].strip():
                        continue
                    cx = (ch["x0"] + ch["x1"]) / 2
                    x_, day = min(cols, key=lambda c_: abs(c_[0] - cx))
                    if abs(x_ - cx) <= pitch * 0.55:
                        cells[day] = cells.get(day, "") + ch["text"]
                y, m = _shift_ym(text, path)
                wd1 = None   # 1日の曜日（見出しのすぐ下の行）
                for top, ws in sorted(lines.items()):
                    if head_top < top <= head_top + rowh:
                        for w_ in ws:
                            if w_["text"][:1] in "月火水木金土日" and abs((w_["x0"] + w_["x1"]) / 2 - cols[0][0]) <= pitch * 0.55:
                                wd1 = w_["text"][0]
                        if wd1:
                            break
                y, m = _shift_fix_month(y, m, len(cols), wd1)
                return y, m, {d: unicodedata.normalize("NFKC", v).strip() for d, v in cells.items()}, "pdfplumber"
        raise ValueError(f"「{who}」の行が見つかりませんでした")
    try:
        from pypdf import PdfReader
    except ImportError:
        raise RuntimeError("PDF を読むには追加のライブラリが必要です。\nコマンドプロンプトで次を実行してください：\n" + SHIFT_PIP)
    text = "\n".join((pg.extract_text() or "") for pg in PdfReader(path).pages)
    y, m = _shift_ym(text, path)
    hd = re.search(r"(?<![0-9])1\s+2\s+3\s+4\s+5(?:\s+\d{1,2})+", text)
    wd = re.search(r"((?:[日月火水木金土]\s*){28,31})", text)
    if hd and wd:
        y, m = _shift_fix_month(y, m, len(hd.group(0).split()), wd.group(1).strip()[0])
    for line in text.splitlines():
        if q in _norm(line):
            nl = unicodedata.normalize("NFKC", line)
            i = nl.replace("　", " ")
            parts = re.split(r"\s+", i.strip())
            # 名前の後ろを記号に分ける（「所休所休」のようにくっついたものも分ける）
            k, acc = 0, ""
            while k < len(parts) and q not in _norm(acc):
                acc += parts[k]
                k += 1
            toks = re.findall(r"[A-Za-z]+\d*|[^\sA-Za-z\d]休|[^\sA-Za-z\d]", " ".join(parts[k:]))
            return y, m, {d + 1: t for d, t in enumerate(toks)}, "pypdf"
    raise ValueError(f"「{who}」の行が見つかりませんでした")


# =====================================================================
# 日本の祝日（内閣府の規定どおりに計算。春分・秋分は近似式：1980〜2099年）
# =====================================================================
_JP_HOL_CACHE = {}


def jp_holidays(year):
    """{日付: 祝日名}（振替休日・国民の休日を含む）"""
    if year in _JP_HOL_CACHE:
        return _JP_HOL_CACHE[year]
    D = datetime.date

    def nth_monday(m, k):
        d = D(year, m, 1)
        return d + datetime.timedelta(days=(7 - d.weekday()) % 7 + 7 * (k - 1))
    h = {D(year, 1, 1): "元日", nth_monday(1, 2): "成人の日", D(year, 2, 11): "建国記念の日",
         D(year, 4, 29): "昭和の日", D(year, 5, 3): "憲法記念日", D(year, 5, 4): "みどりの日",
         D(year, 5, 5): "こどもの日", D(year, 11, 3): "文化の日", D(year, 11, 23): "勤労感謝の日"}
    if year >= 2020:
        h[D(year, 2, 23)] = "天皇誕生日"
    elif 1989 <= year <= 2018:
        h[D(year, 12, 23)] = "天皇誕生日"
    if 1980 <= year <= 2099:
        y_ = year - 1980
        h[D(year, 3, int(20.8431 + 0.242194 * y_ - y_ // 4))] = "春分の日"
        h[D(year, 9, int(23.2488 + 0.242194 * y_ - y_ // 4))] = "秋分の日"
    special = {2020: {"海の日": D(2020, 7, 23), "スポーツの日": D(2020, 7, 24), "山の日": D(2020, 8, 10)},
               2021: {"海の日": D(2021, 7, 22), "スポーツの日": D(2021, 7, 23), "山の日": D(2021, 8, 8)}}
    sp = special.get(year, {})
    h[sp.get("海の日", nth_monday(7, 3))] = "海の日"
    if year >= 2016:
        h[sp.get("山の日", D(year, 8, 11))] = "山の日"
    h[nth_monday(9, 3)] = "敬老の日"
    h[sp.get("スポーツの日", nth_monday(10, 2))] = "スポーツの日" if year >= 2020 else "体育の日"
    if year == 2019:
        h.update({D(2019, 4, 30): "国民の休日", D(2019, 5, 1): "天皇の即位の日", D(2019, 5, 2): "国民の休日",
                  D(2019, 10, 22): "即位礼正殿の儀"})
    # 国民の休日：祝日にはさまれた平日
    for d in sorted(h):
        n2 = d + datetime.timedelta(days=2)
        mid = d + datetime.timedelta(days=1)
        if n2 in h and mid not in h and mid.weekday() != 6:
            h[mid] = "国民の休日"
    # 振替休日：日曜の祝日のあと、最初の祝日でない日
    for d in sorted(k for k in h if k.weekday() == 6):
        nd = d + datetime.timedelta(days=1)
        while nd in h:
            nd += datetime.timedelta(days=1)
        h[nd] = "振替休日"
    _JP_HOL_CACHE[year] = h
    return h


def jp_holiday(d):
    return jp_holidays(d.year).get(d)


def sched_start_dt(n):
    """予定の開始の日時（時刻なしはその日の始まり）。繰り返し・日付なしは None"""
    if n.get("repeat"):
        return None
    d = _date(n.get("sched_date"))
    if not d:
        return None
    sc = sched_of(n)
    return datetime.datetime.combine(d, datetime.time()) + datetime.timedelta(minutes=sc[1] if sc else 0)


def note_postpone(n, new_date, new_start=None, new_end=None):
    """延期の判定：終了時刻がまだ来ていない（今より後の）タスクを動かしたとき、開始時刻が今をまたいで
    今以降になったら「延期」を1回数える。それ以外の移動（終わったタスク・まだ始まっていないタスクの移動など）は延期にしない。
    時刻なしのタスクは、その日の 0:00〜24:00 として判定する"""
    if n.get("status") == "done" or n.get("kind") == "event" or new_date is None:
        return False
    d0 = _date(n.get("sched_date"))
    if d0 is None:
        return False
    sc = sched_of(n)
    nowdt = datetime.datetime.now()
    day0 = datetime.datetime.combine(d0, datetime.time())
    old_start = day0 + datetime.timedelta(minutes=sc[1] if sc else 0)
    old_end = day0 + datetime.timedelta(minutes=sc[2] if sc else 24 * 60)
    if old_end <= nowdt:   # もう終わっている → 延期ではない
        return False
    if old_start >= nowdt:   # まだ始まっていない → 開始時刻は今をまたがない
        return False
    new_start_dt = datetime.datetime.combine(new_date, datetime.time()) + datetime.timedelta(minutes=new_start or 0)
    if new_start_dt < nowdt:   # 開始時刻が今より前のまま → 延期ではない
        return False
    n["postpone"] = int(n.get("postpone") or 0) + 1
    n.setdefault("postpone_log", []).append({"at": nowdt.isoformat(timespec="minutes"),
                                             "from": n.get("sched_date"), "to": new_date.isoformat()})
    return True


def postpone_text(n):
    k = int(n.get("postpone") or 0)
    return f"延期{k}回" if k else ""


def reuse_rep(n):
    """繰り返しタスクの「毎日・毎週など」の回も実施回数に数えるか。
    時刻を決めないデイリー（時刻なしの繰り返し）は例外で、これまでどおりのデイリータスクとして扱う"""
    return bool(n.get("repeat") and n.get("sched_date") and n.get("sched_start"))


def reuse_count(n, d0=None, d1=None):
    """繰り返しタスクの実施回数：カレンダーに置いた回＋毎日・毎週などの繰り返しの回のうち、チェックしたもの
    （d0〜d1 を渡すとその期間だけ）"""
    def inside(ds):
        d = _date(ds)
        return d is not None and (d0 is None or d0 <= d) and (d1 is None or d <= d1)
    k = sum(1 for se in n.get("sessions") or [] if se.get("done") and inside(se.get("date")))
    if reuse_rep(n):
        base = _date(n["sched_date"])
        occ = {d.isoformat() for d in occurrences(n, d0 or base, d1 or datetime.date.today() + datetime.timedelta(days=3660))}
        k += sum(1 for ds in n.get("done_dates", []) if ds in occ)
    return k


def reuse_total(n, d0=None, d1=None):
    """繰り返しタスクの設定回数：カレンダーに置いた回＋繰り返しの回（期間を渡さなければ今日まで）"""
    def inside(ds):
        d = _date(ds)
        return d is not None and (d0 is None or d0 <= d) and (d1 is None or d <= d1)
    t = sum(1 for se in n.get("sessions") or [] if inside(se.get("date")))
    if reuse_rep(n):
        base = _date(n["sched_date"])
        t += len(occurrences(n, d0 or base, d1 or max(datetime.date.today(), base)))
    return t


def occurrences(n, d0, d1):
    """d0〜d1 の間で予定がある日付の一覧（繰り返しを展開、除外日を除く）"""
    base = _date(n.get("sched_date"))
    if not base:
        return []
    rp = n.get("repeat") or {}
    f = rp.get("freq")
    if not f:
        return [base] if d0 <= base <= d1 else []
    end = min(d1, _date(rp.get("until")) or d1)
    iv = max(1, int(rp.get("interval", 1) or 1))
    ex = set(n.get("exdates", []))
    wds = set(rp.get("byweekday") or [base.weekday()])
    mon = lambda d: d - datetime.timedelta(days=d.weekday())
    out, d = [], max(d0, base)
    while d <= end:
        if f == "daily":
            ok = (d - base).days % iv == 0
        elif f == "weekdays":
            ok = d.weekday() < 5
        elif f == "weekly":
            ok = d.weekday() in wds and ((mon(d) - mon(base)).days // 7) % iv == 0
        elif f == "monthly":
            ok = d.day == base.day and ((d.year - base.year) * 12 + d.month - base.month) % iv == 0
        else:
            ok = d == base
        if ok and d.isoformat() not in ex:
            out.append(d)
        d += datetime.timedelta(days=1)
    return out


def dark(color, t):
    """色を黒の方へ（t＝0〜1）"""
    return mix(color, t, "#000000")


