def task_quad(n):
    """タスクの4象限（指標が未入力なら None）。指標は小さいほど高い（1位・2位…）"""
    if not (n.get("imp") and n.get("need")):
        return None
    hi_n, hi_i = int(n["need"]) <= IDX_HIGH, int(n["imp"]) <= IDX_HIGH
    return "core" if hi_n and hi_i else "infra" if hi_n else "ambition" if hi_i else "bull"


