def alarm_fire_times(n, start):
    """予定の開始日時 start に対するアラームの時刻：[(日時, 警告音, 名前)]"""
    out = []
    al = n.get("alarm")
    if al:
        out.append((start - datetime.timedelta(minutes=int(al.get("before", 15))), bool(al.get("sound")),
                    f"{al.get('before', 15)}分前"))
    for a in n.get("alarms") or []:
        if "at" in a:
            hm = _hm(a["at"])
            if hm is None:
                continue
            day = start.date() + datetime.timedelta(days=int(a.get("day", 0)))
            out.append((datetime.datetime.combine(day, datetime.time()) + datetime.timedelta(minutes=hm),
                        bool(a.get("sound")), ("前日" if a.get("day") == -1 else "当日") + a["at"]))
        else:
            out.append((start - datetime.timedelta(minutes=int(a.get("before", 15))), bool(a.get("sound")),
                        f"{a.get('before', 15)}分前"))
    return out


ROUTINE_TYPES = {"daily": "デイリー", "weekdays": "デイリー", "weekly": "ウィークリー", "monthly": "マンスリー"}


def routine_rate(mm, d0, d1, today=None):
    """定期タスク（繰り返しのあるタスク）の実施率。今日より先の回は数えない。
    戻り値: (予定の回数, 実施した回数, {デイリー/ウィークリー/マンスリー: (回数, 実施)})"""
    today = today or datetime.date.today()
    end = min(d1, today)
    tot = done = 0
    by = {}
    if end < d0:
        return 0, 0, by
    for n in mm.nodes.values():
        rp = n.get("repeat")
        if not rp or n.get("kind") in ("event", "note"):
            continue
        occ = occurrences(n, d0, end)
        dd = set(n.get("done_dates", []))
        t, k = len(occ), sum(1 for d in occ if d.isoformat() in dd)
        tot, done = tot + t, done + k
        key = ROUTINE_TYPES.get(rp.get("freq"), "その他")
        a, b = by.get(key, (0, 0))
        by[key] = (a + t, b + k)
    return tot, done, by


UNCAT = "（未分類）"
ITER_COLOR = "#7048e8"   # 反復タスク（実行回数を数える）の色


def iter_count(n):
    """反復タスクの実施回数（カレンダーで実施チェックを付けた回の数）"""
    return len(set(n.get("done_dates") or []))


def cal_achievement(mm, d0, d1, today=None):
    """カレンダーに置いたタスクの達成率（今日までの回）。予定（イベント）とメモは数えない。
    戻り値: {カテゴリ: (回数, 達成した回数)}、全体は "全体" """
    today = today or datetime.date.today()
    end = min(d1, today)
    out = {"全体": (0, 0)}
    if end < d0:
        return out
    for n in mm.nodes.values():
        if n.get("kind") in ("event", "note") or not (n.get("sched_date") or n.get("sessions")):
            continue
        if n.get("shift_code"):
            continue
        occ = occurrences(n, d0, end)
        if not occ and not n.get("sessions"):
            continue
        try:
            tg = max(1, int(n.get("day_target") or 1)) if (n.get("multi") or int(n.get("day_target") or 1) > 1) else 1
        except (TypeError, ValueError):
            tg = 1
        if tg > 1 or n.get("multi"):   # 1日に何回か実施するタスク：1回の実施を1件として数える
            dc = n.get("day_counts") or {}
            dd = set(n.get("done_dates", []))
            tot_ = tg * len(occ)
            k = sum(min(tg, int(dc.get(d.isoformat(), tg if d.isoformat() in dd else 0))) for d in occ)
        elif n.get("repeat"):
            dd = set(n.get("done_dates", []))
            tot_ = len(occ)
            k = sum(1 for d in occ if d.isoformat() in dd)
        else:
            tot_ = len(occ)
            k = len(occ) if n.get("status") == "done" else 0
        for se in n.get("sessions") or []:   # 続きの時間枠も1件ずつ
            sd = _date(se.get("date"))
            if sd and d0 <= sd <= end:
                tot_ += 1
                k += 1 if se.get("done") else 0
        for cat in (mm.category_of(n["id"]), "全体"):
            a, b = out.get(cat, (0, 0))
            out[cat] = (a + tot_, b + k)
    return out


def done_day(n):
    """完了した日（記録がない古いデータは最終更新日で代用）"""
    return _date((n.get("done_at") or n.get("updated") or "")[:10])


def completion_stats(mm, d0=None, d1=None, star_only=False, today=None):
    """完了タスク統計（カテゴリ別と全体）。
    1回のタスク: 完了＝期間内に完了したもの、未完了＝現在未完了のもの。
    定期タスク : 期間内（今日まで）の予定回数と実施回数。
    戻り値: {カテゴリ: {"done", "todo", "rtot", "rdone", "items": [(完了日, ラベル)]}}、全体は "全体" """
    today = today or datetime.date.today()
    out = {}

    def row(cat):
        return out.setdefault(cat, {"done": 0, "todo": 0, "rtot": 0, "rdone": 0, "items": []})
    for n in mm.nodes.values():
        if n.get("kind") in ("note", "event", "goal") and not n.get("focus"):
            continue
        if n.get("kind") not in ("task", None) and not n.get("focus"):
            continue
        if star_only and not n.get("focus"):
            continue
        cat = mm.category_of(n["id"])
        lab = n.get("label", "")
        rp = n.get("repeat")
        if rp:
            a = d0 or _date(n.get("sched_date")) or today
            b = min(d1 or today, today)
            if b < a:
                continue
            occ = occurrences(n, a, b)
            dd = set(n.get("done_dates", []))
            k = [d for d in occ if d.isoformat() in dd]
            for r in (row(cat), row("全体")):
                r["rtot"] += len(occ)
                r["rdone"] += len(k)
                r["items"].extend((d, lab + "（定期）") for d in k)
            continue
        if n.get("status") == "done":
            d = done_day(n)
            if (d0 and (not d or d < d0)) or (d1 and (not d or d > d1)):
                continue
            for r in (row(cat), row("全体")):
                r["done"] += 1
                r["items"].append((d, lab))
        else:
            for r in (row(cat), row("全体")):
                r["todo"] += 1
    for r in out.values():
        r["items"].sort(key=lambda t: (t[0] or datetime.date.min), reverse=True)
    row("全体")
    return out


def _pct(a, b):
    return f"{a / b * 100:.0f}%" if b else "-"


def rrule_of(n):
    """iCalendar / Google 用の RRULE 文字列（繰り返しなしは None）"""
    rp = n.get("repeat") or {}
    f = rp.get("freq")
    if not f:
        return None
    iv = max(1, int(rp.get("interval", 1) or 1))
    dn = ["MO", "TU", "WE", "TH", "FR", "SA", "SU"]
    if f == "daily":
        r = f"FREQ=DAILY;INTERVAL={iv}"
    elif f == "weekdays":
        r = "FREQ=WEEKLY;BYDAY=MO,TU,WE,TH,FR"
    elif f == "weekly":
        base = _date(n.get("sched_date")) or datetime.date.today()
        r = f"FREQ=WEEKLY;INTERVAL={iv};BYDAY=" + ",".join(dn[w] for w in sorted(rp.get("byweekday")
                                                                                   or [base.weekday()]))
    else:
        r = f"FREQ=MONTHLY;INTERVAL={iv}"
    u = _date(rp.get("until"))
    if u:
        r += ";UNTIL=" + _local_dt(u, 24 * 60 - 1).astimezone(datetime.timezone.utc).strftime("%Y%m%dT%H%M%SZ")
    return "RRULE:" + r


def gcal_event_body(n, map_name="", tz="Asia/Tokyo"):
    if untimed(n):   # 時刻なし → Google では終日の予定
        d = _date(n["sched_date"])
        a = b = None
    else:
        d, a, b = sched_of(n)
    title = ("✔ " if n.get("status") == "done" and not n.get("repeat") else "") + (n.get("label") or "（無題）")
    desc = (n.get("note") or "").strip()
    desc = (desc + "\n\n" if desc else "") + f"Mind_Navi{('：' + map_name) if map_name else ''}"
    if a is None:
        when = {"start": {"date": d.isoformat()},
                "end": {"date": (d + datetime.timedelta(days=1)).isoformat()}}
    else:
        when = {"start": {"dateTime": _local_dt(d, a).isoformat(), "timeZone": tz},
                "end": {"dateTime": _local_dt(d, b).isoformat(), "timeZone": tz}}
    body = {"summary": title, "description": desc, **when,
            "extendedProperties": {"private": {"taskmap_id": n["id"]}}}   # キー名は旧名のまま（同期済みの予定と照合するため変えない）
    al = n.get("alarm")
    if al and a is not None:   # アラーム → Google の通知（ポップアップ）
        body["reminders"] = {"useDefault": False,
                             "overrides": [{"method": "popup", "minutes": int(al.get("before", 15))}]}
    rr = rrule_of(n)
    if rr:   # 繰り返し（除外した回は EXDATE）
        rec = [rr]
        for x in n.get("exdates", []):
            xd = _date(x)
            if xd and a is None:
                rec.append("EXDATE;VALUE=DATE:" + xd.strftime("%Y%m%d"))
            elif xd:
                rec.append(f"EXDATE;TZID={tz}:" + (datetime.datetime.combine(xd, datetime.time())
                                                   + datetime.timedelta(minutes=a)).strftime("%Y%m%dT%H%M%S"))
        body["recurrence"] = rec
    return body


def _apply_remote(n, ev):
    """Google 側で変更された日時・タイトルを取り込む"""
    if "date" in ev.get("start", {}) and "dateTime" not in ev.get("start", {}):   # 終日の予定
        if _date(ev["start"]["date"]):
            n["sched_date"] = ev["start"]["date"]
            n.pop("sched_start", None)
            n.pop("sched_end", None)
    try:
        st = datetime.datetime.fromisoformat(ev["start"]["dateTime"].replace("Z", "+00:00")).astimezone()
        en = datetime.datetime.fromisoformat(ev["end"]["dateTime"].replace("Z", "+00:00")).astimezone()
        n["sched_date"] = st.date().isoformat()
        n["sched_start"] = _fmt_hm(st.hour * 60 + st.minute)
        n["sched_end"] = _fmt_hm(24 * 60 if en.date() > st.date() else en.hour * 60 + en.minute)
    except (KeyError, ValueError, TypeError):
        pass   # 終日予定などは日時を取り込まない
    title = (ev.get("summary") or "").strip()
    if title.startswith("✔ "):
        title = title[2:]
    if title:
        n["label"] = title


def gcal_sync(mm, service, calendar_id="primary", map_name="", tz="Asia/Tokyo"):
    """Mind_Navi ⇔ Google カレンダーの同期。
    ・日時を設定したタスク → Google に作成 / 更新
    ・予定を外した・削除したタスク → Google から削除
    ・Google 側だけで変更された日時・タイトル → Mind_Navi に取り込む（両方変更ならMind_Navi優先）
    ・Google 側で削除された予定 → Mind_Navi の予定も外す"""
    ev_api = service.events()
    st = {"created": 0, "updated": 0, "pulled": 0, "deleted": 0, "cleared": 0}
    alive = {n.get("gcal_id") for n in mm.nodes.values() if n.get("gcal_id")}

    def gone(err):
        code = getattr(getattr(err, "resp", None), "status", None)
        return str(code) in ("404", "410")

    for eid in mm.view.get("gcal_trash", []):
        if eid in alive:      # 元に戻すで復活したもの
            continue
        try:
            ev_api.delete(calendarId=calendar_id, eventId=eid).execute()
            st["deleted"] += 1
        except Exception as err:
            if not gone(err):
                raise
    mm.view["gcal_trash"] = []
    for n in mm.nodes.values():
        eid = n.get("gcal_id")
        if not has_sched(n):
            if eid:
                try:
                    ev_api.delete(calendarId=calendar_id, eventId=eid).execute()
                except Exception as err:
                    if not gone(err):
                        raise
                for k in ("gcal_id", "gcal_updated", "gcal_hash"):
                    n.pop(k, None)
                st["deleted"] += 1
            continue
        h = _sched_hash(n)
        if not eid:
            ev = ev_api.insert(calendarId=calendar_id, body=gcal_event_body(n, map_name, tz)).execute()
            n["gcal_id"], n["gcal_updated"], n["gcal_hash"] = ev["id"], ev.get("updated", ""), h
            st["created"] += 1
            continue
        try:
            ev = ev_api.get(calendarId=calendar_id, eventId=eid).execute()
        except Exception as err:
            if not gone(err):
                raise
            ev = None
        if ev is None or ev.get("status") == "cancelled":   # Google 側で削除された
            clear_sched(n)
            for k in ("gcal_id", "gcal_updated", "gcal_hash"):
                n.pop(k, None)
            st["cleared"] += 1
            continue
        local_changed = n.get("gcal_hash") != h
        remote_changed = ev.get("updated", "") != n.get("gcal_updated", "")
        if local_changed:
            ev = ev_api.update(calendarId=calendar_id, eventId=eid, body=gcal_event_body(n, map_name, tz)).execute()
            st["updated"] += 1
        elif remote_changed:
            _apply_remote(n, ev)
            n["updated"] = now()
            st["pulled"] += 1
        n["gcal_updated"], n["gcal_hash"] = ev.get("updated", ""), _sched_hash(n)
    return st


def google_service(credentials_path):
    """Google カレンダー API のサービス（初回はブラウザで許可）"""
    try:
        from google.oauth2.credentials import Credentials
        from google_auth_oauthlib.flow import InstalledAppFlow
        from google.auth.transport.requests import Request
        from googleapiclient.discovery import build
    except ImportError:
        raise RuntimeError("Google 連携用のライブラリが入っていません。\n次のコマンドでインストールしてください:\n\n"
                           + GOOGLE_PIP)
    scopes = ["https://www.googleapis.com/auth/calendar.events"]
    creds = None
    if os.path.exists(GOOGLE_TOKEN):
        creds = Credentials.from_authorized_user_file(GOOGLE_TOKEN, scopes)
    if not creds or not creds.valid:
        if creds and creds.expired and creds.refresh_token:
            creds.refresh(Request())
        else:
            if not credentials_path or not os.path.exists(credentials_path):
                raise RuntimeError("認証ファイル（credentials.json）が設定されていません。\n"
                                   "「ファイル」→「Googleカレンダー設定…」で指定してください。")
            flow = InstalledAppFlow.from_client_secrets_file(credentials_path, scopes)
            creds = flow.run_local_server(port=0)
        with open(GOOGLE_TOKEN, "w", encoding="utf-8") as f:
            f.write(creds.to_json())
    return build("calendar", "v3", credentials=creds, cache_discovery=False)


def export_ics(mm, path):
    """日時を設定したタスクを iCalendar(.ics) に書き出す（Googleカレンダーへ手動で取り込み可）"""
    def esc(t):
        return (t or "").replace("\\", "\\\\").replace(";", "\\;").replace(",", "\\,").replace("\n", "\\n")
    stamp = datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%dT%H%M%SZ")
    lines = ["BEGIN:VCALENDAR", "VERSION:2.0", "PRODID:-//Mind_Navi//JP", "CALSCALE:GREGORIAN"]
    k = 0
    for n in mm.nodes.values():
        if not has_sched(n):
            continue
        sc = sched_of(n)
        if sc:
            d, a, b = sc
            f = lambda dd, m: (datetime.datetime.combine(dd, datetime.time())
                               + datetime.timedelta(minutes=m)).strftime("%Y%m%dT%H%M%S")
            t0, t1 = f"DTSTART:{f(d, a)}", f"DTEND:{f(d, b)}"
        else:   # 時刻なし → 終日
            d, a = _date(n["sched_date"]), None
            f = lambda dd, m: dd.strftime("%Y%m%d")
            t0 = "DTSTART;VALUE=DATE:" + d.strftime("%Y%m%d")
            t1 = "DTEND;VALUE=DATE:" + (d + datetime.timedelta(days=1)).strftime("%Y%m%d")
        lines += ["BEGIN:VEVENT", f"UID:{n['id']}@taskmap",   # UID は旧名のまま（取り込み済みの予定と重複させない）
                   f"DTSTAMP:{stamp}", t0, t1,
                  "SUMMARY:" + esc(("✔ " if n.get("status") == "done" and not n.get("repeat") else "")
                                   + n.get("label", "")),
                  "DESCRIPTION:" + esc(n.get("note", ""))]
        rr = rrule_of(n)
        if rr:
            lines.append(rr)
            lines += [(f"EXDATE:{f(_date(x), a)}" if a is not None else f"EXDATE;VALUE=DATE:{f(_date(x), a)}")
                      for x in n.get("exdates", []) if _date(x)]
        lines.append("END:VEVENT")
        k += 1
    lines.append("END:VCALENDAR")
    with open(path, "w", encoding="utf-8", newline="") as fp:
        fp.write("\r\n".join(lines) + "\r\n")
    return k


