REMIND_POINTS = ()   # 以前の「1か月前・1週間前・3日前」（期限日をなくしたので使わない）


REMIND_BEFORE = [(365, "1年前から"), (180, "半年前から"), (90, "3か月前から"), (30, "1か月前から"), (14, "2週間前から"), (7, "1週間前から"), (3, "3日前から"), (1, "前日から"),
                 (0, "当日だけ")]
REMIND_DEFAULT = 30   # 重要期限にしたときの既定：期限日の1か月前から知らせる


def remind_mode(n):
    """always（常に・毎日）／ before（期限日の◯日前から）／ deadline（期限日だけ。一覧に残り日数）
    ／ None（時期が未設定＝表示しない）"""
    r = n.get("remind") or {}
    return r.get("mode")


def remind_deadline(n):
    """重要期限の期限日＝タスクの日付（「期限日の◯日前から」のときだけ）"""
    if remind_mode(n) not in ("before", "deadline"):
        return None
    return _date(n.get("sched_date")) or _date(n.get("due"))


def remind_since(n):
    """重要期限にした日（古いデータは今日）"""
    r = n.get("remind") or {}
    return _date(r.get("since")) or datetime.date.today()


def remind_before(n):
    try:
        return max(0, int((n.get("remind") or {}).get("before", REMIND_DEFAULT)))
    except (TypeError, ValueError):
        return REMIND_DEFAULT


def remind_info(n, today=None):
    """今日知らせる重要期限なら (期限日, 数, True, 種類)。種類：daily（常に）／ before（期限の◯日前から）"""
    if not n.get("remind") or n.get("status") == "done":
        return None
    today = today or datetime.date.today()
    mode = remind_mode(n)
    if mode == "always":
        return None, (today - remind_since(n)).days + 1, True, "daily"
    if mode == "before":
        dl = remind_deadline(n)
        if dl and today >= dl - datetime.timedelta(days=remind_before(n)):
            return dl, (dl - today).days, True, "before"
    if mode == "deadline":   # 期限日だけ（当日以降）知らせる
        dl = remind_deadline(n)
        if dl and today >= dl:
            return dl, (dl - today).days, True, "before"
    return None


def _ymd_text(d, today=None):
    """日付の短い表示（今年でなければ年も付ける：50年先でも分かるように）"""
    today = today or datetime.date.today()
    return f"{d.month}/{d.day}" if d.year == today.year else f"{d.year}/{d.month}/{d.day}"


def left_text(days):
    """残り日数（1年以上は「◯年◯日」も添える）"""
    if days >= 365:
        y, r = divmod(days, 365)
        return f"あと{y}年{r}日" if r else f"あと{y}年"
    return f"あと{days}日"


def remind_start(n):
    dl = remind_deadline(n)
    return dl - datetime.timedelta(days=remind_before(n)) if dl else remind_since(n)


def remind_setting_text(n):
    """設定の説明（例「11/30 の1か月前から」「常に表示」「時期が未設定」）"""
    mode = remind_mode(n)
    if mode == "always":
        return "常に表示（毎日）"
    if mode == "before":
        dl = remind_deadline(n)
        lbl = dict(REMIND_BEFORE).get(remind_before(n), f"{remind_before(n)}日前から")
        return f"{_ymd_text(dl)} の{lbl}" if dl else "期限日（タスクの日付）が未入力"
    if mode == "deadline":
        dl = remind_deadline(n)
        return f"{_ymd_text(dl)} の当日だけ表示（一覧に残り日数）" if dl else "期限日（タスクの日付）が未入力"
    return "知らせる時期が未設定"


def remind_days(n, today=None):
    """一覧などの短い表示：常に＝「◯日目」、期限の前から＝「あと◯日」「今日」「◯日超過」"""
    info = remind_info(n, today)
    if not info:
        dl = remind_deadline(n)
        if remind_mode(n) == "deadline" and dl:   # 期限日だけ表示：一覧には残り日数
            return left_text((dl - (today or datetime.date.today())).days)
        st = remind_start(n) if remind_mode(n) == "before" and dl else None
        return f"{_ymd_text(st, today)}から" if st else ("未設定" if n.get("remind") and n.get("status") != "done" else "")
    if info[3] == "daily":
        return f"{info[1]}日目"
    return "今日が期限" if info[1] == 0 else (left_text(info[1]) if info[1] > 0 else f"{-info[1]}日超過")


def remind_left(n, today=None):
    """タスクリストの重要期限：期限日までの残り日数（50年先でも日数で。例「残り18,250日」）"""
    today = today or datetime.date.today()
    dl = remind_deadline(n) or _date(n.get("sched_date")) or _date(n.get("due"))
    if not dl:
        return remind_days(n, today) or "期限未設定"
    k = (dl - today).days
    if k == 0:
        return "今日が期限"
    return f"残り{k:,}日" if k > 0 else f"{-k:,}日超過"


def remind_text(n, today=None):
    info = remind_info(n, today)
    if not info:
        return ""
    if info[3] == "daily":
        return f"重要期限（{info[1]}日目）"
    dl = info[0]
    return f"期限 {_ymd_text(dl, today)}（{remind_days(n, today)}）"


