def mix(color, t, base="#ffffff"):
    try:
        a = [int(color[i:i + 2], 16) for i in (1, 3, 5)]
    except (TypeError, ValueError, IndexError):
        a = [0x86, 0x8e, 0x96]
    b = [int(base[i:i + 2], 16) for i in (1, 3, 5)]
    return "#%02x%02x%02x" % tuple(round(x + (y - x) * t) for x, y in zip(a, b))


def wobble(x1, y1, x2, y2, seed, z):
    """手書き風に少し揺れた線の座標列"""
    rnd = random.Random(seed)
    length = math.hypot(x2 - x1, y2 - y1)
    if length < 1:
        return [x1, y1, x2, y2]
    nx, ny = -(y2 - y1) / length, (x2 - x1) / length
    n = max(2, int(length / 28))
    bow = rnd.uniform(-10, 10) * z
    pts = [x1, y1]
    for i in range(1, n):
        t = i / n
        o = math.sin(math.pi * t) * bow + rnd.uniform(-1.6, 1.6) * z
        pts += [x1 + (x2 - x1) * t + nx * o, y1 + (y2 - y1) * t + ny * o]
    return pts + [x2, y2]


def clip_to_box(x0, y0, x1, y1, box):
    """(x0,y0)→(x1,y1) の線分が box（始点側）の境界と交わる点"""
    bx1, by1, bx2, by2 = box
    dx, dy = x1 - x0, y1 - y0
    ts = []
    if dx:
        ts += [(bx1 - x0) / dx, (bx2 - x0) / dx]
    if dy:
        ts += [(by1 - y0) / dy, (by2 - y0) / dy]
    ts = [t for t in ts if t > 0]
    t = min(ts) if ts else 0
    return x0 + dx * t, y0 + dy * t


