def migrate_old_local_files():
    """旧名（TaskMap）のころにこのPCに保存した設定・バックアップを、新しい名前（Mind_Navi）へコピーする。
    新しい方がまだ無いときだけ。元のファイルは残す"""
    home = os.path.expanduser("~")
    for old, new in ((".taskmap_slots.json", SETTINGS_PATH), (".taskmap_viewstate.json", VIEWSTATE_PATH),
                     (".taskmap_reminders.json", REMIND_STATE), (".taskmap_categories.json", CATEGORY_SETTINGS),
                     (".taskmap_google.json", GOOGLE_SETTINGS), (".taskmap_google_token.json", GOOGLE_TOKEN),
                     (".taskmap_backups", BACKUP_DIR)):
        src = os.path.join(home, old)
        if os.path.exists(new) or not os.path.exists(src):
            continue
        try:
            if os.path.isdir(src):
                shutil.copytree(src, new)
            else:
                shutil.copy2(src, new)
        except OSError:
            pass


LOCK_PATH = os.path.join(os.path.expanduser("~"), ".mind_navi.lock")
_instance_lock = None


def acquire_single_instance():
    """二重起動の防止：ロックファイルを OS の排他ロック付きで開いたままにする。
    すでに別の Mind_Navi が持っていれば False。異常終了してもロックは OS が自動で外すので、残骸で起動できなくなることはない"""
    global _instance_lock
    try:
        fp = open(LOCK_PATH, "a+")
    except OSError:
        return True   # ロックファイルを作れない環境では制限しない
    try:
        if sys.platform.startswith("win"):
            import msvcrt
            fp.seek(0)
            msvcrt.locking(fp.fileno(), msvcrt.LK_NBLCK, 1)
        else:
            import fcntl
            fcntl.flock(fp.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
    except OSError:
        fp.close()
        return False
    try:
        fp.seek(0)
        fp.truncate()
        fp.write(f"{os.getpid()} {now()}\n")
        fp.flush()
    except OSError:
        pass
    _instance_lock = fp   # プロセスが終わるまで開いたまま（＝ロックを保持）
    return True


def run_gui(path=None):
    import tkinter as tk
    from tkinter import ttk, filedialog, messagebox, simpledialog, colorchooser
    import tkinter.font as tkfont

    KIND_BY_LABEL = {v: k for k, v in KINDS.items()}
    STATUS_BY_LABEL = {v: k for k, v in STATUSES.items()}

    # ================= デザインスタイル（全画面の配色）：オフィス／ハッカー／深海／仏教 =================
    # 画面の色はすべて tkinter の _options を通るので、そこで色を置きかえる（描き直すたびに自動で反映、軽い辞書引き）。
    # 4象限の色（赤・紫・緑・灰）や黄などの鮮やかな色は色相を変えず、明るさだけ地の色に合わせて読みやすくする
    import colorsys
    DESIGNS = {
        "office": {"name": "オフィス"},
        "hacker": {"name": "ハッカー", "dark": True, "bg": "#050b07", "fg": "#c4ffd2", "hue": 0.36, "sat": 0.6,
                   "over": {"#a5d8ff": "#3dff7f", "#868e96": "#a3aaa6", "#1864ac": "#0e3b1e", "#fffffe": "#d8ffe2",
                            "#a5d8fe": "#3dff7f"}},
        "deepsea": {"name": "深海", "dark": True, "bg": "#061527", "fg": "#e2f1ff", "hue": 0.58, "sat": 0.5,
                    "over": {"#a5d8ff": "#7fd3ff", "#868e96": "#a3abb3", "#1864ac": "#0d3a66", "#fffffe": "#e8f4ff",
                             "#a5d8fe": "#7fd3ff"}},
        "buddha": {"name": "仏教（初期仏教）", "dark": False, "bg": "#fbf3df", "fg": "#3a2210", "hue": 0.09, "sat": 0.42,
                   "over": {"#1864ab": "#9a4a0c", "#a5d8ff": "#ffd27a", "#e7f5ff": "#fbe8c4", "#f8f9fa": "#f7ecd2",
                            "#ffffff": "#fffaf0", "#868e96": "#868e96", "#1864ac": "#9a4a0c", "#fffffe": "#fffaf0",
                            "#a5d8fe": "#ffd27a"}},   # ディベストの灰色はそのまま
    }
    THEME = {"key": "office", "fn": None, "rev": {}, "exempt": (), "applying": False}
    STYLE_LOG = {}   # アプリで設定した ttk のスタイル（見た目を切り替えたら設定し直す）
    _orig_style_configure = ttk.Style.configure

    def _logged_style_configure(self, style, query_opt=None, **kw):
        if kw and not THEME["applying"]:
            STYLE_LOG.setdefault(style, {}).update(kw)
        return _orig_style_configure(self, style, query_opt, **kw)
    ttk.Style.configure = _logged_style_configure
    _COLOR_OPTS = {"-fill", "-outline", "-background", "-bg", "-foreground", "-fg", "-activebackground",
                   "-activeforeground", "-activefill", "-activeoutline", "-highlightbackground", "-highlightcolor",
                   "-insertbackground", "-selectbackground", "-selectforeground", "-disabledforeground",
                   "-readonlybackground", "-troughcolor", "-disabledfill", "-selectcolor", "-fieldbackground"}

    def _hex(c):
        c = c.strip()
        if len(c) == 4:
            c = "#" + "".join(ch * 2 for ch in c[1:])
        return int(c[1:3], 16) / 255, int(c[3:5], 16) / 255, int(c[5:7], 16) / 255

    def _theme_map_factory(cfg):
        cache = {}
        bgL = colorsys.rgb_to_hls(*_hex(cfg["bg"]))[1]
        fgL = colorsys.rgb_to_hls(*_hex(cfg["fg"]))[1]
        over = {k.lower(): v for k, v in cfg.get("over", {}).items()}

        def f(col):
            v = cache.get(col)
            if v is not None:
                return v
            lc = col.lower()
            if lc in over:
                v = over[lc]
            elif not (lc.startswith("#") and len(lc) in (4, 7)):
                v = col
            else:
                try:
                    r, g, b = _hex(lc)
                except ValueError:
                    cache[col] = col
                    return col
                h, l, s_ = colorsys.rgb_to_hls(r, g, b)
                if s_ < 0.2 or l > 0.96 or l < 0.06:   # 白・灰・黒
                    if cfg["dark"]:   # 明るい灰（地の色）は暗い地へ、暗い灰（文字の色）ははっきり明るく（見やすさ優先）
                        if l >= 0.78:
                            l2, s2 = bgL + (1 - l) / 0.22 * 0.17, cfg["sat"] * 0.45
                        else:
                            l2, s2 = fgL - (l / 0.78) * 0.18, cfg["sat"] * 0.3   # 文字はどれもはっきり明るく
                    else:
                        l2, s2 = fgL + l * (bgL - fgL), cfg["sat"] * 0.7
                    h2 = cfg["hue"]
                elif cfg["dark"]:   # 鮮やかな色：色相はそのまま。うすい地の色は暗く、文字・線の色は明るくはっきり
                    h2 = h
                    if l > 0.88:   # ごくうすい広い地（今日の列・お知らせの地など）：暗く落ち着いた色に（文字が読めるよう）
                        l2, s2 = bgL + 0.05 + (1 - l) * 0.45, min(0.5, s_ * 0.35 + 0.12)
                    elif l > 0.72:
                        l2, s2 = bgL + 0.06 + (1 - l) * 0.45, min(0.85, s_ * 0.55 + 0.2)
                    else:
                        l2, s2 = max(0.68, min(0.82, l + 0.32)), max(s_, 0.7)
                else:
                    h2, l2, s2 = h, l, s_
                rr, gg, bb = colorsys.hls_to_rgb(h2, max(0.0, min(1.0, l2)), max(0.0, min(1.0, s2)))
                v = "#%02x%02x%02x" % (int(rr * 255 + 0.5), int(gg * 255 + 0.5), int(bb * 255 + 0.5))
            cache[col] = v
            THEME["rev"][v] = col   # 元の色を覚える（スタイルを変えたときに元から変換し直す）
            return v
        return f

    _orig_options = tk.Misc._options

    def _themed_options(self, cnf, kw=None):
        res = _orig_options(self, cnf, kw)
        fn = THEME["fn"]
        if fn is None or not res:
            return res
        if THEME["exempt"] and getattr(self, "_w", "").startswith(THEME["exempt"]):
            return res   # 独自の配色の画面（Vipassana）はそのまま
        lst = list(res)
        for i in range(0, len(lst) - 1, 2):
            if lst[i] in _COLOR_OPTS and isinstance(lst[i + 1], str) and lst[i + 1][:1] == "#":
                lst[i + 1] = fn(lst[i + 1])
        return tuple(lst)
    # （オフィスのときは置きかえを入れない：描画を遅くしないため。ほかのスタイルを選んだときだけ差し込む）

    _orig_create_text = tk.Canvas.create_text

    def _create_text_default_fill(self, *args, **kw):
        """色を指定していない文字（既定は黒）も、デザインスタイルに合わせて読める色にする"""
        if "fill" not in kw and not (args and isinstance(args[-1], dict) and "fill" in args[-1]):
            kw["fill"] = "#212529"
        return _orig_create_text(self, *args, **kw)
    tk.Canvas.create_text = _create_text_default_fill

    _orig_tag_configure = ttk.Treeview.tag_configure

    def _themed_tag_configure(self, tagname, option=None, **kw):
        if kw:   # 一覧の色（行・見出しの色）も置きかえ。元の色は覚えておく
            store = self.__dict__.setdefault("_tm_tags", {})
            store.setdefault(tagname, {}).update({k: v for k, v in kw.items() if k in ("foreground", "background")})
            fn = THEME["fn"]
            if fn is not None:
                kw = {k: (fn(v) if k in ("foreground", "background") and isinstance(v, str) and v[:1] == "#" else v)
                      for k, v in kw.items()}
        return _orig_tag_configure(self, tagname, option, **kw)
    ttk.Treeview.tag_configure = _themed_tag_configure
    ttk.Treeview.tag_config = _themed_tag_configure

    def apply_design(root, key, base_theme=None):
        """デザインスタイルを切り替え：ttk の見た目・既定の色・開いているすべての画面の色を、その場で変える"""
        cfg = DESIGNS.get(key) or DESIGNS["office"]
        THEME["key"] = key if key in DESIGNS else "office"
        THEME["fn"] = None if THEME["key"] == "office" else _theme_map_factory(cfg)
        tk.Misc._options = _orig_options if THEME["fn"] is None else _themed_options
        fn = THEME["fn"] or (lambda c: c)
        st = ttk.Style(root)
        THEME["applying"] = True
        try:
            _apply_styles(st, root, cfg, fn, base_theme)
        finally:
            THEME["applying"] = False
        _recolor_all(root)

    def _apply_styles(st, root, cfg, fn, base_theme):
        if THEME["key"] == "office":
            if base_theme and st.theme_use() != base_theme:
                st.theme_use(base_theme)
            for sname, kw in STYLE_LOG.items():   # アプリのスタイル（行の高さ・文字）
                st.configure(sname, **kw)
            try:
                root.option_clear()
            except tk.TclError:
                pass
        else:
            if st.theme_use() != "clam":
                st.theme_use("clam")   # 色を変えられる見た目に
            for sname, kw in STYLE_LOG.items():
                st.configure(sname, **kw)
            BG, FG = cfg["bg"], cfg["fg"]
            PANEL, FIELD, BTN, SEL, BORDER = fn("#f1f3f5"), fn("#ffffff"), fn("#e9ecef"), fn("#a5d8ff" if not cfg["dark"] else "#228be6"), fn("#adb5bd")
            if cfg["dark"]:
                SEL = cfg.get("sel") or mix(cfg["fg"], 0.6, cfg["bg"])
            for v_, o_ in ((FG, "#212529"), (BG, "#ffffff"), (SEL, "#a5d8ff")):   # 元の色（オフィスに戻すとき用）
                THEME["rev"].setdefault(v_, o_)
            st.configure(".", background=PANEL, foreground=FG, fieldbackground=FIELD, bordercolor=BORDER,
                         lightcolor=PANEL, darkcolor=PANEL, troughcolor=BTN, selectbackground=SEL,
                         selectforeground=FG if cfg["dark"] else "#ffffff", insertcolor=FG, arrowcolor=FG)
            st.configure("TButton", background=BTN, foreground=FG)
            st.map("TButton", background=[("active", SEL)], foreground=[("disabled", BORDER)])
            st.configure("Toolbutton", background=PANEL, foreground=FG)
            st.map("Toolbutton", background=[("selected", SEL), ("active", BTN)])
            st.configure("Treeview", background=FIELD, fieldbackground=FIELD, foreground=FG)
            st.map("Treeview", background=[("selected", SEL)], foreground=[("selected", FG if cfg["dark"] else "#ffffff")])
            st.configure("Treeview.Heading", background=BTN, foreground=FG)
            st.configure("TNotebook", background=PANEL)
            st.configure("TNotebook.Tab", background=BTN, foreground=FG)
            st.map("TNotebook.Tab", background=[("selected", PANEL)])
            for name in ("TEntry", "TCombobox", "TSpinbox"):
                st.configure(name, fieldbackground=FIELD, foreground=FG)
            st.map("TCombobox", fieldbackground=[("readonly", FIELD)], foreground=[("readonly", FG)])
            st.configure("TLabelframe", background=PANEL)
            st.configure("TLabelframe.Label", background=PANEL, foreground=FG)
            for name in ("TCheckbutton", "TRadiobutton"):
                st.map(name, background=[("active", PANEL)])
            try:
                root.option_clear()
                for pat, val in (("*Background", PANEL), ("*Foreground", FG), ("*Menu.background", PANEL),
                                 ("*Menu.foreground", FG), ("*Menu.activeBackground", SEL),
                                 ("*TCombobox*Listbox.background", FIELD), ("*TCombobox*Listbox.foreground", FG),
                                 ("*insertBackground", FG)):
                    root.option_add(pat, val)
            except tk.TclError:
                pass

    _TK_COLOR_OPTS = ("background", "foreground", "activebackground", "activeforeground", "highlightbackground",
                      "highlightcolor", "insertbackground", "selectbackground", "selectforeground", "troughcolor",
                      "disabledforeground", "selectcolor", "readonlybackground")

    def _recolor_all(root):
        """開いているすべての画面の色を、元の色からいまのスタイルの色に変え直す"""
        rev = THEME["rev"]
        cfg = DESIGNS.get(THEME["key"]) or {}

        def walk(w):
            try:
                cls = w.winfo_class()
            except tk.TclError:
                return
            if THEME["exempt"] and str(w).startswith(THEME["exempt"]):
                return
            is_ttk = isinstance(w, ttk.Widget)
            orig = w.__dict__.setdefault("_tm_o", {})
            for opt in (("foreground", "background") if is_ttk else _TK_COLOR_OPTS):
                try:
                    cur = str(w.cget(opt))
                except (tk.TclError, ValueError):
                    continue
                if opt not in orig:
                    orig[opt] = rev.get(cur, cur)
                o = orig[opt]
                try:
                    if o[:1] == "#":
                        w.configure(**{opt: o})   # _options で今のスタイルの色に
                    elif not is_ttk and THEME["fn"] is not None and o:   # 既定の色（システムの色）の部品
                        if opt in ("background", "highlightbackground", "troughcolor", "readonlybackground"):
                            w.configure(**{opt: THEME["fn"]("#f1f3f5" if cls not in ("Text", "Entry", "Listbox") else "#ffffff")})
                        elif opt in ("foreground", "insertbackground", "activeforeground", "selectforeground"):
                            w.configure(**{opt: cfg.get("fg", "#000000")})
                        elif opt in ("activebackground", "selectbackground"):
                            w.configure(**{opt: THEME["fn"]("#a5d8ff")})
                    elif not is_ttk and THEME["fn"] is None and o:
                        w.configure(**{opt: o})
                except tk.TclError:
                    pass
            if cls == "Canvas":   # 描いてある図形の色も
                for it in w.find_all():
                    for opt in ("fill", "outline"):
                        try:
                            cur = str(w.itemcget(it, opt))
                        except tk.TclError:
                            continue
                        if cur[:1] == "#":
                            try:
                                w.itemconfigure(it, **{opt: rev.get(cur, cur)})
                            except tk.TclError:
                                pass
            if cls == "Treeview" and "_tm_tags" in w.__dict__:
                for tg, kw in w._tm_tags.items():
                    w.tag_configure(tg, **kw)
            for ch in w.winfo_children():
                walk(ch)
        walk(root)


    class DateBoxes(ttk.Frame):
        """日付の入力欄：［年］年［月］月［日］日 の3つの箱（Tab で次の箱へ。年4桁・月日2桁で自動で次へ）。
        var（StringVar）とは「2026-11-05」の形でやりとりする（空なら ""）"""

        def __init__(self, parent, var, on_return=None):
            super().__init__(parent)
            self.var = var
            self._busy = False
            self.parts = [tk.StringVar() for _ in range(3)]
            self.entries = []
            for k, (w, unit) in enumerate(((5, "年"), (3, "月"), (3, "日"))):
                e = ttk.Entry(self, textvariable=self.parts[k], width=w, justify="center")
                e.pack(side="left")
                ttk.Label(self, text=unit).pack(side="left", padx=(1, 4))
                e.bind("<KeyRelease>", lambda ev, k=k: self._typed(ev, k))
                e.bind("<BackSpace>", lambda ev, k=k: self._back(ev, k))
                e.bind("<FocusIn>", lambda ev: ev.widget.select_range(0, "end"))
                for key in ("<Key-minus>", "<Key-slash>", "<Key-period>"):   # 区切りを打ったら次の箱へ
                    e.bind(key, lambda ev, k=k: (self._next(k), "break")[1])
                if on_return:
                    e.bind("<Return>", lambda ev: on_return())
                self.entries.append(e)
            self._on_return = on_return
            b = ttk.Button(self, text="📅", width=3, command=self.pick)   # カレンダーから選ぶ
            b.pack(side="left", padx=(2, 0))
            var.trace_add("write", lambda *_: self._from_var())
            self._from_var()

        shift_lookup = None   # 日付 → (勤務の記号, 強調するか)：App が設定（私のシフトをカレンダーに表示）

        def pick(self):
            """月のカレンダーを出して、日付をクリックで選ぶ（私のシフト（勤務）も各日に表示）"""
            cur = _date(self.var.get()) or datetime.date.today()
            try:
                shifts = DateBoxes.shift_lookup() if DateBoxes.shift_lookup else {}
            except Exception:
                shifts = {}
            st = {"ym": cur.replace(day=1)}
            w = tk.Toplevel(self)
            w.title("日付を選ぶ")
            w.transient(self.winfo_toplevel())
            w.resizable(False, False)
            top = ttk.Frame(w, padding=(6, 6, 6, 0))
            top.pack(fill="x")
            lbl = ttk.Label(top, font=("TkDefaultFont", 11, "bold"))
            grid = ttk.Frame(w, padding=6)
            grid.pack()

            def shift(k):
                y, m = st["ym"].year, st["ym"].month + k
                y, m = y + (m - 1) // 12, (m - 1) % 12 + 1
                st["ym"] = datetime.date(y, m, 1)
                draw()

            def choose(d):
                self.var.set(d.isoformat())   # 入れるだけ（保存は［保存］で）
                w.destroy()

            def draw():
                for ch in grid.winfo_children():
                    ch.destroy()
                ym = st["ym"]
                lbl.configure(text=f"{ym.year}年{ym.month}月")
                if yv.get() != str(ym.year):
                    yv.set(str(ym.year))
                for i, wd in enumerate("月火水木金土日"):
                    tk.Label(grid, text=wd, fg="#e03131" if i == 6 else "#1c7ed6" if i == 5 else "#495057").grid(
                        row=0, column=i, padx=1)
                d = ym - datetime.timedelta(days=ym.weekday())
                today = datetime.date.today()
                for r in range(6):
                    for col in range(7):
                        inm = d.month == ym.month
                        sh_ = shifts.get(d)
                        bt = tk.Button(grid, text=str(d.day) + ("\n" + sh_[0] if sh_ else "\n "), width=4,
                                       relief="flat" if d != cur else "solid", font=("TkDefaultFont", 9),
                                       bg="#fff3bf" if d == today else ("#ffe3e3" if sh_ and sh_[1] else "#e7f5ff" if sh_ else
                                                                         "#ffffff" if inm else "#f1f3f5"),
                                       fg=("#e03131" if col == 6 or jp_holiday(d) else "#1c7ed6" if col == 5 else "#212529")
                                       if inm else "#adb5bd",
                                       command=lambda d=d: choose(d))
                        bt.grid(row=r + 1, column=col, padx=1, pady=1)
                        d += datetime.timedelta(days=1)
            ttk.Button(top, text="«", width=3, command=lambda: shift(-12)).pack(side="left")   # 1年ずつ
            ttk.Button(top, text="◀", width=3, command=lambda: shift(-1)).pack(side="left")
            lbl.pack(side="left", expand=True)
            ttk.Button(top, text="»", width=3, command=lambda: shift(12)).pack(side="right")
            ttk.Button(top, text="▶", width=3, command=lambda: shift(1)).pack(side="right")
            yv = tk.StringVar(value=str(cur.year))   # 年を直接（50年先でもすぐ）
            ys = ttk.Spinbox(top, from_=1900, to=2200, textvariable=yv, width=6,
                             command=lambda: jump_year())
            ys.pack(side="right", padx=(0, 4))
            ys.bind("<Return>", lambda ev: jump_year())

            def jump_year():
                try:
                    y = max(1900, min(2200, int(yv.get())))
                except ValueError:
                    return
                st["ym"] = datetime.date(y, st["ym"].month, 1)
                draw()
            ttk.Button(top, text="今日", command=lambda: choose(datetime.date.today())).pack(side="right", padx=4)
            draw()
            w.update_idletasks()
            w.geometry(f"+{self.winfo_rootx()}+{self.winfo_rooty() + self.winfo_height() + 2}")
            w.grab_set()

        def _from_var(self):
            if self._busy:
                return
            v = (self.var.get() or "").strip().replace("/", "-")
            ps = v.split("-") if v else ["", "", ""]
            ps = (ps + ["", "", ""])[:3]
            self._busy = True
            try:
                for pv, x in zip(self.parts, ps):
                    pv.set(x.lstrip("0") if x and len(x) <= 2 else x)
            finally:
                self._busy = False

        def _to_var(self):
            y, m, d = (p.get().strip() for p in self.parts)
            if not (y or m or d):
                v = ""
            elif y.isdigit() and m.isdigit() and d.isdigit():
                v = f"{int(y):04d}-{int(m):02d}-{int(d):02d}"
            else:
                v = f"{y}-{m}-{d}"   # 不完全（保存時に確認する）
            self._busy = True
            try:
                self.var.set(v)
            finally:
                self._busy = False

        def _typed(self, ev, k):
            txt = self.parts[k].get()
            digits = "".join(ch for ch in txt if ch.isdigit())
            if digits != txt:
                self.parts[k].set(digits)
            self._to_var()
            if ev.keysym.isdigit() and len(digits) >= (4 if k == 0 else 2):
                self._next(k)

        def _next(self, k):
            if k < 2:
                self.entries[k + 1].focus_set()
                self.entries[k + 1].select_range(0, "end")

        def _back(self, ev, k):
            if k > 0 and not self.parts[k].get():
                self.entries[k - 1].focus_set()
                self.entries[k - 1].icursor("end")
                return "break"
            return None

        def set_state(self, state):
            for e in self.entries:
                e.configure(state=state)

    def ask_date(parent, title, prompt, initial=""):
        """日付を3つの箱で入力する小さな画面。戻り値：「2026-11-05」／ ""（空欄＝解除）／ None（キャンセル）"""
        w = tk.Toplevel(parent)
        w.title(title)
        w.transient(parent)
        w.resizable(False, False)
        f = ttk.Frame(w, padding=14)
        f.pack()
        ttk.Label(f, text=prompt).pack(anchor="w")
        v = tk.StringVar(value=initial)
        res = {"v": None}

        def ok():
            res["v"] = v.get().strip()
            w.destroy()
        db = DateBoxes(f, v, on_return=ok)
        db.pack(anchor="w", pady=8)
        bf = ttk.Frame(f)
        bf.pack(fill="x")
        ttk.Button(bf, text="OK", command=ok).pack(side="right")
        ttk.Button(bf, text="空欄にする", command=lambda: (v.set(""), ok())).pack(side="right", padx=6)
        ttk.Button(bf, text="キャンセル", command=w.destroy).pack(side="left")
        w.bind("<Escape>", lambda ev: w.destroy())
        db.entries[0].focus_set()
        w.grab_set()
        parent.wait_window(w)
        return res["v"]

    class CachedFont(tkfont.Font):
        """文字幅の計測を速くするフォント：1文字ずつの幅を覚えておき、文字列は足し合わせて求める
        （Tk の measure は1回ごとに時間がかかり、画面の描き直しが重くなるため）"""

        def __init__(self, *a, **k):
            super().__init__(*a, **k)
            self._cw = {}

        def measure(self, text, displayof=None):
            text = str(text)
            sw = self.__dict__.setdefault("_sw", {})   # 文字列ごとの幅も覚える（同じ文字列を何度も測るため）
            got = sw.get(text)
            if got is not None:
                return got
            if len(sw) > 20000:
                sw.clear()
            cw = self._cw
            tot = 0
            for ch in text:
                w = cw.get(ch)
                if w is None:
                    w = cw[ch] = tkfont.Font.measure(self, ch)
                tot += w
            sw[text] = tot
            return tot

        def metrics(self, *opts, **kw):
            key = ("__m",) + opts
            v = self._cw.get(key)
            if v is None:
                v = self._cw[key] = tkfont.Font.metrics(self, *opts, **kw)
            return v

    class App:
        def __init__(self, root):
            self.root = root
            self.mm = MindNavi()
            self.path = None
            self.dirty = False
            self._known_mtime = {}   # 開いた・保存したときのファイルの更新時刻（別の場所での上書きを検出）
            self._snap_last = {}     # 版のフォルダ → 最後に残した内容
            self.place_mode = None   # カテゴリのツリーで置き場所を決めている途中
            self.catpick_mode = None  # マップでカテゴリにするノードを選んでいる途中
            self._file_sha = {}      # ファイル → 開いた・保存したときの内容のハッシュ（元に戻す履歴の照合用）
            self.sel = None
            self.mode = None          # None / "link" / "parent"
            self.drag = None
            self.drop_target = None
            self.editing = None       # (nid, entry, window_id, is_new)
            self.history, self.future = [], []
            self.z, self.ox, self.oy = 1.0, 0.0, 0.0
            self.style = "office"
            self.boxes, self.ul = {}, {}
            self._drawn_ids = set()   # 今の画面で実際に描いたノード
            self._bsize_all, self._bsize = {}, {}   # 表示スタイルごとのノードの大きさ（画面の外のノードの見積もり用）
            self._fonts = {}
            fams = set(tkfont.families())
            default = tkfont.nametofont("TkDefaultFont").actual("family")

            def pick(cands, fb):
                return next((c for c in cands if c in fams), fb)
            self.fam_base = pick(["Yu Gothic UI", "Meiryo UI", "Hiragino Sans", "Noto Sans CJK JP",
                                  "Noto Sans JP"], default)
            self.fam_casual = pick(["UD デジタル 教科書体 NK-R", "UD デジタル 教科書体 N-R",
                                    "Hiragino Maru Gothic ProN", "ヒラギノ丸ゴ ProN", "M PLUS Rounded 1c",
                                    "Zen Maru Gothic", "Kosugi Maru"], self.fam_base)
            try:   # 入力欄の文字（TkTextFont）は表示の文字（TkDefaultFont）と同じ大きさに：入力中に小さくならないように
                dfl = tkfont.nametofont("TkDefaultFont")
                tkfont.nametofont("TkTextFont").configure(size=dfl.actual("size"), family=dfl.actual("family"))
            except tk.TclError:
                pass
            self.v_style = tk.StringVar(value="office")
            self.v_auto = tk.BooleanVar(value=True)
            self.v_panel = tk.BooleanVar(value=True)
            self.v_layout = tk.StringVar(value="tree")
            self.v_gantt_all = tk.BooleanVar(value=False)
            self.load_categories()
            self.slots, self.cur = self._load_settings()
            self.v_open_mode = tk.StringVar(value=self._open_mode_default)
            self.v_hide_done = tk.BooleanVar(value=self._hide_done_default)
            self.compass_open = self._compass_open_default
            self.daily_open = True   # カレンダー最上段のデイリー欄を展開しているか
            self.sec_open = self._sec_open_default   # 左パネルの各欄（達成率・タスクリスト・選択中・ヒント）の開閉
            self.compass_mon = None   # コンパスで見ている週（None＝今週／カレンダーでは表示中の週）
            self.v_slot = tk.IntVar(value=self.cur)
            self._base_theme = ttk.Style(root).theme_use()
            self._build()
            if getattr(self, "design", "office") != "office":   # デザインスタイル（前回選んだもの）
                apply_design(root, self.design, self._base_theme)
            root.protocol("WM_DELETE_WINDOW", self.on_close)
            # すべてのポップアップ（設定画面・ダイアログ・各ウインドウ）は、表示するときに画面の中に収まる位置へ
            root.bind_class("Toplevel", "<Map>",
                            lambda ev: ev.widget.after(15, lambda w=ev.widget: fit_on_screen(w))
                            if isinstance(ev.widget, tk.Toplevel) else None, add="+")
            self._startup(path)
            DateBoxes.shift_lookup = self._shift_days   # 日付を選ぶカレンダーに私のシフトを表示
            self._schedule_clock()
            self.alarm_fired = set()
            self.root.after(3000, self._alarm_tick)
            self._bak_last = {}   # バックアップ先 → 最後に書いた内容（同じなら書かない）
            self.last_autosave = None
            self.root.after(BACKUP_INTERVAL_MS, self._backup_tick)
            self.root.after(1500, self.import_legacy_data)   # このPCだけにあった購入分析・メモをデータファイルへ
            self.root.after(2500, self._check_data_dir)   # データは Googleドライブのフォルダに（どのPCからも同じ）
            self.root.after(30000, self._periodic_save)   # こまめに自動保存（操作の邪魔にならないとき）

        # ---- 現在時刻の線を 5 分ごとに更新 ----
        def _schedule_clock(self):
            """次の 5 分の区切り（0分・5分・10分…）に合わせて更新する"""
            nw = datetime.datetime.now()
            sec = (5 - nw.minute % 5) * 60 - nw.second
            self.root.after(max(1, sec) * 1000 + 200, self._clock_tick)

        def _clock_tick(self):
            try:
                busy = self.drag or self.editing or getattr(self, "palette_win", None)
                if self.style in TABLE_STYLES and not busy:
                    self.redraw()   # カレンダーの現在時刻の線・ガントの今日の線
            finally:
                self._schedule_clock()

        # ---- 1分ごとの自動バックアップ ----
        def _backup_docs(self):
            """(バックアップ先, マップ, 元ファイル) の一覧。変更がある（未保存の）マップだけ"""
            out = []
            for j, s_ in enumerate(self.slots):
                if not s_:
                    continue
                if j == self.cur:
                    if self.dirty:
                        out.append((backup_path(self.path, j), self.mm, self.path))
                elif s_.get("doc") and s_["doc"]["dirty"]:
                    out.append((backup_path(s_["doc"]["path"], j), s_["doc"]["mm"], s_["doc"]["path"]))
            return out

        def backup_now(self):
            n = 0
            for bp, mm, src in self._backup_docs():
                try:
                    d = mm.to_dict()
                    d["backup_of"] = os.path.abspath(src) if src else None
                    txt = json.dumps(d, ensure_ascii=False, indent=1)
                    if self._bak_last.get(bp) == txt and os.path.exists(bp):
                        continue   # 前回から変わっていない
                    def write(bp=bp, txt=txt):   # 書き込みは別の処理で（画面を待たせない）
                        os.makedirs(BACKUP_DIR, exist_ok=True)
                        tmp = bp + ".tmp"
                        with open(tmp, "w", encoding="utf-8") as fp:
                            fp.write(txt)
                        os.replace(tmp, bp)   # 書きかけで壊れないように置き換え
                    BG_WRITER.put(write)
                    self._bak_last[bp] = txt
                    n += 1
                except (OSError, TypeError, ValueError):
                    pass
            if n:
                self.last_backup = datetime.datetime.now()
            return n

        def _backup_tick(self):
            """1分ごと：保存先のあるマップは自動保存、無題のマップはバックアップ"""
            try:
                self.autosave()
                self.snapshot_all()
                self.backup_now()
            except Exception:
                pass
            finally:
                self.root.after(AUTOSAVE_MS, self._backup_tick)

        # ---- 自動保存（1分ごと・画面を切り替えたとき）と版の管理 ----
        def _busy_editing(self):
            """入力・ドラッグの途中か（途中なら今のマップの自動保存は次の機会に）"""
            return bool(self.editing or self.drag or getattr(self, "cal_inline", None)
                        or getattr(self, "_q_dirty", False))

        def _snapshot(self, path, mm):
            """バックアップ（版）を残す。内容が前回と同じなら残さない。新しい VERSION_KEEP 版だけ保持"""
            try:
                txt = json.dumps(mm.to_dict(), ensure_ascii=False, indent=1)
                vd = version_dir(path)
                if self._snap_last.get(vd) == txt:
                    return False
                stamp = datetime.datetime.now().strftime("%Y%m%d-%H%M%S-%f")[:-3]

                def write(vd=vd, txt=txt, stamp=stamp):   # 書き込みは別の処理で（画面を待たせない）
                    os.makedirs(vd, exist_ok=True)
                    fp = os.path.join(vd, stamp + ".json")
                    with open(fp + ".tmp", "w", encoding="utf-8") as f:
                        f.write(txt)
                    os.replace(fp + ".tmp", fp)
                    olds = sorted(f for f in os.listdir(vd) if f.endswith(".json"))
                    for f in olds[:-VERSION_KEEP]:
                        os.remove(os.path.join(vd, f))
                BG_WRITER.put(write)
                self._snap_last[vd] = txt
                return True
            except (OSError, TypeError, ValueError):
                return False

        def snapshot_all(self):
            """開いているすべてのマップ（保存先のあるもの）のバックアップを残す"""
            for j, s_ in enumerate(self.slots):
                if not s_:
                    continue
                if j == self.cur:
                    path, mm = self.path, self.mm
                else:
                    doc = s_.get("doc")
                    path, mm = (doc["path"], doc["mm"]) if doc else (None, None)
                if path and mm is not None and path.lower().endswith(".json"):
                    self._snapshot(path, mm)

        def on_transition(self, reason="画面の切り替え", defer=None):
            """画面を切り替えたとき：メインファイルへ自動保存＋バックアップを残す。
            ふつうの画面の切り替えは、新しい画面を先に表示してから少し後に保存する（切り替えを待たせない）"""
            try:   # 開いている状態（表示・拡大率・位置・展開）も記録して、次に開いたときにその状態から
                self.remember_view()
                if self.path:
                    self.record_view_state()
            except Exception:
                pass
            if defer is None:
                defer = reason == "画面の切り替え"
            job = getattr(self, "_trans_job", None)
            if job:
                try:
                    self.root.after_cancel(job)
                except tk.TclError:
                    pass
                self._trans_job = None
            if defer:
                try:
                    self._trans_job = self.root.after(350, lambda: self._transition_save(reason))
                    return
                except tk.TclError:
                    pass
            self._transition_save(reason)

        def _transition_save(self, reason):
            self._trans_job = None
            try:
                self.autosave(reason)
                self.snapshot_all()
                self.backup_now()
            except Exception as err:   # 保存の失敗で画面の切り替えを止めない
                self.set_status(f"⚠ 自動保存できませんでした：{err}")

        @staticmethod
        def _core_sig(d):
            """買い物リスト（スマホアプリでも書きかえる部分）を除いた内容の指紋"""
            def norm(x):   # 数の書き方の違い（0.0 と 0 など）は同じとみなす
                if isinstance(x, float) and x.is_integer():
                    return int(x)
                if isinstance(x, dict):
                    return {k: norm(v) for k, v in x.items()}
                if isinstance(x, list):
                    return [norm(v) for v in x]
                return x
            try:
                d2 = dict(d)
                v = dict(d2.get("view") or {})
                v.pop("groceries", None)
                d2["view"] = v
                return hashlib.sha1(json.dumps(norm(d2), sort_keys=True, ensure_ascii=False, default=str).encode("utf-8")).hexdigest()
            except Exception:
                return None

        def adopt_outside_groceries(self, path=None, quiet=False):
            """スマホアプリ（Googleドライブ）で買い物リストだけが書きかえられていたら、その内容を取り込んで続ける。
            戻り値：取り込んだら True（ほかの部分も変わっていたら False）"""
            path = path or self.path
            if not path or not self._changed_outside(path):
                return False
            ap = os.path.abspath(path)
            try:
                with open(ap, encoding="utf-8") as fp:
                    disk = json.load(fp)
            except (OSError, ValueError):
                return False
            sig = getattr(self, "_core_sigs", {}).get(ap)
            if not sig or self._core_sig(disk) != sig:
                return False   # 買い物リスト以外も変わっている → これまでどおり確認
            if getattr(self, "_groc_local", False):
                mine = self.mm.view.get("groceries") or {}
                theirs = (disk.get("view") or {}).get("groceries") or {}
                merged = dict(theirs)   # 両方で変えた：品・定番は id でまとめ、購入の記録は両方を残す
                for k in ("items", "staples"):
                    ids = {x.get("id") for x in theirs.get(k, [])}
                    merged[k] = list(theirs.get(k, [])) + [x for x in mine.get(k, []) if x.get("id") not in ids]
                hs = {json.dumps(h, sort_keys=True) for h in theirs.get("history", [])}
                merged["history"] = list(theirs.get("history", [])) + [h for h in mine.get("history", [])
                                                                       if json.dumps(h, sort_keys=True) not in hs]
                self.mm.view["groceries"] = merged
                self.dirty = True
            else:
                self.mm.view["groceries"] = (disk.get("view") or {}).get("groceries") or {}
            self._known_mtime[ap] = os.path.getmtime(ap)
            self._groc_local = False
            gw = getattr(self, "grocery_win", None)
            try:
                if gw is not None and gw.win.winfo_exists():
                    gw.data = self.mm.view.setdefault("groceries", {"items": [], "staples": [], "history": []})
                    for k_ in ("items", "staples", "history"):
                        gw.data.setdefault(k_, [])
                    gw.refresh()
            except Exception:
                pass
            if not quiet:
                self.set_status("スマホの買い物リストの変更を取り込みました")
            return True

        def _write_doc(self, path, mm, history=None):
            """書きかけで壊れないよう一時ファイルに書いてから置き換える。history を渡すと元に戻す履歴も保存。
            保存の前に、データが大きく減っていないか確かめる（減っていれば前の中身を「保存前の退避」として残して知らせる）。
            1時間ごと・毎日・毎月の復元ポイントも残す"""
            ap = os.path.abspath(path)
            d_ = mm.to_dict()
            if not getattr(self, "_guard_skip", False):   # 復元ポイントから戻したときは守りを通さない
                d_ = self._protect_before_save(path, ap, mm, d_)
            self._guard_skip = False
            sc_ = data_score(d_)
            fp_ = {"ver": APP_VERSION, "at": now(), **sc_}   # 保存したときの数（次に開いたときに減っていないか比べる）
            mm.view["mn_guard"] = fp_
            d_.setdefault("view", {})["mn_guard"] = dict(fp_)
            txt = json.dumps(d_, ensure_ascii=False, indent=2)
            data = txt.encode("utf-8")
            self._save_guard(path, ap, d_)
            tmp = path + ".tmp"
            with open(tmp, "wb") as f:
                f.write(data)
            os.replace(tmp, path)
            mp = mirror_path(path)
            if mp:   # 壊れたとき用：まったく同じ内容のバックアップファイルを同じフォルダにもう一つ
                try:
                    with open(mp + ".tmp", "wb") as f:
                        f.write(data)
                    os.replace(mp + ".tmp", mp)
                except OSError:
                    pass
            self._known_mtime[ap] = os.path.getmtime(path)
            self.__dict__.setdefault("_core_sigs", {})[ap] = self._core_sig(json.loads(txt))
            self.__dict__.setdefault("_saved_score", {})[ap] = data_score(d_)
            for kind in rp_due(path):   # 定期の復元ポイント（書き込みは別の処理で）
                BG_WRITER.put(lambda kind=kind, data=data: rp_write(path, kind, data))
            self._groc_local = False
            self._file_sha[ap] = hashlib.sha1(data).hexdigest()
            if mm is self.mm:
                self._shop_deleted = 0   # 画面で削除した数（保存の守りで使う）を数え直す
            if history is not None:
                self._save_undo(path, history)

        def _protect_before_save(self, path, ap, mm, d_):
            """保存の前の守り（4.3）：IN/OUT_Navi の入力・品が前に保存した中身より大きく減っていたら、前の中身から戻す。
            戻したら知らせ、前の中身は「保存前の退避」の復元ポイントにも残す"""
            prev = (getattr(self, "_saved_score", None) or {}).get(ap)
            if not prev or not os.path.exists(path):
                return d_
            now_ = data_score(d_)
            if not ((prev.get("shop_info", 0) >= 5 and now_["shop_info"] < prev["shop_info"] * 0.5) or
                    (prev.get("shop", 0) >= 5 and now_["shop"] < prev["shop"] * 0.5)):
                return d_
            try:
                with open(path, "rb") as f:
                    raw = f.read()
                old = json.loads(raw.decode("utf-8"))
            except (OSError, ValueError):
                return d_
            old_sh = (old.get("view") or {}).get("shopping")
            cur_sh = mm.view.setdefault("shopping", {})
            n_fill, n_add = shopping_protect(cur_sh, old_sh, getattr(self, "_shop_deleted", 0) if mm is self.mm else 0)
            if not (n_fill or n_add):
                return d_
            rp_write(path, "guard", raw)
            w_ = getattr(self, "shop_win", None)
            if w_ is not None and mm is self.mm:   # 開いている IN/OUT_Navi も直したデータで描き直す
                try:
                    w_.data = cur_sh
                    w_.refresh()
                except Exception:
                    pass
            msg = (f"IN/OUT_Navi のデータが大きく減ろうとしたので、前に保存した中身から戻しました"
                   f"（入力を補った品 {n_fill}・戻した品 {n_add}）。")
            self.set_status("⚠ " + msg)
            try:
                messagebox.showwarning(APP_NAME, msg + "\n\n意図して消した場合は、IN/OUT_Navi の ✕・Delete で消してください"
                                                   "（画面で消した品は戻しません）。", parent=self.root)
            except tk.TclError:
                pass
            return mm.to_dict()

        def _check_guard_on_open(self):
            """開いたとき（4.3）：前回 Mind_Navi で保存したときの数より大きく減っていたら知らせて、戻す画面を出す
            （古い版のPCやほかの道具で上書きされたときに気づけるように）"""
            st = self.mm.view.get("mn_guard")
            if not isinstance(st, dict) or not self.path:
                return
            now_ = data_score(self.mm.to_dict())
            names = {"nodes": "ノード", "shop": "IN/OUT_Navi の品", "shop_info": "IN/OUT_Navi の入力（状態・★など）",
                     "groc": "買い物リストの品"}
            drop = [k for k in names if int(st.get(k) or 0) >= 5 and now_.get(k, 0) < int(st.get(k) or 0) * 0.5]
            if not drop:
                return
            msg = "、".join(f"{names[k]} {st.get(k)}→{now_.get(k, 0)}" for k in drop)
            if messagebox.askyesno(APP_NAME, f"前回 Mind_Navi {st.get('ver', '')} で保存したとき（{str(st.get('at', ''))[:16]}）より、"
                                             f"データが大きく減っています。\n\n{msg}\n\n"
                                             "古い版の Mind_Navi のPCなどで上書きされた可能性があります。\n"
                                             "復元ポイントから戻す画面を開きますか？", parent=self.root):
                self.restore_dialog(focus="shop_info" if "shop_info" in drop else "shop" if "shop" in drop else "nodes")

        def _save_guard(self, path, ap, d_):
            """保存しようとしているデータが、前に保存したときより大きく減っていないか（不具合での消失を防ぐ）。
            減っていたら、今のファイルの中身を「保存前の退避」の復元ポイントとして残し、入力が消えたときは知らせる"""
            prev = (getattr(self, "_saved_score", None) or {}).get(ap)
            if not prev or not os.path.exists(path):
                return
            now_ = data_score(d_)
            drop = [k for k in prev if prev[k] >= 5 and now_.get(k, 0) < prev[k] * 0.5]
            if not drop:
                return
            try:
                with open(path, "rb") as f:
                    old = f.read()
            except OSError:
                return
            rp_write(path, "guard", old)   # 確実に残す（その場で書く）
            names = {"nodes": "ノード", "shop": "IN/OUT_Navi の品", "shop_info": "IN/OUT_Navi の入力（状態・★など）",
                     "groc": "買い物リストの品"}
            msg = "、".join(f"{names[k]} {prev[k]}→{now_.get(k, 0)}" for k in drop)
            self.set_status(f"⚠ データが大きく減りました（{msg}）。前の中身を復元ポイント「保存前の退避」に残しました")
            wiped = "shop_info" in drop and now_.get("shop", 0) >= prev.get("shop", 0) * 0.9   # 品はあるのに入力だけ消えた
            if wiped or "nodes" in drop:
                try:
                    messagebox.showwarning(APP_NAME, f"保存しようとしているデータが、前より大きく減っています。\n\n{msg}\n\n"
                                                     "念のため、前の中身を復元ポイント「保存前の退避」に残しました。\n"
                                                     "意図しない変化なら［ファイル］→［復元ポイントから戻す…］で戻せます。",
                                           parent=self.root)
                except tk.TclError:
                    pass

        def _undo_path(self, path):
            return os.path.join(version_dir(path), "undo.json.gz")

        def _save_undo(self, path, history):
            """元に戻す履歴（直近 UNDO_MAX 操作）をファイルごとに保存。次に開いたときも続けて戻れる"""
            up = self._undo_path(path)
            sha = self._file_sha.get(os.path.abspath(path))
            hist = list(history[-UNDO_MAX:])   # 中身は文字列（変わらない）なので、そのまま別の処理に渡せる
            sig = (sha, len(hist), id(hist[-1]) if hist else None)
            last = self.__dict__.setdefault("_undo_sig", {})
            if last.get(up) == sig:   # 前回から変わっていなければ書かない
                return
            last[up] = sig

            def write():   # 圧縮と書き込みは別の処理で（画面を待たせない。速さ優先の圧縮）
                os.makedirs(os.path.dirname(up), exist_ok=True)
                with gzip.open(up + ".tmp", "wt", encoding="utf-8", compresslevel=1) as f:
                    json.dump({"sha": sha, "history": hist}, f, ensure_ascii=False)
                os.replace(up + ".tmp", up)
            BG_WRITER.put(write)

        def _load_undo(self, path):
            """保存しておいた元に戻す履歴。ファイルがその後に別の場所で変わっていたら使わない"""
            if not path:
                return []
            BG_WRITER.flush()   # 書きかけがあれば書き終わってから読む
            try:
                with gzip.open(self._undo_path(path), "rt", encoding="utf-8") as f:
                    rec = json.load(f)
            except (OSError, ValueError, EOFError):
                return []
            if not rec.get("sha") or rec.get("sha") != self._file_sha.get(os.path.abspath(path)):
                return []
            return [h for h in rec.get("history") or [] if isinstance(h, str)][-UNDO_MAX:]

        def _changed_outside(self, path):
            """開いた後に別の場所（別のPC・Googleドライブの同期など）でファイルが書きかえられたか"""
            ap = os.path.abspath(path)
            k = self._known_mtime.get(ap)
            if k is None or not os.path.exists(ap):
                return False
            return os.path.getmtime(ap) > k + 2

        def autosave(self, reason=""):
            """変更のあるマップを保存先へ自動で保存。戻り値：保存した数"""
            n, warn = 0, []
            for j, s_ in enumerate(self.slots):
                if not s_:
                    continue
                if j == self.cur:
                    path, mm, dirty = self.path, self.mm, self.dirty
                    if self._busy_editing():
                        continue
                else:
                    doc = s_.get("doc")
                    if not doc:
                        continue
                    path, mm, dirty = doc["path"], doc["mm"], doc["dirty"]
                if not dirty or not path or not path.lower().endswith(".json"):
                    continue   # 無題のマップはバックアップだけ（保存先は［名前を付けて保存］で決める）
                if self._changed_outside(path) and not (j == self.cur and self.adopt_outside_groceries(path, quiet=True)):
                    warn.append(os.path.basename(path))
                    continue   # 別の場所での変更を上書きしない（バックアップには残る）
                try:
                    if j == self.cur:
                        self.mm.view.update(style=self.style, auto_layout=self.v_auto.get())
                        self.mm.store_positions(self.style)
                    self._write_doc(path, mm, self.history if j == self.cur else s_["doc"].get("history") or [])
                except (OSError, TypeError, ValueError) as err:
                    warn.append(f"{os.path.basename(path)}（{err}）")
                    continue
                if j == self.cur:
                    self.dirty = False
                else:
                    s_["doc"]["dirty"] = False
                self._drop_backup(path, j)
                n += 1
            if n:
                self.last_autosave = datetime.datetime.now()
                self.update_title()
                try:
                    self.refresh_slots()
                except Exception:
                    pass
                if not warn and reason != "操作":
                    self.set_status(f"自動保存しました（{self.last_autosave:%H:%M}{'・' + reason if reason else ''}）"
                                    f"　Ctrl+Z で {UNDO_MAX} 操作まで戻れます")
            if warn and not getattr(self, "_autosave_warned", False):
                self._autosave_warned = True
                self.set_status("⚠ 自動保存を止めています：" + "、".join(warn) +
                                " が別の場所で更新されました。［ファイル］→［開く］で読み直すか、［保存］で上書きしてください")
            return n

        def _drop_backup(self, path, slot=None):
            """保存した・変更を破棄したときはバックアップを消す"""
            for bp in {backup_path(path, slot) if path else None, backup_path(None, slot)}:
                if bp:
                    def drop(bp=bp):   # 書き込みと同じ順番で（先に頼んだ書き込みの後に消す）
                        if os.path.exists(bp):
                            os.remove(bp)
                    BG_WRITER.put(drop)
                    self._bak_last.pop(bp, None)

        def _load_checked(self, p):
            """ファイルを読む。バックアップの方が新しければ、どちらから開くか確認する。
            戻り値: (マップ, バックアップから開いたか)"""
            BG_WRITER.flush()   # バックアップの書きかけがあれば書き終わってから比べる
            try:
                self._known_mtime[os.path.abspath(p)] = os.path.getmtime(p)
                with open(p, "rb") as fb_:
                    raw_ = fb_.read()
                self._file_sha[os.path.abspath(p)] = hashlib.sha1(raw_).hexdigest()
                if p.lower().endswith(".json") and raw_:   # 開いたときの中身を、読み替える前にそのまま復元ポイントへ
                    BG_WRITER.put(lambda p=p, raw_=raw_: rp_write(p, "open", raw_))
                try:
                    d0_ = json.loads(raw_.decode("utf-8"))
                    self.__dict__.setdefault("_core_sigs", {})[os.path.abspath(p)] = self._core_sig(d0_)
                    self.__dict__.setdefault("_saved_score", {})[os.path.abspath(p)] = data_score(d0_)
                except ValueError:
                    pass
            except OSError:
                pass
            bp = backup_path(p) if p.lower().endswith(".json") else None
            if bp and os.path.exists(bp):
                bt = os.path.getmtime(bp)
                ft = os.path.getmtime(p) if os.path.exists(p) else 0
                if bt > ft + 1:
                    name = os.path.basename(p)
                    ans = messagebox.askyesno(
                        f"{APP_NAME} - バックアップの確認",
                        f"「{name}」には、保存ファイルより新しいバックアップがあります。\n\n"
                        f"保存ファイル　：{_mtime_text(ft) if ft else '（見つかりません）'}\n"
                        f"バックアップ　：{_mtime_text(bt)}\n\n"
                        "前回、保存せずに終了した（または異常終了した）可能性があります。\n"
                        "バックアップファイルから開きますか？\n\n"
                        "はい　：バックアップから開く（保存すると元のファイルに上書きされます）\n"
                        "いいえ：保存ファイルから開く（バックアップは別名で残します）",
                        icon="warning", parent=self.root)
                    if ans:
                        try:
                            with open(bp, encoding="utf-8") as fp:
                                return MindNavi.from_dict(json.load(fp)), True
                        except (OSError, ValueError) as err:
                            messagebox.showerror(APP_NAME, f"バックアップを読み込めませんでした:\n{err}",
                                                 parent=self.root)
                    else:
                        stamp = datetime.datetime.fromtimestamp(bt).strftime("%Y%m%d_%H%M%S")
                        try:   # 次回からは聞かない（ファイルは残す）
                            os.replace(bp, bp[:-5] + f"_不採用_{stamp}.json")
                        except OSError:
                            pass
            try:
                mm_ = MindNavi.load(p)
                if p.lower().endswith(".json"):
                    self._snapshot(p, mm_)   # 開いた時点の内容もバックアップに残す
                return mm_, False
            except (OSError, ValueError, KeyError, TypeError) as err:
                if not p.lower().endswith(".json"):
                    raise
                got = self._recover_from_backup(p, err)
                if got is None:
                    raise
                return got, True

        def _backup_candidates(self, p):
            """そのファイルのバックアップ（新しい順）：[(更新時刻, ファイル)]"""
            BG_WRITER.flush()
            out = []
            vd = version_dir(p)
            try:
                out += [(os.path.getmtime(os.path.join(vd, f)), os.path.join(vd, f))
                        for f in os.listdir(vd) if f.endswith(".json")]
            except OSError:
                pass
            bp = backup_path(p)
            if os.path.exists(bp):
                out.append((os.path.getmtime(bp), bp))
            out = sorted(out, reverse=True)
            mp = mirror_path(p)
            if mp and os.path.exists(mp):   # 同じフォルダのバックアップファイル（最後に保存したものと同じ内容）を最初に
                out.insert(0, (os.path.getmtime(mp), mp))
            return out

        def _recover_from_backup(self, p, err):
            """メインファイルが壊れて読めないとき：読めるいちばん新しいバックアップから復元する"""
            for t_, bp in self._backup_candidates(p):
                try:
                    with open(bp, encoding="utf-8") as fp:
                        mm = MindNavi.from_dict(json.load(fp))
                except (OSError, ValueError, KeyError, TypeError):
                    continue   # これも壊れていたら、ひとつ前の版へ
                name = os.path.basename(p)
                ok = messagebox.askyesno(
                    f"{APP_NAME} - ファイルの復元",
                    f"「{name}」が壊れていて読み込めませんでした。\n（{err}）\n\n"
                    f"バックアップ（{_mtime_text(t_)}）から復元しますか？\n\n"
                    "はい　：バックアップから復元（壊れたファイルは「_壊れたファイル_日時.json」として残し、"
                    "復元した内容で上書き保存します）\n"
                    "いいえ：復元しない",
                    icon="warning", parent=self.root)
                if not ok:
                    return None
                stamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
                try:
                    if os.path.exists(p):
                        shutil.copy2(p, os.path.splitext(p)[0] + f"_壊れたファイル_{stamp}.json")
                    self._write_doc(p, mm)
                except OSError:
                    pass
                self.set_status(f"バックアップ（{_mtime_text(t_)}）から「{name}」を復元しました")
                return mm
            return None

        def _offer_untitled_backups(self):
            """保存していない（無題の）マップのバックアップがあれば開くか確認"""
            BG_WRITER.flush()
            try:
                files = sorted(f for f in os.listdir(BACKUP_DIR)
                               if f.startswith("untitled_slot") and f.endswith(".json"))
            except OSError:
                return
            for f in files:
                bp = os.path.join(BACKUP_DIR, f)
                ans = messagebox.askyesnocancel(
                    f"{APP_NAME} - バックアップの確認",
                    f"保存されていないマップのバックアップがあります（{_mtime_text(os.path.getmtime(bp))}）。\n\n"
                    "バックアップファイルから開きますか？\n\n"
                    "はい　：空いているボタンに開く\nいいえ：開かない（バックアップは別名で残します）\n"
                    "キャンセル：今回は何もしない",
                    icon="warning", parent=self.root)
                if ans is None:
                    continue
                if not ans:
                    try:
                        os.replace(bp, bp[:-5] + f"_不採用_{datetime.datetime.now():%Y%m%d_%H%M%S}.json")
                    except OSError:
                        pass
                    continue
                try:
                    with open(bp, encoding="utf-8") as fp:
                        mm = MindNavi.from_dict(json.load(fp))
                except (OSError, ValueError) as err:
                    messagebox.showerror(APP_NAME, f"バックアップを読み込めませんでした:\n{err}", parent=self.root)
                    continue
                cur_blank = (not self.path and not self.dirty and len(self.mm.nodes) <= 1)
                free = self.cur if cur_blank else next((j for j, s_ in enumerate(self.slots) if s_ is None), None)
                if free is None:
                    messagebox.showinfo(APP_NAME, "空いているボタンがありません。ボタンの登録を1つ解除してから"
                                                  "再度起動してください。", parent=self.root)
                    return
                if free != self.cur:
                    self._leave_current()
                    self.cur = free
                self.slots[free] = {"path": None, "name": "", "doc": None}
                self.mm, self.path, self.dirty = mm, None, True
                self.history, self.future = [], []
                try:
                    os.remove(bp)   # 開いた内容は新しいボタンの番号で改めてバックアップされる
                except OSError:
                    pass
                self._after_load()
                self.set_status("バックアップから開きました。「名前を付けて保存」で保存してください")

        def restore_dialog(self, focus=None):
            """復元ポイントから戻す（2026-11-08）：開いたとき・1時間ごと・毎日・毎月・保存前の退避・自動保存の版 から選び、
            全部／IN/OUT_Navi だけ／買い物リストだけ を戻す、または IN/OUT_Navi の消えた入力だけを補う。
            戻す前の中身も復元ポイント「戻す前」に残すので、やり直せる"""
            if not self.path:
                messagebox.showinfo(APP_NAME, "保存先のあるマップで使えます", parent=self.root)
                return
            self.on_transition("復元の前", defer=False)
            BG_WRITER.flush()
            cands = [(t, RP_NAME.get(k, k), fp) for t, k, fp in rp_list(self.path)]
            for t_, bp in self._backup_candidates(self.path):   # 以前からの自動保存の版・同じフォルダのバックアップ
                kind = "同じフォルダの .backup" if bp == mirror_path(self.path) else "自動保存の版"
                cands.append((datetime.datetime.fromtimestamp(t_), kind, bp))
            for lp in (SHOP_PATH, SHOP_PATH + ".imported"):   # 以前このPCだけに保存していた IN/OUT_Navi（購入分析）
                if os.path.exists(lp):
                    cands.append((datetime.datetime.fromtimestamp(os.path.getmtime(lp)), "以前のPCの購入分析", lp))
            cands.sort(key=lambda c: c[0], reverse=True)
            w = tk.Toplevel(self.root)
            w.title("復元ポイントから戻す")
            w.transient(self.root)
            w.geometry("860x560")
            ttk.Label(w, padding=(10, 8), wraplength=820, justify="left",
                      text=f"「{os.path.basename(self.path)}」の復元ポイント（新しい順）。選ぶと下に中身の数を表示します。\n"
                           "戻す前の中身は復元ポイント「戻す前」に残るので、いつでもやり直せます。"
                           "Google ドライブの「版を管理」でダウンロードした古いファイルは［ファイルを選ぶ…］で使えます。").pack(anchor="w")
            tf = ttk.Frame(w)
            tf.pack(fill="both", expand=True, padx=10)
            tv = ttk.Treeview(tf, columns=("t", "k", "w"), show="headings", selectmode="browse")
            for c, txt, wd in (("t", "日時", 170), ("k", "種類", 170), ("w", "場所", 460)):
                tv.heading(c, text=txt)
                tv.column(c, width=wd, anchor="w")
            sb = ttk.Scrollbar(tf, orient="vertical", command=tv.yview)
            tv.configure(yscrollcommand=sb.set)
            sb.pack(side="right", fill="y")
            tv.pack(fill="both", expand=True)
            rows = {}

            def add(t, kind, fp, top=False):
                iid = f"r{len(rows)}"
                rows[iid] = fp
                where = "このPC" if os.path.abspath(fp).startswith(os.path.abspath(BACKUP_DIR)) else os.path.dirname(fp)
                tv.insert("", 0 if top else "end", iid=iid, values=(t.strftime("%Y/%m/%d %H:%M:%S"), kind, where))
                return iid
            for t, kind, fp in cands:
                add(t, kind, fp)
            info = tk.StringVar(value="（復元ポイントを選んでください）")
            ttk.Label(w, textvariable=info, padding=(10, 6), foreground="#1864ab",
                      font=(self.fam_base, 10, "bold")).pack(anchor="w")
            cache = {}

            def load(iid):
                fp = rows[iid]
                if fp not in cache:
                    d = read_data_file(fp)
                    if isinstance(d, dict) and "nodes" not in d and "items" in d:   # IN/OUT_Navi だけのファイル
                        d = {"nodes": [], "view": {"shopping": d}}
                    cache[fp] = d
                return cache[fp]

            def on_sel(ev=None):
                sel = tv.selection()
                if not sel:
                    return
                try:
                    sc = data_score(load(sel[0]))
                except (OSError, ValueError, EOFError) as err:
                    info.set(f"読めません：{err}")
                    return
                cur = data_score(self.mm.to_dict())
                info.set(f"この時点：ノード {sc['nodes']}　IN/OUT_Navi {sc['shop']}品（入力あり {sc['shop_info']}）　"
                         f"買い物リスト {sc['groc']}品　　｜　今：ノード {cur['nodes']}　IN/OUT_Navi {cur['shop']}品"
                         f"（入力あり {cur['shop_info']}）　買い物リスト {cur['groc']}品")
            tv.bind("<<TreeviewSelect>>", on_sel)

            def pick_file():
                fp = filedialog.askopenfilename(parent=w, title="戻すのに使うデータファイル",
                                                filetypes=[("Mind_Navi のデータ", "*.json *.json.gz"), ("すべて", "*.*")])
                if fp:
                    iid = add(datetime.datetime.fromtimestamp(os.path.getmtime(fp)), "選んだファイル", fp, top=True)
                    tv.selection_set(iid)
                    tv.see(iid)

            def do(mode):
                sel = tv.selection()
                if not sel:
                    messagebox.showinfo(APP_NAME, "復元ポイントを選んでください", parent=w)
                    return
                try:
                    d = load(sel[0])
                except (OSError, ValueError, EOFError) as err:
                    messagebox.showerror(APP_NAME, f"このファイルは読めません：\n{err}", parent=w)
                    return
                msg = self._apply_restore(d, mode, parent=w)
                if msg:
                    info.set(msg)
                    messagebox.showinfo(APP_NAME, msg, parent=w)
                    on_sel()
            bf = ttk.Frame(w, padding=8)
            bf.pack(fill="x")
            ttk.Button(bf, text="ファイルを選ぶ…", command=pick_file).pack(side="left")
            ttk.Button(bf, text="閉じる", command=w.destroy).pack(side="right")
            for txt, mode in (("全部をこの時点に戻す", "all"), ("買い物リストだけ戻す", "groc"), ("IN/OUT_Navi だけ戻す", "shop"),
                              ("IN/OUT_Navi の消えた入力を補う", "fill")):
                ttk.Button(bf, text=txt, command=lambda m=mode: do(m)).pack(side="right", padx=3)
            if rows:
                first = next(iter(rows))
                if focus:   # その数（IN/OUT_Navi の入力など）がいちばん多い時点を選んでおく
                    metric = "shop_info" if focus == "fill" else focus
                    best = None
                    for iid in list(rows)[:200]:
                        try:
                            n_ = data_score(load(iid)).get(metric, 0)
                        except (OSError, ValueError, EOFError):
                            continue
                        if best is None or n_ > best[0]:
                            best = (n_, iid)
                    first = best[1] if best else first
                tv.selection_set(first)
                tv.see(first)

        def _apply_restore(self, d, mode, parent=None):
            """復元ポイントの中身 d を戻す。mode：all＝全部、shop＝IN/OUT_Navi、groc＝買い物リスト、fill＝IN/OUT_Navi の消えた入力を補う"""
            v = (d or {}).get("view") or {}
            if mode in ("shop", "fill") and not isinstance(v.get("shopping"), dict):
                messagebox.showinfo(APP_NAME, "この復元ポイントには IN/OUT_Navi のデータがありません", parent=parent)
                return None
            if mode == "groc" and not isinstance(v.get("groceries"), dict):
                messagebox.showinfo(APP_NAME, "この復元ポイントには買い物リストのデータがありません", parent=parent)
                return None
            if mode == "all" and not d.get("nodes"):
                messagebox.showinfo(APP_NAME, "このファイルはマップ全体のデータではありません（IN/OUT_Navi だけ戻せます）", parent=parent)
                return None
            names = {"all": "全部", "shop": "IN/OUT_Navi", "groc": "買い物リスト", "fill": "IN/OUT_Navi の消えた入力"}
            if mode != "fill" and not messagebox.askyesno(APP_NAME, f"{names[mode]}をこの時点に戻しますか？\n"
                                                                     "（今の中身は復元ポイント「戻す前」に残します）", parent=parent):
                return None
            BG_WRITER.flush()
            if self.path and os.path.exists(self.path):   # 戻す前の中身を残す（やり直せるように）
                try:
                    with open(self.path, "rb") as f:
                        rp_write(self.path, "restore", f.read())
                except OSError:
                    pass
            self._close_data_windows()
            import copy as _copy
            if mode == "all":
                self.checkpoint()
                self._restore(json.dumps(d, ensure_ascii=False))
                for k in SHARED_VIEW_KEYS:   # 別画面のデータもこの時点に
                    if k in v:
                        self.mm.view[k] = _copy.deepcopy(v[k])
                msg = "全部をこの時点に戻しました"
            elif mode == "shop":
                self.mm.view["shopping"] = shopping_upgrade(_copy.deepcopy(v["shopping"]))
                msg = "IN/OUT_Navi をこの時点に戻しました"
            elif mode == "groc":
                self.mm.view["groceries"] = groceries_normalize(_copy.deepcopy(v["groceries"]))
                msg = "買い物リストをこの時点に戻しました"
            else:
                cur = self.mm.view.setdefault("shopping", {})
                shopping_upgrade(cur)
                n = shopping_fill_lost(cur, v["shopping"])
                msg = (f"IN/OUT_Navi の {n} 品に、消えていた入力（状態・★・売却価格など）を戻しました" if n else
                       "この復元ポイントからは、補える入力はありませんでした（別の時点を選んでください）")
                if not n:
                    return msg
            self.dirty = True
            self._guard_skip = True   # 戻した中身はそのまま保存する（保存の守りを通さない）
            self.touch()
            self.redraw()
            self.on_transition("復元", defer=False)
            self.set_status(msg)
            return msg

        def open_backup_folder(self):
            os.makedirs(BACKUP_DIR, exist_ok=True)
            try:
                if sys.platform.startswith("win"):
                    os.startfile(BACKUP_DIR)   # エクスプローラーで開く
                else:
                    import subprocess
                    subprocess.Popen(["open" if sys.platform == "darwin" else "xdg-open", BACKUP_DIR])
            except Exception:
                messagebox.showinfo(APP_NAME, f"バックアップの保存先:\n{BACKUP_DIR}")

        def _startup(self, path):
            if path:
                hit = self._slot_of(path)
                if hit is None:
                    hit = next((j for j, s in enumerate(self.slots) if s is None), self.cur)
                    self.slots[hit] = {"path": path, "name": "", "doc": None}
                self.cur = hit
            s = self.slots[self.cur]
            if s is None:
                s = self.slots[self.cur] = {"path": None, "name": "", "doc": None}
            if not (s.get("path") and self.open_path(s["path"])):
                s["path"] = None
                self.new(confirm=False)
            self._offer_untitled_backups()

        # ================= 画面構成 =================
        def _build(self):
            r = self.root
            r.geometry("1280x800")
            r.minsize(820, 560)
            try:   # 起動時は最大化して表示
                if sys.platform.startswith("win"):
                    r.state("zoomed")
                elif sys.platform == "darwin":
                    r.geometry(f"{r.winfo_screenwidth()}x{r.winfo_screenheight() - 60}+0+0")
                else:
                    r.attributes("-zoomed", True)
            except tk.TclError:
                r.geometry(f"{r.winfo_screenwidth()}x{r.winfo_screenheight() - 60}+0+0")

            def ensure_big():   # ウインドウマネージャーが最大化に対応しないときは画面いっぱいの大きさに
                try:
                    if r.winfo_width() < r.winfo_screenwidth() * 0.9 and r.state() != "zoomed":
                        r.geometry(f"{r.winfo_screenwidth()}x{r.winfo_screenheight() - 60}+0+0")
                except tk.TclError:
                    pass
            r.after(300, ensure_big)
            # 日本語の幅で正しく測れるよう、画面全体のフォントを日本語フォントに揃える
            ttk.Style().configure(".", font=(self.fam_base, 10))
            for name in ("TkDefaultFont", "TkMenuFont", "TkTextFont"):
                tkfont.nametofont(name).configure(family=self.fam_base)
            self._build_menubar()

            self._mission_labels = []
            top = ttk.Frame(r, padding=(8, 4))
            top.pack(fill="x")
            self.tb = top
            self.tb_left = tl = ttk.Frame(top)
            self.tb_right = tr = ttk.Frame(top)
            tl.pack(side="left")
            tr.pack(side="right")
            self._tb_wrapped = False
            # ツールバー：左から［マップ］［表示］［ツール］｜右に［展開］［絞り込み］（よく使う操作だけ。残りはメニューに）
            def sep(parent):
                ttk.Separator(parent, orient="vertical").pack(side="left", fill="y", padx=8, pady=2)

            def head(parent, text):
                ttk.Label(parent, text=text, foreground="#495057").pack(side="left", padx=(0, 3))
            head(tl, "マップ")
            self.slot_buttons = []
            for i in range(SLOT_COUNT):
                b = ttk.Radiobutton(tl, value=i, variable=self.v_slot, style="Toolbutton", width=-7,
                                    command=lambda i=i: self.on_slot_click(i))
                b.pack(side="left", padx=1)
                for seq in ("<Button-3>", "<Button-2>") if sys.platform == "darwin" else ("<Button-3>",):
                    b.bind(seq, lambda ev, i=i: self.on_slot_menu(ev, i))
                self.slot_buttons.append(b)
            sep(tl)
            head(tl, "表示")
            for key, label in STYLES.items():
                ttk.Radiobutton(tl, text=label, value=key, variable=self.v_style, style="Toolbutton",
                                command=lambda k=key: self.set_style(k)).pack(side="left", padx=1)
            sep(tl)
            head(tl, "ツール")
            ttk.Button(tl, text="振り返り", width=-5, command=lambda: self.open_review(
                "day", getattr(self, "cal_sel_date", None) if self.style == "calendar" else None)).pack(side="left", padx=1)
            ttk.Button(tl, text="メモ", width=-5, command=self.open_memo).pack(side="left", padx=1)
            ttk.Button(tl, text="IN/OUT_Navi", width=-5, command=self.open_shopping).pack(side="left", padx=1)
            ttk.Button(tl, text="買い物リスト", width=-5, command=self.open_grocery).pack(side="left", padx=1)
            ttk.Button(tl, text="タスク分析", width=-5, command=self.open_task_ana).pack(side="left", padx=1)
            ttk.Button(tl, text="ライフプラン", width=-5, command=self.open_lifeplan).pack(side="left", padx=1)
            ttk.Button(tl, text="🧘 Vipassana", width=-5, command=lambda: self.open_vipassana()).pack(side="left", padx=1)
            sep(tl)
            head(tl, "デザイン")
            dnames = {k_: c_["name"].split("（")[0] for k_, c_ in DESIGNS.items()}
            self.v_design_name = tk.StringVar(value=dnames.get(getattr(self, "design", "office"), "オフィス"))
            cbd = ttk.Combobox(tl, textvariable=self.v_design_name, values=list(dnames.values()), state="readonly", width=7)
            cbd.pack(side="left", padx=1)
            cbd.bind("<<ComboboxSelected>>", lambda ev: self.set_design(next(k_ for k_, n_ in dnames.items()
                                                                             if n_ == self.v_design_name.get())))
            # 右側：展開・絞り込み
            head(tr, "展開")
            ttk.Button(tr, text="★タスクリストのツリー", width=-12, command=self.focus_tree_view).pack(side="left", padx=(0, 2))
            for k, lbl in ((1, "1"), (2, "2"), (3, "3"), (None, "全")):
                ttk.Button(tr, text=lbl, width=-3, command=lambda k=k: self.show_level(k)).pack(side="left")
            sep(tr)
            head(tr, "アクティブ")
            for k, lbl in (("day", "日"), ("week", "週"), ("month", "月"), ("year", "年")):
                ttk.Button(tr, text=lbl, width=-3, command=lambda k=k: self.active_tree_view(k)).pack(side="left")
            ttk.Button(tr, text="×", width=-2, command=self.clear_active_tree).pack(side="left")
            sep(tr)
            head(tr, "絞り込み")
            self.v_flt = {k: tk.BooleanVar() for k in ("undone", "1", "2", "3")}
            ttk.Checkbutton(tr, text="未完了", variable=self.v_flt["undone"], style="Toolbutton", width=-5,
                            command=lambda: self.set_filter(undone=self.v_flt["undone"].get())).pack(side="left")
            for k in ("1", "2", "3"):
                ttk.Checkbutton(tr, text=f"重{k}", variable=self.v_flt[k], style="Toolbutton", width=-3,
                                command=lambda k=k: self.set_filter(toggle_pri=k)).pack(side="left")
            ttk.Button(tr, text="解除", width=-3, command=lambda: self.set_filter(clear=True)).pack(side="left", padx=(2, 0))

            # 画面の区切り：左パネル（ウィークリーコンパス・達成率・タスクリスト…）｜ マップ・カレンダー
            #   境界線（灰色の帯）にマウスを置いてドラッグで幅を変更。ダブルクリックで自動の幅に戻す
            pane_opt = dict(sashwidth=8, sashrelief="raised", bd=0, bg="#adb5bd", opaqueresize=True,
                            sashcursor="sb_h_double_arrow")
            self.hpane = hp = tk.PanedWindow(r, orient="horizontal", **pane_opt)
            hp.pack(fill="both", expand=True)
            self.main_area = ma = tk.Frame(hp)
            self.panel = p = ttk.Frame(hp, padding=6, width=self.panel_w or 350)
            p.pack_propagate(False)
            hp.add(p, stretch="never", minsize=260, width=self.panel_w or 350)
            hp.add(ma, stretch="always", minsize=460)
            # 右：タスクリスト
            self.rpanel = rp = ttk.Frame(hp, padding=6, width=getattr(self, "rpanel_w", None) or 430)
            rp.pack_propagate(False)
            hp.add(rp, stretch="never", minsize=240, width=getattr(self, "rpanel_w", None) or 430)
            self.canvas = c = tk.Canvas(ma, bg=STYLE_BG["office"], highlightthickness=0, takefocus=1)
            c.pack(fill="both", expand=True)
            hp.bind("<ButtonRelease-1>", self._on_sash_release, add="+")
            hp.bind("<Double-Button-1>", self._sash_reset, add="+")
            self.nb = ttk.Notebook(p)
            self.nb.pack(fill="both", expand=True)
            self.tab_focus = ttk.Frame(self.nb, padding=(4, 8))
            tab_detail = ttk.Frame(self.nb, padding=(4, 8))
            self.nb.add(self.tab_focus, text="ウィークリーコンパス")
            self.nb.add(tab_detail, text="詳細")
            self._build_focus_list(self.tab_focus)
            self._build_panel(tab_detail)

            self.status = ttk.Label(r, padding=(8, 3), foreground="#444")
            self.status.pack(side="bottom", fill="x", before=self.hpane)   # 狭い画面でも状態表示が隠れないように
            self.set_status()
            self._build_context_menus()
            self._bind_keys()

        def open_memo(self):
            self.on_transition()
            w = getattr(self, "memo_win", None)
            if w is not None and w.win.winfo_exists():
                w.win.lift()
                return
            self.memo_win = MemoWin(self)

        def open_lifeplan(self):
            self.on_transition()
            w = getattr(self, "life_win", None)
            if w is not None and w.win.winfo_exists():
                w.win.lift()
                return
            self.life_win = LifePlanWin(self)

        def open_review(self, period="day", day=None):
            self.on_transition()
            w = getattr(self, "review_win", None)
            if w is not None and w.win.winfo_exists():
                w.v_period.set(period)
                w.go(day or w.day)
                w.win.lift()
                return
            self.review_win = ReviewWin(self, period, day)

        def _ana_mode_changed(self):
            """タスク分析マップの表示の切り替え（タスクリストの下と拡大画面の両方）"""
            if getattr(self, "ana_panel", None) is not None:
                self.ana_panel.draw()
            w = getattr(self, "task_ana_win", None)
            if w is not None and w.win.winfo_exists():
                w.refresh()

        def set_design(self, key):
            """全画面のデザインスタイルを切り替える（その場で反映し、次回もこのスタイルで開く）"""
            if key not in DESIGNS:
                return
            self.design = key
            if getattr(self, "v_design", None) is not None:
                self.v_design.set(key)
            if getattr(self, "v_design_name", None) is not None:
                self.v_design_name.set(DESIGNS[key]["name"].split("（")[0])
            apply_design(self.root, key, self._base_theme)
            self.save_settings()
            self.redraw()
            for attr in ("shop_win", "task_ana_win", "grocery_win", "review_win", "life_win", "memo_win"):   # 開いている画面も描き直す
                w = getattr(self, attr, None)
                for m in ("refresh", "draw"):
                    try:
                        if w is not None and w.win.winfo_exists() and hasattr(w, m):
                            getattr(w, m)()
                            break
                    except Exception:
                        pass
            self._schedule_week_panel()
            if getattr(self, "ana_panel", None) is not None:
                self.ana_panel.draw()
            self.set_status(f"デザインスタイルを「{DESIGNS[key]['name']}」にしました")

        def open_vipassana(self, parent=None):
            w = getattr(self, "vip_win", None)
            if w is not None and w.win.winfo_exists():
                w.win.lift()
                return
            self.vip_win = VipassanaWin(self, parent)

        def vipassana_stats(self, d0, d1):
            """期間の Vipassana：回数・合計分・平均クオリティ（1〜5）"""
            ss = [x for x in (self.mm.view.get("vipassana") or {}).get("sessions", [])
                  if (lambda d_: d_ and d0 <= d_ <= d1)(_date(x.get("date")))]
            qs = [int(x["quality"]) for x in ss if x.get("quality")]
            return len(ss), sum(int(x.get("min") or 0) for x in ss), (sum(qs) / len(qs) if qs else None)

        def open_grocery(self):
            self.adopt_outside_groceries()   # スマホで変えた分を先に取り込む
            self.on_transition()
            w = getattr(self, "grocery_win", None)
            if w is not None and w.win.winfo_exists():
                w.win.lift()
                return
            self.grocery_win = GroceryWin(self)

        def open_task_ana(self):
            self.on_transition()
            w = getattr(self, "task_ana_win", None)
            if w is not None and w.win.winfo_exists():
                w.win.lift()
                w.refresh()
                return
            self.task_ana_win = TaskAnaWin(self)

        def open_shopping(self):
            self.on_transition()
            w = getattr(self, "shop_win", None)
            if w is not None and w.win.winfo_exists():
                w.win.lift()
                return
            self.shop_win = ShoppingWin(self)

        # ---- ミッションステートメント（すべての画面の左上。クリックで書き込み） ----
        def mission_bar(self, parent):
            bar = tk.Frame(parent, bg="#1864ac", cursor="hand2")   # （帯専用の色：デザインスタイルで帯だけの色にする）
            tk.Label(bar, text="MISSION", bg="#1864ac", fg="#a5d8fe", font=(self.fam_base, 8, "bold"),
                     padx=8).pack(side="left", anchor="n", pady=(5, 0))
            lab = tk.Label(bar, bg="#1864ac", fg="#fffffe", font=(self.fam_base, 10, "bold"), anchor="w",
                           justify="left", padx=2, pady=3, cursor="hand2")
            lab.pack(side="left", fill="x", expand=True)
            for w_ in (bar, lab) + tuple(bar.winfo_children()):
                w_.bind("<Button-1>", lambda ev: self.mission_dialog())
            vb = tk.Label(bar, text="🧘 Vipassana", bg="#0b7285", fg="#ffffff", font=(self.fam_base, 9, "bold"),
                          padx=8, pady=2, cursor="hand2")   # どの画面からも 10 分の瞑想
            vb.pack(side="right", padx=4, pady=2, before=lab)
            vb.bind("<Button-1>", lambda ev: (self.open_vipassana(parent.winfo_toplevel()), "break")[1])
            bar.bind("<Configure>", lambda ev, l=lab: l.configure(wraplength=max(200, ev.width - 200)))
            self._mission_labels.append(lab)
            self.refresh_mission()
            return bar

        def refresh_mission(self):
            txt = (getattr(self, "mission", "") or "").strip()
            for lab in list(self._mission_labels):
                try:
                    lab.configure(text=txt.replace("\n", "　／　") if txt else
                                  "（ここをクリックして、ミッションステートメント＝自分の使命・大切にしたいことを書く）",
                                  fg="#fffffe" if txt else "#a5d8fe")
                except tk.TclError:
                    self._mission_labels.remove(lab)

        def mission_dialog(self):
            w = tk.Toplevel(self.root)
            w.title("ミッションステートメント")
            w.transient(self.root)
            f = ttk.Frame(w, padding=10)
            f.pack(fill="both", expand=True)
            ttk.Label(f, text="あなたの使命・大切にしたい価値・目指す姿（すべての画面の左上に表示されます）").pack(anchor="w")
            t = tk.Text(f, width=56, height=6, font=(self.fam_base, 11), wrap="word")
            t.pack(fill="both", expand=True, pady=6)
            t.insert("1.0", getattr(self, "mission", ""))
            t.focus_set()

            def ok(ev=None):
                self.mission = t.get("1.0", "end").strip()
                self.shared_put("mission", {"text": self.mission})   # データファイルに保存（どのPCでも同じ）
                self.save_settings()
                self.refresh_mission()
                w.destroy()
                return "break"
            bf = ttk.Frame(f)
            bf.pack(fill="x")
            ttk.Button(bf, text="保存", command=ok).pack(side="right")
            ttk.Button(bf, text="キャンセル", command=w.destroy).pack(side="right", padx=6)
            ttk.Label(bf, text=f"{ACC}+Enter で保存", foreground="#868e96").pack(side="left")
            t.bind(f"<{MOD}-Return>", ok)
            w.bind("<Escape>", lambda ev: w.destroy())

