        def _auto_accels(self, menubar):
            """メニューのすべての項目にショートカットを付ける（まだないものに Ctrl+Shift／Ctrl+Alt＋英字を順に割り当て）"""
            used = {"D", "S", "Z", "J", "TAB"}
            pool = [("Shift", ch) for ch in "ABCEFGHIKLMNOPQRTUVWXY" if ch not in used] + \
                   [("Alt", ch) for ch in "ABCDEFGHIJKLMNOPQRSTUVWXYZ"]
            mod_lbl = "Cmd" if sys.platform == "darwin" else "Ctrl"

            def walk(menu):
                try:
                    last = menu.index("end")
                except tk.TclError:
                    return
                if last is None:
                    return
                for i in range(last + 1):
                    typ = menu.type(i)
                    if typ == "cascade":
                        sub = menu.nametowidget(menu.entrycget(i, "menu"))
                        if not str(sub.cget("postcommand") or ""):   # 開くたびに中身が変わるメニューは除く
                            walk(sub)
                        continue
                    if typ not in ("command", "checkbutton", "radiobutton"):
                        continue
                    if menu.entrycget(i, "accelerator") or menu.entrycget(i, "state") == "disabled":
                        continue
                    if not pool:
                        return
                    modk, ch = pool.pop(0)
                    seq = f"<{MOD}-{modk}-Key-{ch}>" if modk == "Shift" else f"<{MOD}-{ALT}-Key-{ch.lower()}>"
                    try:
                        self.root.bind(seq, lambda ev, m_=menu, i_=i: (m_.invoke(i_), "break")[1])
                        if modk == "Alt":
                            self.root.bind(f"<{MOD}-{ALT}-Key-{ch}>", lambda ev, m_=menu, i_=i: (m_.invoke(i_), "break")[1])
                    except tk.TclError:
                        continue
                    menu.entryconfigure(i, accelerator=f"{mod_lbl}+{modk}+{ch}")
            for k in range((menubar.index("end") or -1) + 1):
                if menubar.type(k) == "cascade":
                    walk(menubar.nametowidget(menubar.entrycget(k, "menu")))

        def _menu_need_sel(self, menu, need_sel=(), need_sel2=()):
            """選んでいるノードがないと使えない項目を灰色に"""
            on = bool(self.sel and self.sel in self.mm.nodes)
            for i in tuple(need_sel) + tuple(need_sel2):
                try:
                    menu.entryconfigure(i, state="normal" if on else "disabled")
                except tk.TclError:
                    pass

        def _cal_menu_mode(self, mode):
            if self.style != "calendar":
                self.set_style("calendar")
            self.set_cal_mode(mode)

        def _cal_menu_shift(self, step):
            if self.style != "calendar":
                self.set_style("calendar")
            self.cal_shift(step)

        def _cal_menu_daily(self):
            self.set_lane_mode(getattr(self, "lane_prev", "shrink") if self.v_daily.get() else "fold")

        def _fill_node_menu(self, menu, edit_items=True):
            """タスク（ノード）のメニュー。右クリックとメニューバー「タスク」で共通。
              タスクの設定… ／ ★ タスクリスト ／ ✓ 完了 ／ タスク設定 ▸ ｜（追加・名前）｜ 整理 ▸ ／ 展開・折りたたみ ▸ ／ つながり ▸ ｜ 削除"""
            menu.add_command(label="カレンダーで表示", accelerator=f"{ACC}+J", command=self.jump_view)
            menu.add_separator()
            menu.add_command(label="タスクリストに送る", accelerator="F", command=lambda: self.toggle_focus(force=True))
            menu.add_command(label="タスクを外す", accelerator=f"{ACC}+Delete", command=lambda: self.untask(self.sel))
            menu.add_checkbutton(label="✓ 完了", accelerator="Space", variable=self.v_m_done,
                                 command=lambda: (self.toggle_done(), self._sync_menu_vars()))
            menu.add_command(label="📝 メモ…", accelerator=f"{ACC}+M", command=lambda: self.memo_dialog())
            menu.add_command(label="指標（重要度・必要度・緊急度）…", accelerator="I", command=lambda: self.index_dialog())
            self.v_m_notable = getattr(self, "v_m_notable", None) or tk.BooleanVar(value=False)
            menu.add_checkbutton(label="☆ 注目ノード", accelerator="N", variable=self.v_m_notable,
                                 command=lambda: self.toggle_notable())
            menu.add_separator()
            if edit_items:
                menu.add_command(label="サブタスクを追加", accelerator="Tab", command=self.add_child)
                menu.add_command(label="同じ階層に追加", accelerator="Enter", command=self.add_sibling)
                menu.add_command(label="名前を変更", accelerator="F2", command=self.rename)
                menu.add_separator()
            og = tk.Menu(menu, tearoff=0)
            st = tk.Menu(og, tearoff=0)
            for k, lbl in STATUSES.items():
                st.add_command(label=lbl, command=lambda k=k: self.update_node(status=k))
            st.add_separator()
            st.add_command(label="次の状態へ進める", accelerator="Shift+Space", command=self.cycle_status)
            og.add_cascade(label="状態", menu=st)
            ct = tk.Menu(og, tearoff=0)
            ct.configure(postcommand=lambda m=ct: self._fill_category_menu(m))
            og.add_cascade(label="カテゴリ（置き場所）", menu=ct)
            kd = tk.Menu(og, tearoff=0)
            for (k, lbl), key in zip(KINDS.items(), "GTME"):
                kd.add_command(label=lbl, accelerator=key, command=lambda k=k: self.update_node(kind=k))
            og.add_cascade(label="種類", menu=kd)
            cm_ = tk.Menu(og, tearoff=0)
            cm_.add_command(label="パレットを開く…", accelerator="K", command=lambda: self.color_palette())
            cm_.add_separator()
            for name, col in NODE_COLORS:
                cm_.add_command(label=f"■ {name}（下位も）", foreground=col, activeforeground=col,
                                command=lambda col=col: self.set_color(col))
            cm_.add_separator()
            cm_.add_command(label="色を解除（下位も）", command=lambda: self.set_color(None))
            og.add_cascade(label="色", menu=cm_)
            menu.add_cascade(label="整理（状態・カテゴリ・種類・色）", menu=og)
            tm = tk.Menu(menu, tearoff=0)
            self._fill_tree_menu(tm, node=True)
            menu.add_cascade(label="展開・折りたたみ", menu=tm)
            lk = tk.Menu(menu, tearoff=0)
            lk.add_command(label="関連リンクを引く…", accelerator="L", command=lambda: self.set_mode("link"))
            lk.add_command(label="親を付け替える…", accelerator="P", command=lambda: self.set_mode("parent"))
            menu.add_cascade(label="つながり（リンク・親）", menu=lk)
            sm = tk.Menu(menu, tearoff=0)   # マップの分割・統合
            sm.add_command(label="このツリーを分割（別ファイル・別のマップへ）…", command=lambda: self.split_tree())
            sm.add_command(label="☆ 分割先／元のマップを開く", command=lambda: self.open_file_link())
            sm.add_command(label="分割したツリーを元に戻す（再統合）…", command=lambda: self.merge_split())
            menu.add_cascade(label="分割・統合", menu=sm)
            if edit_items:
                menu.add_separator()
                menu.add_command(label="削除", accelerator="Delete", command=self.delete)

            def upd(m=menu):   # 開くたびに今の状態（★・完了）を表示し、選んでいなければ灰色に
                self._sync_menu_vars()
                on = bool(self.sel and self.sel in self.mm.nodes)
                for k_ in range(m.index("end") + 1):
                    if m.type(k_) not in ("separator", "tearoff"):
                        m.entryconfigure(k_, state="normal" if on else "disabled")
            menu.configure(postcommand=upd)

        def _sync_menu_vars(self):
            n = self.mm.nodes.get(self.sel) if self.sel else None
            self.v_m_star.set(bool(n and n.get("focus")))
            self.v_m_done.set(bool(n and self.is_done(n)))
            self.v_m_rem.set(bool(n and n.get("remind")))
            self.v_m_reuse.set(bool(n and n.get("reusable")))
            self.v_m_freq.set((self._freq_of(n) or "") if n and n.get("kind") in ("task", "event") else "")
            if getattr(self, "v_m_notable", None) is not None:
                self.v_m_notable.set(bool(n and n.get("notable")))

        def show_in_mindmap(self, nid=None):
            """マインドマップに切り替える。前回の表示（拡大率・位置・展開）はそのままにし、
            そのタスクが隠れているときだけ上位を開き、画面の外にあるときだけ見える位置まで動かす"""
            nid = nid or self.sel
            if not nid or nid not in self.mm.nodes:
                return
            self.cancel_edit()
            if self.style != "mindmap":
                self.set_style("mindmap")   # 前回のマインドマップの拡大率・位置に戻る
            if nid in set(self.inbox_items()) or any(self.mm.nodes[a].get("calendar_root") for a in self._ancestors(nid)):
                self.sel = nid   # 未分類のタスク：右上の枠の中で選ぶ
                self.redraw()
                self.set_status(f"「{self.mm.nodes[nid].get('label', '')}」は右上の「未分類のタスク」にあります"
                                "（ドラッグしてツリーへ分類できます）")
                return
            opened = [a for a in self._ancestors(nid) if is_folded(self.mm.nodes[a]) or self.mm.nodes[a].get("hide_done_kids")]
            hidden_now = nid in self.mm.hidden_nodes()
            if hidden_now:   # 隠れているときだけ上位を開く
                self.checkpoint()
                for a in opened:
                    self.mm.nodes[a].pop("collapsed", None)
                    self.mm.nodes[a].pop("hide_done_kids", None)
                    self.mm.nodes[a].pop("done_hidden", None)
                self.touch()
                if not self.v_auto.get():
                    self.do_layout()
            self.sel = nid
            self.select(nid)
            n = self.mm.nodes[nid]
            c = self.canvas
            c.update_idletasks()
            X, Y = self.sx(_to_float(n.get("x"))), self.sy(_to_float(n.get("y")))
            W, H, m = c.winfo_width(), c.winfo_height(), 60
            if not (m <= X <= W - m and m <= Y <= H - m):   # 画面の外にあるときだけ中央へ
                self.ox += W / 2 - X
                self.oy += H / 2 - Y
            self.redraw()
            path = " › ".join(self.mm.nodes[a].get("label", "") for a in reversed(self._ancestors(nid)))
            self.set_status(f"マインドマップで表示: {path + ' › ' if path else ''}{n.get('label', '')}")

        def only_this_tree(self, nid=None):
            """選んだタスクのツリーだけを表示：上位の道筋と自分の下位はすべて開き、ほかの枝は折りたたむ"""
            nid = nid or self.sel
            if not nid or nid not in self.mm.nodes:
                return
            self.cancel_edit()
            self.checkpoint()
            anc = self._ancestors(nid)
            openset = set(anc) | {nid} | self.mm.descendants(nid)
            cm = self.mm.child_map()
            for k, n in self.mm.nodes.items():
                if k in openset:
                    n.pop("collapsed", None)
                    n.pop("hide_done_kids", None)
                    if k in anc or k == nid:
                        n.pop("done_hidden", None)
                elif cm[k]:
                    n["collapsed"] = True
            if self.style in TABLE_STYLES:
                self.set_style("mindmap")
            self.touch()
            if not self.v_auto.get():
                self.do_layout()
            self.select(nid)
            self.fit_view()
            path = " › ".join(self.mm.nodes[a].get("label", "") for a in reversed(anc))
            self.set_status(f"このツリーだけを表示: {path + ' › ' if path else ''}"
                            f"{self.mm.nodes[nid].get('label', '')}（「全」ですべて表示）")

        def fold_all_trees(self):
            """すべてのツリーを折りたたむ：子を持つノードを全部閉じる（最上位だけが見え、
            そこから子を開いても孫は閉じたまま）"""
            self.commit_edit()
            cm = self.mm.child_map()
            depth = self._tree_info()[0]
            self.checkpoint()
            for nid, n in self.mm.nodes.items():
                n.pop("hide_done_kids", None)
                if cm[nid] and depth.get(nid, 0) >= 1:   # いちばん上（最上位の目標）は開いたまま、その下はすべて閉じる
                    if "fold_saved" not in n:   # 折りたたむ前の開き具合を覚えておく（展開ボタンでその状態に戻す）
                        n["fold_saved"] = bool(n.get("collapsed"))
                    n["collapsed"] = True
                    n.pop("done_hidden", None)
                else:
                    n.pop("collapsed", None)
            self.touch()
            self.select(self.sel if self.sel in self.mm.nodes and self.sel not in self.mm.hidden_nodes() else None)
            self.fit_view()
            self.set_status("最上位とその直下だけを表示しました（展開ボタンで、折りたたむ前の開き具合に戻ります）")

        def expand_subtree(self, nid=None):
            """選んだノードの子・孫…をすべて展開"""
            nid = nid or self.sel
            if not nid or nid not in self.mm.nodes:
                return
            self.checkpoint()
            for k in {nid} | self.mm.descendants(nid):
                n = self.mm.nodes[k]
                for f in ("collapsed", "done_hidden", "hide_done_kids", "fold_saved"):
                    n.pop(f, None)
            self.touch()
            self.select(nid)
            self.set_status(f"「{self.mm.nodes[nid].get('label', '')}」の下位をすべて展開しました")

        # ---- 絞り込み（未完了・優先度）：条件に合うタスクとその上位だけを表示 ----
        def set_filter(self, undone=None, pri=None, toggle_pri=None, clear=False):
            self.commit_edit()
            f = self.mm.get_filter()
            f.pop("keep", None)
            if clear:
                f = {"undone": False, "pri": []}
            if undone is not None:
                f["undone"] = undone
            if pri is not None:
                f["pri"] = list(pri)
            if toggle_pri:
                f["pri"] = sorted(set(f["pri"]) ^ {toggle_pri})
            self.checkpoint()
            if f["undone"] or f["pri"]:
                self.mm.view["filter"] = f
                vis = self.mm.filter_visible()
                for k in vis:   # 条件に合うツリーは開いて見えるように
                    n = self.mm.nodes[k]
                    if any(c in vis for c in self.mm.children(k)):
                        for fl in ("collapsed", "done_hidden", "hide_done_kids"):
                            n.pop(fl, None)
            else:
                self.mm.view.pop("filter", None)
            self.touch()
            self.select(self.sel if self.sel in self.mm.nodes and self.sel not in self.mm.hidden_nodes() else None)
            self.refresh_filter_ui()
            if self.style not in TABLE_STYLES:
                self.fit_view()
            else:
                self.redraw()
            self.set_status(self.filter_text() or "絞り込みを解除しました")

        def filter_text(self):
            f = self.mm.get_filter()
            parts = (["未完了"] if f["undone"] else []) + ([f"重要度 {'・'.join(f['pri'])}位"] if f["pri"] else [])
            if not parts:
                return ""
            n = sum(1 for k in self.mm.filter_visible() if self.mm.node_matches(self.mm.nodes[k]))
            return f"絞り込み中：{' かつ '.join(parts)} のタスク {n} 件（そのツリーだけ表示）"

        def refresh_filter_ui(self):
            if not hasattr(self, "v_flt"):
                return
            f = self.mm.get_filter()
            self.v_flt["undone"].set(f["undone"])
            for k in ("1", "2", "3"):
                self.v_flt[k].set(k in f["pri"])

        # ---- 非表示（非表示リスト） ----
        def hide_node(self, nid=None):
            nid = nid or self.sel
            n = self.mm.nodes.get(nid) if nid else None
            if not n:
                return
            self.checkpoint()
            n["hidden"] = True
            n["hidden_at"] = now()
            self.touch()
            self.select(self.mm.parent(nid))
            self.set_status(f"「{n.get('label', '')}」を非表示にしました（表示 → 非表示リスト… で戻せます）")

        def hidden_list_dialog(self):
            """非表示リスト：個別・範囲（Shift／Ctrl で複数選択）・一括で 表示に戻す／削除"""
            old = getattr(self, "hidden_win", None)
            if old is not None and old.winfo_exists():
                old.lift()
                old.refresh()
                return
            w = self.hidden_win = tk.Toplevel(self.root)
            w.title("非表示リスト")
            w.transient(self.root)
            w.geometry("520x420")
            f = ttk.Frame(w, padding=10)
            f.pack(fill="both", expand=True)
            ttk.Label(f, text="非表示にしたタスク（Shift／Ctrl＋クリックで範囲・複数選択）",
                      foreground="#495057").pack(anchor="w")
            t = ttk.Treeview(f, columns=("lab", "path", "when"), show="headings", selectmode="extended", height=12)
            for col, txt, wd, st in (("lab", "タスク", 160, True), ("path", "場所（上位）", 200, True),
                                     ("when", "非表示にした日", 90, False)):
                t.heading(col, text=txt)
                t.column(col, width=wd, stretch=st)
            sb = ttk.Scrollbar(f, orient="vertical", command=t.yview)
            t.configure(yscrollcommand=sb.set)
            bf = ttk.Frame(f)
            bf.pack(side="bottom", fill="x", pady=(8, 0))
            sb.pack(side="right", fill="y", pady=(6, 0))
            t.pack(fill="both", expand=True, pady=(6, 0))

            def refresh():
                t.delete(*t.get_children())
                for nid, n in sorted(((k, v) for k, v in self.mm.nodes.items() if v.get("hidden")),
                                     key=lambda kv: kv[1].get("hidden_at", ""), reverse=True):
                    path = " › ".join(self.mm.nodes[a].get("label", "") for a in reversed(self._ancestors(nid)))
                    t.insert("", "end", iid=nid, values=(n.get("label", ""), path or "（最上位）",
                                                         (n.get("hidden_at") or "")[:10]))

            def targets(all_=False):
                return list(t.get_children()) if all_ else list(t.selection())

            def show(all_=False):
                ids = targets(all_)
                if not ids:
                    return
                self.checkpoint()
                for k in ids:
                    self.mm.nodes[k].pop("hidden", None)
                    self.mm.nodes[k].pop("hidden_at", None)
                self.touch()
                self.select(ids[0])
                refresh()
                self.set_status(f"{len(ids)} 件を表示に戻しました")

            def delete(all_=False):
                ids = targets(all_)
                if not ids:
                    return
                k = sum(1 + len(self.mm.descendants(i)) for i in ids if i in self.mm.nodes)
                if not messagebox.askyesno(APP_NAME, f"{len(ids)} 件（下位を含め {k} 件）をマップから削除します。"
                                                     f"\n（{ACC}+Z で元に戻せます）", parent=w):
                    return
                self.checkpoint()
                for i in ids:
                    if i in self.mm.nodes:
                        self.mm.remove_node(i)
                self.touch()
                self.select(None)
                refresh()
                self.set_status(f"非表示リストから {len(ids)} 件を削除しました")
            for txt, cmd in (("表示に戻す", show), ("すべて表示", lambda: show(True)),
                             ("削除", delete), ("すべて削除", lambda: delete(True))):
                ttk.Button(bf, text=txt, command=cmd).pack(side="left", padx=(0, 6))
            ttk.Button(bf, text="閉じる", command=w.destroy).pack(side="right")
            t.bind("<Delete>", lambda ev: delete())
            w.refresh = refresh
            refresh()

        def untask(self, nid=None, snapshot=True):
            """タスク設定を解除：タスクリストから外し、カレンダーの予定・繰り返し・アラームも外す。
            マップ（★）・タスクリスト・カレンダーのどこで外しても、この1か所で同じ状態にそろえる"""
            nid = nid or self.sel
            n = self.mm.nodes.get(nid) if nid else None
            if not n:
                return
            if not (n.get("focus") or has_sched(n) or n.get("repeat") or n.get("alarm") or n.get("sessions")
                    or n.get("remind") or self._calendar_only(nid)):
                self.set_status("このノードはタスク設定されていません")
                return
            self.cancel_edit()
            if snapshot:
                self.checkpoint()
            if self._calendar_only(nid) and not n.get("lecture_key") and not n.get("shift_code"):
                lab = n.get("label", "")   # カレンダーだけにあるタスク → 消去
                self.mm.remove_node(nid)
                self.sel = None
                self.touch()
                self.redraw()
                self.set_status(f"「{lab}」はカレンダーだけにあったので消去しました（{ACC}+Z で元に戻せます）")
                return
            n.pop("focus", None)
            clear_sched(n)
            for k in ("repeat", "exdates", "done_dates", "alarm", "snoozes", "iter", "remind", "sessions",
                      "multi", "day_target", "day_counts", "reusable", "trial"):
                n.pop(k, None)
            n["updated"] = now()
            self.touch()
            self.select(nid)
            self.set_status(f"「{n.get('label', '')}」のタスク設定を解除しました（マップの★・タスクリスト・カレンダーから外しました／"
                            f"{ACC}+Z で元に戻せます）")

        def _calendar_only(self, nid):
            """マップのツリーに入っていない（カレンダーの未分類・Adhocのまとめの直下）タスクか"""
            p_ = self.mm.parent(nid)
            v = self.mm.nodes.get(p_, {}) if p_ else {}
            return bool(v.get("calendar_root") or v.get("adhoc_root"))

        def show_in_calendar(self, nid=None):
            """カレンダー（週表示）に切り替え、そのタスクの日（繰り返しは今日以降の直近の回）を表示して選ぶ"""
            nid = nid or self.sel
            n = self.mm.nodes.get(nid) if nid else None
            if not n or not has_sched(n):
                return
            today = datetime.date.today()
            occ = occurrences(n, today, today + datetime.timedelta(days=400))
            d = occ[0] if occ else (_date(n.get("sched_date")) or today)
            sc = sched_of(n)
            if sc:   # 0〜5時の予定は前日の列に出る
                d = self._to_grid(d, sc[1], sc[2])[0]
            self.cancel_edit()
            self.set_style("calendar")
            self.cal_date = d
            self.cal_sel_date = d
            self.select(nid)
            self.fit_view()
            self.set_status(f"カレンダーで表示：{d.month}/{d.day}「{n.get('label', '')}」（ダブルクリックで設定画面・Ctrl+J でマインドマップへ）")

        # ---- マウスの追加ボタン（ケンジントン SlimBlade の右上＝カレンダー、左上＝マインドマップ） ----
        def _mouse_defaults(self):
            if sys.platform.startswith("win"):
                return {"cal": 4, "map": 2}   # Windows：戻るボタン＝4、中ボタン＝2
            return {"cal": 8, "map": 2}

        def on_any_button(self, ev):
            """どの画面でも：割り当てたボタンでカレンダー（週）／マインドマップへ。タスクを選んでいればそのタスクの場所へ"""
            mb = getattr(self, "mouse_btn", None) or self._mouse_defaults()
            num = getattr(ev, "num", None)
            if num in (1, 3) or getattr(self, "_learning_btn", None):
                return None
            if num == mb.get("cal"):
                self.root.after(1, self.go_calendar)
                return "break"
            if num == mb.get("map"):
                self.root.after(1, self.go_mindmap)
                return "break"
            return None

        # ---- データの保存先：Googleドライブの中のフォルダ（どのPCからも同じファイル） ----
        def _dd_initial(self):
            dd = getattr(self, "data_dir", None)
            return {"initialdir": dd} if dd and os.path.isdir(dd) else {}

        def in_data_dir(self, path):
            dd = getattr(self, "data_dir", None)
            if not dd or not path:
                return False
            try:
                return os.path.normcase(os.path.dirname(os.path.abspath(path))) == os.path.normcase(os.path.abspath(dd))
            except (OSError, ValueError):
                return False

        def _check_data_dir(self):
            """起動時：データの保存フォルダが未設定なら、見つかった Googleドライブに作るか確認。
            設定済みで今のファイルがその外にあれば、移すか確認（「いいえ」のファイルは次から聞かない）"""
            try:
                dd = getattr(self, "data_dir", None)
                if not dd:
                    if find_gdrive_roots():
                        self.setup_data_dir()
                    else:
                        self.set_status("データの保存先は［ファイル］→［データの保存フォルダ（Googleドライブ）…］で"
                                        "Googleドライブのフォルダにすると、どのPCからも同じデータを使えます")
                    return
                if os.path.basename(os.path.normpath(dd)) == OLD_DATA_SUBDIR:   # 旧名（TaskMap）のフォルダ
                    self._migrate_data_dir(dd)
                    return
                if not os.path.isdir(dd):
                    self.set_status(f"⚠ データの保存フォルダが見つかりません：{dd}（Googleドライブが起動しているか確認してください）")
                    return
                if self.path and not self.in_data_dir(self.path) and \
                        os.path.abspath(self.path) not in getattr(self, "dd_declined", []):
                    self.move_to_data_dir(ask=True)
            except Exception as err:
                self.set_status(f"⚠ データの保存フォルダを確認できませんでした：{err}")

        def _migrate_data_dir(self, old):
            """旧名（TaskMap）のデータフォルダから、同じ場所の Mind_Navi フォルダへ移る。ファイルはコピーし、元のフォルダは残す。
            Mind_Navi に同じ名前のファイルがあれば（ほかのPCで先に移したもの）、どちらを使うか確認する"""
            new = os.path.join(os.path.dirname(os.path.normpath(old)), DATA_SUBDIR)
            messagebox.showinfo(
                f"{APP_NAME} - データの保存先",
                "ソフトの名前が Mind_Navi（旧称 TaskMap）に変わったため、データの保存フォルダを移します。\n\n"
                f"移す前：{old}\n移した後：{new}\n\n"
                "ファイルはコピーし、元の TaskMap フォルダはそのまま残します（すべてのPCで移し終えたら削除できます）。\n"
                "スマホの買い物リストでは、新しいフォルダのデータファイルを選び直してください。", parent=self.root)
            try:
                os.makedirs(new, exist_ok=True)
            except OSError as err:
                messagebox.showerror(APP_NAME, f"フォルダを作れませんでした：\n{err}", parent=self.root)
                return False
            self.data_dir = os.path.abspath(new)
            self.save_settings()
            self.move_to_data_dir(ask=False, all_slots=True)
            self.update_title()
            self.set_status(f"データの保存フォルダ：{self.data_dir}")
            return True

        def setup_data_dir(self, force=False):
            """データの保存フォルダを決める：Googleドライブ（マイドライブ）の中の「Mind_Navi」フォルダ"""
            roots = find_gdrive_roots()
            cur = getattr(self, "data_dir", None)
            target = None
            if roots and not force:
                ans = messagebox.askyesnocancel(
                    f"{APP_NAME} - データの保存先",
                    "データファイルを Googleドライブのフォルダに保存すると、どのPC・スマホからも同じデータを使えます。\n\n"
                    f"保存先：{os.path.join(roots[0], DATA_SUBDIR)}\n\n"
                    "はい　　：このフォルダに保存する（今のファイルもここへ移します）\n"
                    "いいえ　：別のフォルダを選ぶ\n"
                    "キャンセル：あとで（［ファイル］メニューからいつでも設定できます）", parent=self.root)
                if ans is None:
                    return False
                if ans:
                    target = os.path.join(roots[0], DATA_SUBDIR)
            if target is None:
                init = cur or (roots[0] if roots else os.path.expanduser("~"))
                p = filedialog.askdirectory(parent=self.root, initialdir=init, mustexist=True,
                                            title="データの保存フォルダ（Googleドライブの中）を選ぶ")
                if not p:
                    return False
                target = p if os.path.basename(os.path.normpath(p)) == DATA_SUBDIR else os.path.join(p, DATA_SUBDIR)
            try:
                os.makedirs(target, exist_ok=True)
            except OSError as err:
                messagebox.showerror(APP_NAME, f"フォルダを作れませんでした：\n{err}", parent=self.root)
                return False
            self.data_dir = os.path.abspath(target)
            self.save_settings()
            self.move_to_data_dir(ask=False, all_slots=True)
            self.update_title()
            self.set_status(f"データの保存フォルダ：{self.data_dir}")
            return True

        def move_to_data_dir(self, ask=True, all_slots=False):
            """ファイルをデータの保存フォルダへ移す（元のファイルは残す）。同じ名前のファイルがフォルダにあれば、
            そちら（ほかのPCで移したもの）を使うか確認"""
            dd = getattr(self, "data_dir", None)
            if not dd:
                return self.setup_data_dir(force=True)
            if not os.path.isdir(dd):
                messagebox.showwarning(APP_NAME, f"データの保存フォルダが見つかりません：\n{dd}", parent=self.root)
                return False
            if not self.path:
                return self.save_as()
            if ask and not self.in_data_dir(self.path):
                if not messagebox.askyesno(
                        f"{APP_NAME} - データの保存先",
                        f"「{os.path.basename(self.path)}」は Googleドライブのデータフォルダの外にあります。\n"
                        f"（{os.path.dirname(os.path.abspath(self.path))}）\n\n"
                        "ほかのPCから見られるよう、データフォルダへ移しますか？\n（元のファイルはそのまま残ります）",
                        parent=self.root):
                    self.dd_declined = list(set(getattr(self, "dd_declined", []) + [os.path.abspath(self.path)]))
                    self.save_settings()
                    return False
            moved = []
            for j, s_ in enumerate(self.slots):
                if not s_ or not s_.get("path") or self.in_data_dir(s_["path"]) or not s_["path"].lower().endswith(".json"):
                    continue
                if j != self.cur and not all_slots:
                    continue
                src = s_["path"]
                dst = os.path.join(dd, os.path.basename(src))
                if os.path.exists(dst):
                    use = messagebox.askyesnocancel(
                        f"{APP_NAME} - データの保存先",
                        f"データフォルダに同じ名前の「{os.path.basename(dst)}」があります"
                        f"（更新：{_mtime_text(os.path.getmtime(dst))}）。\n\n"
                        "はい　　：データフォルダのファイルを使う（ほかのPCで移したもの）\n"
                        "いいえ　：このPCのファイルを別の名前でデータフォルダにコピーする\n"
                        "キャンセル：移さない", parent=self.root)
                    if use is None:
                        continue
                    if not use:
                        stem, k = os.path.splitext(os.path.basename(src))[0], 2
                        while os.path.exists(os.path.join(dd, f"{stem}_{k}.json")):
                            k += 1
                        dst = os.path.join(dd, f"{stem}_{k}.json")
                        use = None
                else:
                    use = None
                try:
                    if use is None:   # このPCのファイル（今の内容）をコピー
                        if j == self.cur:
                            self.mm.view.update(style=self.style, auto_layout=self.v_auto.get())
                            self.mm.store_positions(self.style)
                            self._write_doc(dst, self.mm)
                        elif s_.get("doc"):
                            self._write_doc(dst, s_["doc"]["mm"])
                        else:
                            shutil.copy2(src, dst)
                            mp = mirror_path(dst)
                            if mp:
                                shutil.copy2(src, mp)
                except OSError as err:
                    messagebox.showerror(APP_NAME, f"コピーできませんでした：\n{err}", parent=self.root)
                    continue
                s_["path"] = dst
                if s_.get("doc"):
                    s_["doc"]["path"] = dst
                if j == self.cur:
                    if use:   # データフォルダの方を開き直す
                        self.path = None
                        self.open_path(dst)
                    else:
                        self.path = dst
                        self.dirty = False
                moved.append(os.path.basename(dst))
            self.save_settings()
            self.update_title()
            if moved:
                self.set_status("データフォルダへ移しました：" + "、".join(moved) +
                                "（スマホの買い物アプリは、アプリの「ファイル」でこのファイルを選び直してください）")
            return bool(moved)

        def _periodic_save(self):
            """30秒ごと：変更が残っていて、入力・ドラッグ中でなければファイルへ保存（操作の邪魔をしない）"""
            try:
                if self.dirty and self.path and not self._busy_editing() and not self._typing_now() \
                        and not getattr(self, "_as_job", None):
                    self._transition_save("定期")
            except Exception:
                pass
            finally:
                try:
                    self.root.after(30000, self._periodic_save)
                except tk.TclError:
                    pass

        # ---- 買い物リスト・購入分析から買い物タスクを作る ----
        def make_shopping_task(self, rows, parent=None):
            """rows: [(品名, 価格)]。Adhoc の買い物タスクを作り（品目・価格はメモに）、週のカレンダーで置き場所を選ぶ"""
            rows = [(str(nm).strip(), int(pr or 0)) for nm, pr in rows if str(nm).strip()]
            if not rows:
                messagebox.showinfo(APP_NAME, "買い物タスクにする品を選んでください（Ctrl＋クリックで複数選べます）",
                                    parent=parent or self.root)
                return None
            names = [nm for nm, _p in rows]
            label = "買い物：" + "、".join(names[:3]) + (f" ほか{len(names) - 3}品" if len(names) > 3 else "")
            total = sum(p_ for _n, p_ in rows)
            note = "\n".join(["【買い物リスト】"] + [f"・{nm}　¥{p_:,}" if p_ else f"・{nm}" for nm, p_ in rows] +
                             [f"合計 ¥{total:,}（{len(rows)}品）"])
            self.checkpoint()
            nid = self.mm.add_node(label, self._adhoc_root(), kind="task", focus=True, adhoc=True, note=note)
            self.touch()
            try:
                self.root.deiconify()
                self.root.lift()
                self.root.focus_force()
            except tk.TclError:
                pass
            self.set_style("calendar")
            if self.cal_mode != "week":
                self.set_cal_mode("week", getattr(self, "cal_date", None) or datetime.date.today())
            self.select(nid)
            self.refresh_focus_list()
            self.redraw()
            self.start_carry(nid)
            return nid

        def start_carry(self, nid):
            """タスクをマウスに付けて運ぶ：カレンダーをクリックした日時に置く（Esc で取りやめ＝未配置のまま）"""
            self._ldrag = {"iid": nid, "x": -99999, "y": -99999, "on": False, "nopop": True, "carry": True}
            if not getattr(self, "_carry_bound", False):
                self.root.bind_all("<Motion>", self._carry_motion, add="+")
                self.root.bind_all("<Escape>", self._carry_cancel, add="+")
                self._carry_bound = True
            lab = (self.mm.nodes[nid].get("label") or "")[:30]
            self.set_status(f"「{lab}」をカレンダーの置きたい日時でクリック（Esc で取りやめ：タスクリストに未配置で残ります）")

        def _carrying(self):
            d = getattr(self, "_ldrag", None)
            return bool(d and d.get("carry"))

        def _carry_motion(self, ev):
            if self._carrying() and hasattr(ev, "x_root"):
                self.on_focus_drag(ev)

        def _carry_cancel(self, ev=None):
            if not self._carrying():
                return None
            fw, self._drag_float = getattr(self, "_drag_float", None), None
            if fw is not None:
                fw.destroy()
            self._ldrag, self.ext_ghost = None, None
            self.redraw()
            self.set_status("置くのをやめました（タスクリストに未配置で残っています。ドラッグでも置けます）")
            return None

        def go_calendar(self):
            """カレンダー（週表示）へ。選んでいるタスクに日時があればその日へ"""
            try:
                self.root.deiconify()
                self.root.lift()
            except tk.TclError:
                pass
            n = self.mm.nodes.get(self.sel) if self.sel else None
            if n and has_sched(n):
                self.show_in_calendar(n["id"])
                if self.cal_mode != "week":
                    self.set_cal_mode("week", self.cal_date)
                return
            if n and n.get("sessions"):
                se = sorted(n["sessions"], key=lambda x: (x.get("date") or "", x.get("start") or ""))[-1]
                self.set_style("calendar")
                self.set_cal_mode("week", _date(se.get("date")) or datetime.date.today())
                self.select(n["id"])
                return
            self.set_style("calendar")
            if self.cal_mode != "week":
                self.set_cal_mode("week", getattr(self, "cal_date", None) or datetime.date.today())
            if n:
                self.set_status(f"「{n.get('label', '')}」はまだカレンダーに入っていません（週のカレンダーを表示）")

        def go_mindmap(self):
            """マインドマップへ。選んでいるタスクがあれば、そのノードを表示"""
            try:
                self.root.deiconify()
                self.root.lift()
            except tk.TclError:
                pass
            if self.sel and self.sel in self.mm.nodes:
                self.show_in_mindmap(self.sel)
            else:
                self.set_style("mindmap")

        def mouse_button_dialog(self):
            """マウスのボタンの割り当て：割り当てたいボタンを押して覚えさせる"""
            mb = dict(getattr(self, "mouse_btn", None) or self._mouse_defaults())
            w = tk.Toplevel(self.root)
            w.title("マウスのボタンの割り当て")
            w.transient(self.root)
            w.resizable(False, False)
            f = ttk.Frame(w, padding=14)
            f.pack()
            ttk.Label(f, text="ケンジントン SlimBlade などの追加ボタンで、画面を切り替えます。\n"
                              "［設定］を押してから、割り当てたいマウスのボタンをこの枠の中で押してください。",
                      justify="left").grid(row=0, column=0, columnspan=3, sticky="w")
            box = tk.Label(f, text="（ここでボタンを押す）", relief="groove", width=40, height=3)
            box.grid(row=1, column=0, columnspan=3, pady=8)
            v = {k: tk.StringVar(value=f"ボタン {mb[k]}") for k in ("cal", "map")}
            state = {"k": None}

            def learn(k):
                state["k"] = k
                self._learning_btn = True
                box.configure(text=("右上（カレンダー）" if k == "cal" else "左上（マインドマップ）") + "に使うボタンを押してください",
                              bg="#fff3bf")

            def got(ev):
                if not state["k"] or ev.num in (1, 3):
                    return "break"
                mb[state["k"]] = int(ev.num)
                v[state["k"]].set(f"ボタン {ev.num}")
                box.configure(text=f"ボタン {ev.num} を覚えました", bg="#d3f9d8")
                state["k"] = None
                self._learning_btn = False
                return "break"
            box.bind("<Button>", got)
            for i, (k, lbl) in enumerate((("cal", "右上：カレンダー（週）"), ("map", "左上：マインドマップ")), 2):
                ttk.Label(f, text=lbl).grid(row=i, column=0, sticky="w")
                ttk.Label(f, textvariable=v[k], width=10).grid(row=i, column=1, sticky="w")
                ttk.Button(f, text="設定", command=lambda k=k: learn(k)).grid(row=i, column=2, sticky="e", pady=2)

            def ok():
                self.mouse_btn = mb
                self._learning_btn = False
                self.save_settings()
                w.destroy()
                self.set_status(f"マウスのボタン：{mb['cal']}＝カレンダー、{mb['map']}＝マインドマップ")

            def cancel():
                self._learning_btn = False
                w.destroy()
            bf = ttk.Frame(f)
            bf.grid(row=5, column=0, columnspan=3, sticky="e", pady=(10, 0))
            ttk.Button(bf, text="キャンセル", command=cancel).pack(side="right")
            ttk.Button(bf, text="保存", command=ok).pack(side="right", padx=6)
            w.protocol("WM_DELETE_WINDOW", cancel)

        def toggle_remind_pin(self, nid=None):
            """重要期限を、タスクリストで「重要期限」をたたんでも常に表示する／やめる"""
            nid = nid or self.sel
            n = self.mm.nodes.get(nid) if nid else None
            if not n or not n.get("remind"):
                self.set_status("重要期限のタスクを選んでください")
                return
            self.checkpoint()
            if n["remind"].get("pin"):
                n["remind"].pop("pin", None)
            else:
                n["remind"]["pin"] = True
            self.touch()
            self.set_status(f"「{n.get('label', '')}」を" + ("たたんでも常に表示します" if n["remind"].get("pin") else
                                                           "ふつうの表示に戻しました"))

        def index_dialog(self, nid=None):
            """タスクの指標（重要度・必要度・緊急度、6段階）を入力。タスク分析マップに表示"""
            nid = nid or self.sel
            n = self.mm.nodes.get(nid) if nid else None
            if not n:
                self.set_status("先にタスクを選んでください")
                return
            w = tk.Toplevel(self.root)
            w.title(f"指標 - {(n.get('label') or '（無題）')[:24]}")
            w.transient(self.root)
            w.resizable(False, False)
            f = ttk.Frame(w, padding=12)
            f.pack()
            ttk.Label(f, text=n.get("label") or "（無題）", font=(self.fam_base, 11, "bold")).grid(row=0, column=0, columnspan=8,
                                                                                            sticky="w", pady=(0, 6))
            vs = {}
            hints = {"imp": "人生・目標にとっての価値", "need": "やらないと困る度合い", "urg": "締め切りの近さ（円の大きさ）"}
            for r, (k, lbl) in enumerate(TASK_INDEX, 1):
                ttk.Label(f, text=lbl, font=(self.fam_base, 10, "bold")).grid(row=r * 2 - 1, column=0, sticky="w", padx=(0, 8))
                v = tk.StringVar(value=str(n.get(k) or ""))
                vs[k] = v
                for c_, val in enumerate(["1", "2", "3", "4", "5", "6", ""], 1):
                    ttk.Radiobutton(f, text=val or "なし", value=val, variable=v).grid(row=r * 2 - 1, column=c_, padx=2)
                ttk.Label(f, text=hints[k] + "（1位＝最も高い 〜 6＝低い・1〜3が「高」）", foreground="#868e96").grid(
                    row=r * 2, column=1, columnspan=7, sticky="w", pady=(0, 6))

            def ok(ev=None):
                if nid in self.mm.nodes:
                    self.checkpoint()
                    nn = self.mm.nodes[nid]
                    for k, v in vs.items():
                        if v.get().isdigit():
                            nn[k] = int(v.get())
                        else:
                            nn.pop(k, None)
                    if nn.get("kind") not in ("task", "event"):
                        nn["kind"] = "task"
                    nn["updated"] = now()
                    self.touch()
                    self.redraw()
                    tw = getattr(self, "task_ana_win", None)
                    if tw is not None and tw.win.winfo_exists():
                        tw.refresh()
                    self.set_status(f"指標を保存しました：重要度・必要度・緊急度 ＝ {idx_text(nn)}")
                w.destroy()
            bf = ttk.Frame(f)
            bf.grid(row=8, column=0, columnspan=8, sticky="we", pady=(6, 0))
            ttk.Button(bf, text="タスク分析マップを開く", command=lambda: (ok(), self.open_task_ana())).pack(side="left")
            ttk.Button(bf, text="保存", default="active", command=ok).pack(side="right")
            ttk.Button(bf, text="キャンセル", command=w.destroy).pack(side="right", padx=6)
            w.bind("<Return>", ok)
            w.bind("<Escape>", lambda ev: w.destroy())
            w.update_idletasks()
            w.geometry(f"+{self.root.winfo_pointerx() - 60}+{self.root.winfo_pointery() - 20}")
            fit_on_screen(w)

        def toggle_notable(self, nid=None):
            """☆ 注目ノード：朝・夕方のお知らせに名前を出す（クリックでマップのノードへ）"""
            nid = nid or self.sel
            n = self.mm.nodes.get(nid) if nid else None
            if not n:
                self.set_status("先にノードを選んでください")
                return
            self.checkpoint()
            if n.get("notable"):
                n.pop("notable", None)
            else:
                n["notable"] = True
            n["updated"] = now()
            self.touch()
            self.redraw()
            if getattr(self, "v_m_notable", None) is not None:
                self.v_m_notable.set(bool(n.get("notable")))
            self.set_status(f"「{n.get('label', '')}」を注目ノードにしました（朝・夕方のお知らせに表示）"
                            if n.get("notable") else f"「{n.get('label', '')}」の注目を外しました")

        def memo_dialog(self, nid=None):
            """タスク・ノードにリンクしたメモ（大きな入力欄。閉じると保存）"""
            nid = nid or self.sel
            n = self.mm.nodes.get(nid) if nid else None
            if not n:
                self.set_status("先にタスクかノードを選んでください")
                return
            old = getattr(self, "_memo_wins", {}).get(nid)
            if old is not None and old.winfo_exists():
                old.lift()
                return
            w = tk.Toplevel(self.root)
            self._memo_wins = getattr(self, "_memo_wins", {})
            self._memo_wins[nid] = w
            w.title(f"メモ - {(n.get('label') or '（無題）')[:30]}")
            w.transient(self.root)
            f = ttk.Frame(w, padding=8)
            f.pack(fill="both", expand=True)
            ttk.Label(f, text=f"📝 {n.get('label') or '（無題）'}", font=(self.fam_base, 11, "bold")).pack(anchor="w")
            t = tk.Text(f, width=56, height=16, wrap="word", font=(self.fam_base, 11), undo=True,
                        padx=6, pady=6, relief="solid", borderwidth=1)
            t.pack(fill="both", expand=True, pady=(6, 0))
            t.insert("1.0", n.get("note") or "")
            t.edit_reset()
            bb = ttk.Frame(f)
            bb.pack(fill="x", pady=(6, 0))

            def save(close=True):
                if nid not in self.mm.nodes:
                    w.destroy()
                    return
                txt = t.get("1.0", "end-1c").rstrip()
                nn = self.mm.nodes[nid]
                if txt != (nn.get("note") or ""):
                    self.checkpoint()
                    nn["note"] = txt
                    nn["updated"] = now()
                    self.touch()
                    self.redraw()
                    self.set_status(f"「{nn.get('label', '')}」のメモを保存しました")
                if close:
                    w.destroy()

            def cancel():
                w.destroy()
            ttk.Label(bb, text=f"{ACC}+S で保存・閉じると自動保存", foreground="#868e96").pack(side="left")
            ttk.Button(bb, text="保存して閉じる", default="active", command=save).pack(side="right")
            ttk.Button(bb, text="キャンセル", command=cancel).pack(side="right", padx=(0, 6))
            w.protocol("WM_DELETE_WINDOW", save)
            w.bind(f"<{MOD}-s>", lambda ev: (save(), "break")[1])
            w.bind("<Escape>", lambda ev: save())
            w.update_idletasks()
            w.geometry(f"+{self.root.winfo_pointerx() - 40}+{self.root.winfo_pointery() - 20}")
            fit_on_screen(w)
            t.focus_set()
            t.mark_set("insert", "end")
            return w

        def toggle_task_star(self, nid=None):
            """★：タスクに設定（タスクリストに入れる）/ 解除。1回・毎日などはカレンダーで設定"""
            nid = nid or self.sel
            n = self.mm.nodes.get(nid) if nid else None
            if not n:
                return
            if n.get("focus"):   # 解除はカレンダーにも反映（タスクリスト・カレンダーからも外す）
                self.untask(nid)
                return
            self.checkpoint()
            n["focus"] = True
            if n.get("kind") != "event":
                n["kind"] = "task"
            msg = ("タスクに設定しました（カレンダーの予定とつながっています）" if has_sched(n) else
                   "タスクに設定しました。左の「タスクリスト」一覧からカレンダーへドラッグして日時を決めます")
            n["updated"] = now()
            self.touch()
            self.select(nid)
            self.set_status(msg)


        def _fill_cal_menu(self, m):
            """カレンダーの予定・タスクリストの右クリック（タスクメニューと同じ名前・同じ並び）"""
            self._sync_menu_vars()
            m.add_command(label="マインドマップで表示", accelerator=f"{ACC}+J", command=self.jump_view)
            m.add_separator()
            m.add_command(label="タスクの設定…", accelerator="W", command=lambda: self.show_qpop(force=True))
            m.add_checkbutton(label="✓ 完了", accelerator="Space", variable=self.v_m_done,
                              command=lambda: (self.toggle_done(), self._sync_menu_vars()))
            m.add_command(label="📝 メモ…", accelerator=f"{ACC}+M", command=lambda: self.memo_dialog())
            m.add_command(label="指標（重要度・必要度・緊急度）…", accelerator="I", command=lambda: self.index_dialog())
            if n_0 := (self.mm.nodes.get(self.sel) if self.sel else None):
                if n_0.get("remind"):
                    pin_ = bool(n_0["remind"].get("pin"))
                    m.add_command(label=("📌 重要期限：常に表示をやめる" if pin_ else "📌 重要期限：たたんでも常に表示"),
                                  accelerator=f"{ACC}+P", command=lambda: self.toggle_remind_pin())
            ts = tk.Menu(m, tearoff=0)
            self._fill_task_menu(ts)
            m.add_cascade(label="タスク設定（いつ・回数・通知）", menu=ts)
            n_ = self.mm.nodes.get(self.sel) if self.sel else None
            if n_ and self._day_target(n_) > 1:
                d_ = getattr(self, "cal_sel_date", None) or datetime.date.today()
                m.add_command(label=f"実施回数を1つ戻す（{d_.month}/{d_.day}：{self._count_text(n_, d_)}）",
                              command=lambda: self.count_step(n_["id"], d_, -1))
            m.add_separator()
            m.add_command(label="コピー（同じタスクを別の日時にも入れる）", accelerator=f"{ACC}+C", command=self.cal_copy)
            m.add_separator()
            sid_ = getattr(self, "cal_sel_sid", None)
            if sid_ and n_:   # 続きの時間枠
                m.add_command(label="この続きの時間枠を削除", accelerator="Del",
                              command=lambda: self.delete_session(n_["id"], sid_))
                m.add_separator()
            m.add_command(label="日時だけ外す（タスクリストには残す）", command=lambda: self.unschedule(keep_task=True))
            m.add_command(label="タスクを外す", accelerator=f"{ACC}+Delete", command=lambda: self.untask(self.sel))

        def _fill_map_task_menu(self, m):
            self._fill_task_menu(m)

        def _fill_task_menu(self, m):
            """タスク設定 ▸ 　［いつやるか］1回・毎日… ｜［回数・詳細］｜［通知］アラーム・重要期限。今の設定に印"""
            if not getattr(m, "_keep", False):
                m.delete(0, "end")
            self._sync_menu_vars()
            m.add_command(label="いつやるか", state="disabled")
            for freq, lbl in (("once_timed", "1回（時刻あり）"), ("once_day", "1回（時刻なし・デイリー）")):
                m.add_radiobutton(label=lbl, value=freq, variable=self.v_m_freq,
                                  command=lambda f=freq: self.set_task_freq(f))
            dm = tk.Menu(m, tearoff=0)
            for freq, lbl in (("daily", "毎日"), ("iter", "反復タスク（実施回数を数えて表示）"),
                              ("multi", "複数回数実施（1日に1〜5回・時刻なし）…")):
                dm.add_radiobutton(label=lbl, value=freq, variable=self.v_m_freq,
                                   command=lambda f=freq: self.set_task_freq(f))
            m.add_cascade(label=("● " if self.v_m_freq.get() in ("daily", "iter", "multi") else "　 ") + "毎日", menu=dm)
            for freq, lbl in (("weekdays", "平日（月〜金）"), ("weekly", "毎週"), ("monthly", "毎月")):
                m.add_radiobutton(label=lbl, value=freq, variable=self.v_m_freq,
                                  command=lambda f=freq: self.set_task_freq(f))
            m.add_separator()
            m.add_command(label="回数・詳細", state="disabled")
            m.add_command(label="1日の実施回数…（例：食事 3回）", command=lambda: self.day_target_dialog())
            m.add_command(label="日時・繰り返しの詳細…", accelerator="W", command=lambda: self.show_qpop(force=True))
            m.add_separator()
            m.add_command(label="通知", state="disabled")
            m.add_command(label="アラーム…", accelerator="A", command=lambda: self.alarm_dialog())
            m.add_checkbutton(label="重要期限（期限日の前から知らせる）", variable=self.v_m_rem,
                              command=self.toggle_remind)

        def toggle_remind(self, nid=None):
            """重要期限のオン／オフ（期限の日付はなし。オンにすると時刻なしのデイリー＋毎日お知らせ）"""
            nid = nid or self.sel
            n = self.mm.nodes.get(nid) if nid else None
            if not n:
                return
            self.checkpoint()
            if n.get("remind"):
                n.pop("remind", None)
                msg = "重要期限を外しました"
            else:
                n["remind"] = {"since": datetime.date.today().isoformat(), "mode": "before", "before": REMIND_DEFAULT}
                n["kind"] = "task"
                n["focus"] = True
                for k in ("sched_start", "sched_end", "alarm"):
                    n.pop(k, None)
                self._remind_checked = None
                self.root.after(500, self._check_reminders)
                msg = "重要期限にしました（期限日＝タスクの日付の1か月前から知らせます。時期はタスクの設定で変更）"
                if not (_date(n.get("sched_date")) or _date(n.get("due"))):
                    msg += "　※タスクの日付（期限日）を入れてください"
                    self.root.after(100, lambda: self.show_qpop(force=True))
            n["updated"] = now()
            self.touch()
            self.select(nid)
            self.set_status(msg)

        @staticmethod
        def _freq_of(n):
            """今のタスク設定：once_timed / once_day / daily / iter / weekdays / weekly / monthly / None"""
            if not n:
                return None
            cur = (n.get("repeat") or {}).get("freq", "")
            if cur == "daily" and n.get("iter"):
                return "iter"
            if cur == "daily" and n.get("multi"):
                return "multi"
            if cur == "":
                return "once_timed" if sched_of(n) else "once_day" if untimed(n) else None
            return cur

        def make_multi(self, n, times):
            """複数回数実施タスク：毎日・時刻なし（デイリー）で、1日に times 回（1〜5）チェックすると完了"""
            times = max(1, min(5, int(times)))
            was = n.get("multi") and (n.get("repeat") or {}).get("freq") == "daily"
            n["kind"] = "task"
            n["focus"] = True
            n["multi"] = True
            n["day_target"] = times
            n.pop("iter", None)
            n.pop("remind", None)
            if not was:
                n.pop("done_dates", None)
                n.pop("day_counts", None)
                n["repeat"] = {"freq": "daily", "interval": 1}
                n["sched_date"] = (_date(n.get("sched_date")) or datetime.date.today()).isoformat()
            n.pop("sched_start", None)
            n.pop("sched_end", None)
            n.pop("alarm", None)
            n["status"] = "todo"
            n["updated"] = now()

        def multi_task_dialog(self, nid=None):
            """1日の実施回数（1〜5回）を選んで複数回数実施タスクにする"""
            nid = nid or self.sel
            n = self.mm.nodes.get(nid) if nid else None
            if not n:
                return
            w = tk.Toplevel(self.root)
            w.title("複数回数実施タスク")
            w.transient(self.root)
            w.resizable(False, False)
            f = ttk.Frame(w, padding=14)
            f.pack(fill="both", expand=True)
            ttk.Label(f, text=f"「{n.get('label') or '（無題）'}」", font=(self.fam_base, 10, "bold")).pack(anchor="w")
            ttk.Label(f, text="毎日・時刻なしのデイリータスクにして、1日に何回か実施します。\n"
                              "チェックするたびに 1/3 → 2/3 → 3/3 と数え、設定回数で実施済みになります。",
                      foreground="#495057").pack(anchor="w", pady=(4, 8))
            rf = ttk.Frame(f)
            rf.pack(anchor="w")
            ttk.Label(rf, text="1日の実施回数").pack(side="left", padx=(0, 8))
            v = tk.IntVar(value=min(5, max(1, self._day_target(n) if n.get("day_target") else 3)))
            for k in range(1, 6):
                ttk.Radiobutton(rf, text=f"{k}回", value=k, variable=v).pack(side="left", padx=(0, 6))
            bf = ttk.Frame(f)
            bf.pack(fill="x", pady=(12, 0))

            def ok():
                self.checkpoint()
                self.make_multi(n, v.get())
                w.destroy()
                self.touch()
                self.select(n["id"])
                self.set_status(f"「{n.get('label', '')}」を複数回数実施タスク（毎日 {v.get()} 回・時刻なし）にしました。"
                                "カレンダーのデイリー欄でチェックするたびに回数が進みます")
            ttk.Button(bf, text="OK", default="active", command=ok).pack(side="right")
            ttk.Button(bf, text="キャンセル", command=w.destroy).pack(side="right", padx=6)
            w.bind("<Return>", lambda ev: ok())
            w.bind("<Escape>", lambda ev: w.destroy())
            w.update_idletasks()
            w.geometry(f"+{self.root.winfo_rootx() + 160}+{self.root.winfo_rooty() + 140}")
            w.grab_set()
            w.focus_force()

        def set_task_freq(self, freq):
            """選択ノードをタスクにして、1回（時間あり）／1回（デイリー・時間なし）／毎日／毎週／毎月を設定"""
            n = self.mm.nodes.get(self.sel) if self.sel else None
            if not n:
                return
            if freq == "multi":
                self.multi_task_dialog()
                self._sync_menu_vars()
                return
            if n.get("multi") and freq != "multi":   # 複数回数実施をやめる
                for k in ("multi", "day_target", "day_counts"):
                    n.pop(k, None)
            if freq in ("once_timed", "once_day"):
                self.checkpoint()
                n["kind"] = "task"
                n["focus"] = True   # タスクに設定＝タスクリスト
                for k in ("repeat", "exdates", "done_dates", "iter"):
                    n.pop(k, None)
                day = _date(n.get("sched_date")) or datetime.date.today()
                n["sched_date"] = day.isoformat()
                if freq == "once_day":   # 時間なし → カレンダーの最上段（終日欄）に表示
                    n.pop("sched_start", None)
                    n.pop("sched_end", None)
                    n.pop("alarm", None)
                    msg = (f"★タスクリストの {day.month}/{day.day} 1回きりのデイリータスク（時間指定なし）にしました。"
                           "カレンダーの最上段に表示されます")
                else:
                    if not sched_of(n):   # 仮の時刻（次の正時から1時間）を入れて、ダイアログで調整
                        nw = datetime.datetime.now()
                        a = min(22 * 60, (nw.hour + 1) * 60) if day == nw.date() else 9 * 60
                        n["sched_start"], n["sched_end"] = _fmt_hm(a), _fmt_hm(a + NEW_TASK_MIN)
                    msg = "★タスクリストの1回きりのタスク（時間指定あり）にしました。日付と時刻を指定してください"
                n["updated"] = now()
                self.touch()
                self.select(self.sel)
                self.set_status(msg)
                if freq == "once_timed":
                    self.show_qpop()
                return
            if freq:
                it = freq == "iter"   # 反復タスク＝毎日＋実施回数を数えて表示
                rf = "daily" if it else freq
                same = (n.get("repeat") or {}).get("freq") == rf
                if same and bool(n.get("iter")) == it and n.get("kind") == "task" and n.get("focus"):
                    return
                self.checkpoint()
                n["kind"] = "task"
                n["focus"] = True   # タスクに設定＝タスクリスト
                if it:
                    n["iter"] = True
                else:
                    n.pop("iter", None)
                if same:
                    n["updated"] = now()
                    self.touch()
                    self.select(self.sel)
                    if it:
                        self.set_status(f"反復タスクにしました（これまでの実施 {iter_count(n)} 回）。"
                                        "カレンダーで実施をチェックすると回数が増えます")
                    return
                self.set_routine(rf, cp=False)
                if it:
                    self.set_status("反復タスク（毎日）にしました。カレンダーに配置して、実施したらチェック → "
                                    "実施回数がタスクの上に表示されます")
                return
            if n.get("kind") == "task" and not n.get("repeat"):
                return
            self.checkpoint()
            n["kind"] = "task"
            for k in ("repeat", "exdates", "done_dates", "iter"):
                n.pop(k, None)
            if untimed(n):
                n.pop("sched_date", None)
            n["updated"] = now()
            self.touch()
            self.select(self.sel)
            self.set_status("1回きりのタスクにしました（日時は W キー、カレンダーへのドラッグでも設定できます）")

        def _fill_tree_menu(self, m, node=True, view=False):
            """展開・折りたたみ。node=True なら先頭に「このツリー」の操作、続いて全体の操作"""
            if node:
                m.add_command(label="下位を折りたたむ / 展開", accelerator="C", command=self.toggle_collapse)
                m.add_command(label="子・孫をすべて展開", command=lambda: self.expand_subtree())
                m.add_command(label="このツリーだけを表示（ほかは折りたたむ）", command=lambda: self.only_this_tree())
                m.add_command(label="このツリーを非表示（非表示リストへ）", command=lambda: self.hide_node())
                m.add_command(label="マインドマップで確認（上位をたどって展開）", command=lambda: self.show_in_mindmap())
                m.add_separator()
            m.add_command(label="すべて展開", accelerator="Shift+C", command=self.expand_all)
            m.add_command(label="すべてのツリーを折りたたむ（2段目まで表示）", command=self.fold_all_trees)
            sl = tk.Menu(m, tearoff=0)
            for k in (1, 2, 3):
                sl.add_command(label=f"{k} 段目まで", accelerator=f"{ALT}+Shift+{k}", command=lambda k=k: self.show_level(k))
            sl.add_command(label="すべて", accelerator=f"{ALT}+Shift+0", command=lambda: self.show_level(None))
            m.add_cascade(label="表示する段数", menu=sl)
            m.add_command(label="★ タスクリストのツリーだけ展開", accelerator=f"{ALT}+Shift+F", command=self.focus_tree_view)
            am = tk.Menu(m, tearoff=0)
            for i, (k, lbl, _d) in enumerate(self.ACTIVE_PERIODS):
                am.add_command(label=f"{lbl}（実施時間の多いツリー）", accelerator=f"{ALT}+Shift+{'DWMY'[i]}",
                               command=lambda k=k: self.active_tree_view(k))
            am.add_separator()
            am.add_command(label="強調を解除", command=self.clear_active_tree)
            m.add_cascade(label="アクティブツリー", menu=am)
            m.add_separator()
            dm = tk.Menu(m, tearoff=0)
            m.add_cascade(label="完了した枝", menu=dm)
            if view:
                om = tk.Menu(m, tearoff=0)
                om.add_radiobutton(label="前回終了時の展開状態で開く", value="last", variable=self.v_open_mode,
                                   command=self.save_settings)
                om.add_radiobutton(label="タスクリストのツリーだけ展開して開く", value="focus", variable=self.v_open_mode,
                                   command=self.save_settings)
                m.add_cascade(label="開いたときの展開", menu=om)

        def _fill_filter_menu(self, m):
            """絞り込み（条件に合うタスクとその上位だけ表示）と非表示リスト"""
            m.add_command(label="☐ 未完了タスクだけ（もう一度で解除）", command=self.undone_tree_view)
            for k in ("1", "2", "3"):
                m.add_command(label=f"重要度 {k}位 のタスクだけ", command=lambda k=k: self.set_filter(pri=[k]))
            m.add_separator()
            m.add_command(label="絞り込みを解除", command=lambda: self.set_filter(clear=True))
            m.add_separator()
            m.add_command(label="非表示リスト…（非表示にしたタスク）", command=self.hidden_list_dialog)

        def _build_context_menus(self):
            self.node_menu = tk.Menu(self.root, tearoff=0)
            self._fill_node_menu(self.node_menu)
            self.bg_menu = tk.Menu(self.root, tearoff=0)
            self.bg_menu.add_command(label="ここを拡大", accelerator="ダブルクリック",
                                     command=lambda: self.zoom_at(self._menu_world[0] * self.z + self.ox,
                                                                  self._menu_world[1] * self.z + self.oy))
            self.bg_menu.add_command(label="目標を追加（ここに）", accelerator=f"{ACC}+Enter",
                                     command=lambda: self.add_goal(*self._menu_world))
            self.bg_menu.add_separator()
            bt = tk.Menu(self.bg_menu, tearoff=0)
            self._fill_tree_menu(bt, node=False)
            self.bg_menu.add_cascade(label="展開・折りたたみ", menu=bt)
            bf = tk.Menu(self.bg_menu, tearoff=0)
            self._fill_filter_menu(bf)
            self.bg_menu.add_cascade(label="絞り込み・非表示", menu=bf)
            self.bg_menu.add_separator()
            self.bg_menu.add_command(label="整列", accelerator=f"{ACC}+L", command=self.relayout)
            self.bg_menu.add_command(label="全体を表示", accelerator=f"{ACC}+0", command=self.fit_view)
            self._menu_world = (None, None)

        def _build_focus_list(self, p):
            """左パネル「タスクリスト」タブ：達成率 / タスクリスト / 選択中のタスク / ヒント。
            各欄は見出しクリックで折りたたみ、入りきらないときはパネル全体を縦にスクロール"""
            # 各欄を上下に並べ、欄と欄の境界線（灰色の帯）をドラッグで高さを変えられるようにする
            sp = self.spane = tk.PanedWindow(p, orient="vertical", sashwidth=8, sashrelief="raised", bd=0,
                                             bg="#adb5bd", opaqueresize=True, sashcursor="sb_v_double_arrow")
            sp.pack(fill="both", expand=True)
            self._sec = {}   # key → (pane, header, 中身の外枠, 中身, scroll canvas or None)
            self.sec_h = dict(getattr(self, "sec_h", None) or {})
            bgc = ttk.Style().lookup("TFrame", "background") or "#f0f0f0"

            def wheel(ev):   # ホイール：一覧の上では一覧、ほかの欄ではその欄をスクロール
                w = str(ev.widget)
                if w.startswith(str(self.focus_tree)):
                    return
                for key, (pane, hd, box, inner, cv) in self._sec.items():
                    if cv is not None and w.startswith(str(pane)) and inner.winfo_reqheight() > cv.winfo_height():
                        step = -1 if (getattr(ev, "delta", 0) > 0 or getattr(ev, "num", 0) == 4) else 1
                        cv.yview_scroll(step * 2, "units")
                        return
            for seq in ("<MouseWheel>", "<Button-4>", "<Button-5>"):
                self.root.bind_all(seq, wheel, add="+")
            self._sec_hdr = {}

            def section(key, title, scroll=True, stretch="never", header=True):
                pane = tk.Frame(sp, bg=bgc)
                hd = tk.Frame(pane, bg="#e9ecef", cursor="hand2")
                if header:   # header=False の欄（コンパス）は中身に自分の見出しがある
                    hd.pack(side="top", fill="x")
                lab = tk.Label(hd, bg="#e9ecef", fg="#343a40", anchor="w", font=(self.fam_base, 10, "bold"),
                               padx=6, pady=3, cursor="hand2")
                lab.pack(side="left", fill="x", expand=True)
                box = tk.Frame(pane, bg=bgc)
                cv = None
                if scroll:   # 欄が中身より低いときは欄の中でスクロール
                    cv = tk.Canvas(box, highlightthickness=0, bd=0, bg=bgc)
                    vsb = ttk.Scrollbar(box, orient="vertical", command=cv.yview)
                    cv.configure(yscrollcommand=vsb.set)
                    cv.pack(side="left", fill="both", expand=True)
                    inner = ttk.Frame(cv, padding=(2, 4, 2, 2))
                    win = cv.create_window(0, 0, window=inner, anchor="nw")

                    def on_inner(ev=None, cv=cv, inner=inner, vsb=vsb):
                        cv.configure(scrollregion=(0, 0, inner.winfo_reqwidth(), inner.winfo_reqheight()))
                        need = inner.winfo_reqheight() > cv.winfo_height() + 1
                        if need and not vsb.winfo_ismapped():
                            vsb.pack(side="right", fill="y", before=cv)
                        elif not need and vsb.winfo_ismapped():
                            vsb.pack_forget()
                            cv.yview_moveto(0)
                        if ev is not None and ev.widget is inner and key not in self.sec_h:
                            self.root.after_idle(lambda: self._sec_fit(key))
                    inner.bind("<Configure>", on_inner)
                    cv.bind("<Configure>", lambda ev, cv=cv, win=win, f=on_inner: (cv.itemconfigure(win, width=ev.width),
                                                                                  f()))
                else:
                    inner = ttk.Frame(box, padding=(2, 4, 2, 2))
                    inner.pack(fill="both", expand=True)
                if not header:
                    inner.configure(padding=0)
                sp.add(pane, stretch=stretch, minsize=28)
                self._sec[key] = (pane, hd, box, inner, cv)

                def apply():
                    op = self.sec_open.get(key, True)
                    lab.configure(text=("▼ " if op else "▶ ") + lab._title)
                    if op:
                        box.pack(side="top", fill="both", expand=True)
                    else:
                        box.pack_forget()
                    self.root.after_idle(lambda: self._sec_fit(key))

                def toggle(ev=None):
                    self.sec_open[key] = not self.sec_open.get(key, True)
                    apply()
                    self.save_settings()
                lab._title = title
                for w_ in (hd, lab):
                    w_.bind("<Button-1>", toggle)
                self._sec_hdr[key] = (lab, apply)
                return inner
            sp.bind("<ButtonPress-1>", lambda ev: setattr(self, "_sec_drag", True), add="+")
            sp.bind("<ButtonRelease-1>", self._on_sec_sash, add="+")
            sp.bind("<Configure>", lambda ev: self.root.after_idle(self._sec_fit), add="+")
            sp.bind("<Double-Button-1>", self._sec_reset, add="+")

            # 0) ミッションステートメント（いちばん上。クリックで書き込み）
            mi = section("mission", "ミッションステートメント", scroll=False)
            self.mission_bar(mi).pack(fill="x")
            # 1) ウィークリーコンパス（ミッションのすぐ下。金色の帯の「たたむ」で開閉）
            cp = section("compass", "ウィークリーコンパス", header=False)
            self.compass = tk.Frame(cp, bg="#fff8e1", highlightthickness=0)
            self.compass.pack(fill="both", expand=True)
            # 2) 週間実績（コンパスの週の達成・トライアル・積み上げ）
            wk = section("weekly", "週間実績", scroll=True, stretch="always")
            self.rate_cv = None
            self.week_cv = tk.Canvas(wk, height=300, bg="#fbfcfe", highlightthickness=0, bd=0)
            self.week_cv.pack(fill="x", anchor="n")
            self.week_cv.bind("<Configure>", lambda ev: self._schedule_week_panel())
            # 3) タスクリスト（右のパネル）
            p = self.rpanel
            hdr_ = tk.Frame(p, bg="#e9ecef")
            hdr_.pack(fill="x")
            self.list_title = tk.Label(hdr_, text="タスクリスト", bg="#e9ecef", fg="#343a40", anchor="w",
                                       font=(self.fam_base, 11, "bold"), padx=6, pady=4)
            self.list_title.pack(side="left", fill="x", expand=True)
            ttk.Button(hdr_, text="📊 分析マップ", command=self.open_task_ana).pack(side="right", padx=2, pady=2)
            ttk.Button(hdr_, text="⇅ 並べ替える", command=self.resort_list).pack(side="right", padx=2, pady=2)
            sf_ = ttk.Frame(p)   # タスク名で検索（いちばん上）
            sf_.pack(fill="x", pady=(4, 0))
            ttk.Label(sf_, text="🔍").pack(side="left")
            self.v_search = tk.StringVar()
            self.v_newtask = tk.StringVar()   # （以前の入力欄。今はリストに直接入力）
            se_ = ttk.Entry(sf_, textvariable=self.v_search, font=(self.fam_base, 10))
            se_.pack(side="left", fill="x", expand=True, padx=(2, 0))
            ttk.Button(sf_, text="×", width=-2, command=lambda: self.v_search.set("")).pack(side="left", padx=(2, 0))
            self._search_job = None

            def on_search(*_):   # 入力が止まったら絞り込み（打つたびには作り直さない）
                if self._search_job:
                    self.root.after_cancel(self._search_job)
                self._search_job = self.root.after(180, lambda: (setattr(self, "_search_job", None),
                                                                 self.refresh_focus_list()))
            self.v_search.trace_add("write", on_search)
            se_.bind("<Escape>", lambda ev: self.v_search.set(""))
            ttk.Label(p, text="行をカレンダーへドラッグで日時を設定／いちばん下の行に直接入力して追加",
                      foreground="#868e96", justify="left").pack(anchor="w")
            ff = ttk.Frame(p)
            ff.pack(fill="x", pady=(4, 0))
            ttk.Label(ff, text="カテゴリ:").pack(side="left")
            self.v_cat_filter = tk.StringVar(value="すべて")
            self.cb_filter = ttk.Combobox(ff, textvariable=self.v_cat_filter, state="readonly", width=12)
            self.cb_filter.pack(side="left", padx=4)
            self.cb_filter.bind("<<ComboboxSelected>>", lambda ev: self.refresh_focus_list())
            ttk.Button(ff, text="編集…", width=-4, command=self.edit_map_categories).pack(side="right")
            st = ttk.Style()
            st.configure("Focus.Treeview", rowheight=26, font=(self.fam_base, 10))
            st.configure("Focus.Treeview.Heading", font=(self.fam_base, 9))
            fr = ttk.Frame(p)
            fr.pack(fill="both", expand=True, pady=(4, 4))
            t = self.focus_tree = ttk.Treeview(fr, columns=LIST_COLS,
                                               show="headings",
                                               style="Focus.Treeview", selectmode="browse", height=3)
            for col, txt, w, anc, stretch in (("quad", "分類", 58, "center", False), ("due", "日時", 82, "center", False),
                                              ("chk", "", 24, "center", False), ("label", "タスク", 96, "w", True),
                                              ("memo", "📝", 26, "center", False),
                                              ("cat", "カテゴリ▾", 64, "center", False),
                                              ("imp", "重", 26, "center", False),
                                              ("need", "必", 26, "center", False),
                                              ("urg", "緊", 26, "center", False)):
                t.heading(col, text=txt)
                t.column(col, width=w, anchor=anc, stretch=stretch)
                if col in LIST_SORTS:   # 見出しのクリックで並べ替え（もう一度で逆順、3回目で解除）
                    t.heading(col, command=lambda col=col: self.sort_list(col))
            t.tag_configure("done", foreground="#adb5bd")
            t.tag_configure("overdue", foreground="#c92a2a")
            sb = ttk.Scrollbar(fr, orient="vertical", command=t.yview)
            t.configure(yscrollcommand=sb.set)
            t.pack(side="left", fill="both", expand=True)
            sb.pack(side="right", fill="y")
            # 重要期限の「常に表示（📌）」：一覧をスクロールしても常に上に出す別の欄
            pf_ = self.pin_frame = ttk.Frame(p)
            pt_ = self.pin_tree = ttk.Treeview(pf_, columns=LIST_COLS, show="", style="Focus.Treeview",
                                               selectmode="browse", height=1)
            for col in LIST_COLS:
                pt_.column(col, width=t.column(col, "width"), anchor=t.column(col, "anchor"),
                           stretch=t.column(col, "stretch"))
            pt_.tag_configure("pinrow", background="#fff5f5", foreground="#c92a2a")
            pt_.pack(side="left", fill="x", expand=True)
            tk.Frame(pf_, width=sb.winfo_reqwidth(), height=1).pack(side="right")
            self._pin_fr_ref = fr

            def pin_click(ev):
                iid = pt_.identify_row(ev.y)
                if iid in self.mm.nodes:
                    self.select(iid)
                    if pt_.identify_column(ev.x) == LCOL["chk"]:   # □ 列 → 完了
                        self.toggle_done()
                        return "break"
                    self.root.after(60, lambda: self.flash_node(iid))
                return None

            def pin_double(ev):
                iid = pt_.identify_row(ev.y)
                if iid in self.mm.nodes:
                    self.select(iid)
                    if pt_.identify_column(ev.x) == LCOL["memo"] and has_memo(self.mm.nodes[iid]):
                        self.root.after(10, lambda: self.memo_dialog(iid))
                    else:
                        self.show_qpop(ev.x_root, ev.y_root, refocus=pt_, force=True)
                return "break"
            pt_.bind("<Button-1>", pin_click)
            pt_.bind("<Double-Button-1>", pin_double)
            t.bind("<Button-1>", self.on_focus_click)
            t.bind("<B1-Motion>", self.on_focus_drag)   # カレンダーへドラッグ＆ドロップ
            t.bind("<ButtonRelease-1>", self.on_focus_drop)
            t.tag_configure("unplaced", foreground="#e8590c")
            t.tag_configure("placed", foreground=PLACED_COLOR)
            t.tag_configure("group", background="#e7f5ff", foreground="#1864ab",
                            font=(self.fam_base, 9, "bold"))
            t.tag_configure("rgroup", background="#ffe3e3", foreground="#c92a2a",
                            font=(self.fam_base, 9, "bold"))
            t.tag_configure("remind", foreground="#c92a2a")
            t.tag_configure("pinned", background="#fff5f5")
            t.tag_configure("newrow", foreground="#1c7ed6")
            t.tag_configure("dgroup", background="#f1f3f5", foreground="#495057", font=(self.fam_base, 9, "bold"))
            for k_, _n, _d, col_ in TASK_QUAD:   # 4象限の色（カレンダー・スケジュールと共通）
                t.tag_configure("q_" + k_, foreground=col_)
            t.tag_configure("adhoc", background=ADHOC_BG, foreground="#7c5800")
            t.tag_configure("ugroup", background="#e6fcf5", foreground="#087f5b", font=(self.fam_base, 9, "bold"))
            t.tag_configure("reuse", foreground="#087f5b")

            def list_menu(ev):
                iid = t.identify_row(ev.y)
                if not iid or iid not in self.mm.nodes:
                    return
                self.select(iid)
                m = tk.Menu(self.root, tearoff=0)
                self._fill_cal_menu(m)
                self.root.after(20, lambda: m.tk_popup(ev.x_root, ev.y_root))
            for seq in ("<Button-3>", "<Button-2>") if sys.platform == "darwin" else ("<Button-3>",):
                t.bind(seq, list_menu)
            t.bind("<<TreeviewSelect>>", self.on_focus_select)
            t.bind("<Delete>", lambda ev: (self.untask(self.sel) if self.sel in self.mm.nodes else None, "break")[1])
            t.bind("<BackSpace>", lambda ev: (self.untask(self.sel) if self.sel in self.mm.nodes else None, "break")[1])
            # エクセルと同じ操作：セルを選んで矢印・Tab・Enter で移動、文字を打つと入力（タスク名）、数字キーで 重・必・緊
            self.list_nav = GridNav(t, list(LIST_COLS), self._list_can_edit, self._list_begin, self._list_activate,
                                    lambda i: i in self.mm.nodes or i == "__newtask__",
                                    fields=["label", "imp", "need", "urg"], on_resort=self._list_auto_resort,
                                    new_row="__newtask__")   # 行の入力を終えるか、ほかを選ぶと並べ替え

            def list_press(ev):   # 選んである行をもう一度クリック → マップ⇔カレンダー
                iid = t.identify_row(ev.y)
                if iid and iid in self.mm.nodes and getattr(self, "_list_was_sel", False) and \
                        not getattr(self, "_list_dragged", False) and t.identify_column(ev.x) not in \
                        tuple(LCOL[k] for k in ("quad", "chk", "cat", "imp", "need", "urg")):
                    pass   # （もう一度クリックでマップ⇔カレンダーへの切り替えは廃止）
            t.bind("<ButtonRelease-1>", list_press, add="+")

            def list_double(ev):   # ダブルクリック → 設定画面
                self._cancel_dbl()
                self._list_was_sel = False   # 2回目のボタンを離したときに画面を切り替えない
                iid = t.identify_row(ev.y)
                if iid in self.mm.nodes and t.identify_column(ev.x) == LCOL["memo"] and has_memo(self.mm.nodes[iid]):
                    self.select(iid)   # 📝 をダブルクリック → メモを直接開く
                    self.root.after(10, lambda: self.memo_dialog(iid))
                    return "break"
                if iid in self.mm.nodes:
                    self.select(iid)
                    self.show_qpop(ev.x_root, ev.y_root, refocus=t, force=True)
                return "break"
            t.bind("<Double-Button-1>", list_double)
            t.bind("<Triple-Button-1>", list_double)
            bf = ttk.Frame(p)
            bf.pack(side="bottom", fill="x", before=fr)
            ttk.Button(bf, text="リストから外す", command=lambda: self.toggle_focus(force=False)).pack(side="left")
            ttk.Button(bf, text="完了済みを外す", command=self.unfocus_done).pack(side="right")
            # タスクリストの下：タスク分析マップ（選んだタスクを強調）
            af_ = tk.Frame(p, bg="#ffffff", highlightthickness=1, highlightbackground="#dee2e6")
            af_.pack(side="bottom", fill="x", before=bf, pady=(6, 0))
            ah_ = tk.Frame(af_, bg="#e9ecef")
            ah_.pack(fill="x")
            tk.Label(ah_, text="タスク分析マップ", bg="#e9ecef", fg="#343a40",
                     font=(self.fam_base, 9, "bold"), padx=6, pady=2).pack(side="left")
            ttk.Button(ah_, text="拡大…", width=-4, command=self.open_task_ana).pack(side="right", padx=2, pady=1)
            self.ana_panel = TaskAnaPanel(self, af_)
            self.ana_panel.mode_buttons(ah_).pack(side="right", padx=2)

            def fit_ana(ev=None):   # 分析マップのグラフが正方形になる高さ（幅に合わせる）。タスクリストの分は残す
                cw_ = self.ana_panel.chart.winfo_width()
                cw_ = cw_ if cw_ > 50 else p.winfo_width()
                h_ = cw_ - 52 + 24 + 62   # グラフの正方形（幅 − 左の目盛り）＋上下の余白・件数の行
                h_ = int(max(200, min(h_, p.winfo_height() * 0.62)))
                if abs(int(self.ana_panel.chart.cget("height")) - h_) > 4:
                    self.ana_panel.chart.configure(height=h_)
            p.bind("<Configure>", fit_ana, add="+")
            self.ana_panel.chart.bind("<Configure>", lambda ev: self.root.after_idle(fit_ana), add="+")
            # 3) 選択中のタスク
            # 選択中のタスク：左パネルには置かず、タスクを選んだときに小さなウインドウで表示
            qp = self.qpop = tk.Toplevel(self.root)
            qp.withdraw()
            qp.title("選択中のタスク")
            qp.transient(self.root)
            qp.resizable(False, False)
            if sys.platform.startswith("win"):
                try:
                    qp.attributes("-toolwindow", True)
                except tk.TclError:
                    pass
            qp.protocol("WM_DELETE_WINDOW", self.hide_qpop)
            qp.bind("<Escape>", lambda ev: self._qpop_cancel())
            self._build_task_window(qp)
            for key in self._sec_hdr:
                self._sec_hdr[key][1]()
            self._list_updating = False

        def _build_task_window(self, qp):
            """「タスクの設定」ウインドウ：上から 基本 → いつやるか → 日時 → 通知、いちばん下に［削除］［保存］。
            変更は［保存］（Enter）で反映。閉じたりほかのタスクを選んだりしたときも、変更があれば自動で保存"""
            qp.title("タスクの設定")
            ef = ttk.Frame(qp, padding=(12, 10))
            ef.pack(fill="both", expand=True)
            self.q_widgets = []
            cols_ = ttk.Frame(ef)   # 左：基本・指標 ／ 右：いつやるか・日時・通知（画面に収まるよう2列）
            cols_.pack(fill="both", expand=True)
            colL = ttk.Frame(cols_)
            colL.pack(side="left", fill="both", expand=True, anchor="n")
            colR = ttk.Frame(cols_)
            colR.pack(side="left", fill="both", expand=True, anchor="n", padx=(10, 0))
            # ① 基本
            g1 = ttk.LabelFrame(colL, text="基本", padding=(8, 4))
            g1.pack(fill="x")
            self.v_qname = tk.StringVar(value="")
            ttk.Label(g1, text="名前").grid(row=0, column=0, sticky="w")
            qe = ttk.Entry(g1, textvariable=self.v_qname, font=(self.fam_base, 11, "bold"), width=28)
            qe.grid(row=0, column=1, columnspan=5, sticky="we", pady=2)
            self.q_title = qe
            self.qv_kind = tk.StringVar(value="task")
            ttk.Label(g1, text="種類").grid(row=1, column=0, sticky="w")
            kf = ttk.Frame(g1)
            kf.grid(row=1, column=1, columnspan=5, sticky="w", pady=2)
            for val, lbl in (("task", "タスク（チェックあり）"), ("event", "予定")):
                ttk.Radiobutton(kf, text=lbl, value=val, variable=self.qv_kind).pack(side="left", padx=(0, 10))
            self.v_qcat = tk.StringVar()   # 以前のカテゴリ（廃止。画面には出さない）
            self.cb_qcat = ttk.Combobox(g1, textvariable=self.v_qcat, state="readonly", width=16)
            self.v_qpri = tk.StringVar()   # 優先度は廃止（画面には出さない）
            ttk.Label(g1, text="カテゴリ").grid(row=2, column=0, sticky="w")
            self.v_qplace = tk.StringVar()
            self.cb_qplace = ttk.Combobox(g1, textvariable=self.v_qplace, state="readonly", width=16)
            self.cb_qplace.grid(row=2, column=1, columnspan=4, sticky="we", pady=2)
            self.q_place_edit = ttk.Button(g1, text="編集…", width=-4, command=self.edit_map_categories)
            self.q_place_edit.grid(row=2, column=5, padx=(4, 0))
            self._qplace_ids = {}
            self.qv_reuse = tk.BooleanVar(value=False)
            self.qv_adhoc = tk.BooleanVar(value=False)
            self.qv_trial = tk.BooleanVar(value=False)
            self.qv_notable = tk.BooleanVar(value=False)
            flf = ttk.Frame(g1)   # 印（2列×2段）
            flf.grid(row=4, column=0, columnspan=6, sticky="w", pady=(2, 0))
            for k_, (var_, txt_) in enumerate(((self.qv_reuse, "🔁 繰り返しタスク（実施回数を記録）"),
                                               (self.qv_adhoc, "Adhoc（マップに属さない）"),
                                               (self.qv_trial, "トライアル（週の実施回数を数える）"),
                                               (self.qv_notable, "☆ 注目ノード（朝・夕方のお知らせ）"))):
                ttk.Checkbutton(flf, text=txt_, variable=var_).grid(row=k_ // 2, column=k_ % 2, sticky="w", padx=(0, 14))
            gx = ttk.LabelFrame(colL, text="指標（順位のイメージ：1＝最も高い〜6＝低い・1〜3が「高」）→ タスク分析マップ", padding=(8, 4))
            gx.pack(fill="x", pady=(8, 0))
            self.qv_idx = {}
            hints_ = {"imp": "人生・目標にとっての価値", "need": "やらないと困る度合い", "urg": "締め切りの近さ（円の大きさ）"}
            for r_, (key_, lbl_) in enumerate(TASK_INDEX):
                v_ = tk.StringVar(value="")
                ttk.Label(gx, text=lbl_, font=(self.fam_base, 10, "bold")).grid(row=r_ * 2, column=0, sticky="w", padx=(0, 6))
                for c_, val_ in enumerate(["1", "2", "3", "4", "5", "6", ""], 1):
                    ttk.Radiobutton(gx, text=val_ or "なし", value=val_, variable=v_).grid(row=r_ * 2, column=c_, padx=1)
                ttk.Label(gx, text=hints_[key_], foreground="#868e96").grid(row=r_ * 2 + 1, column=1, columnspan=7,
                                                                           sticky="w", pady=(0, 3))
                self.qv_idx[key_] = v_
            self.q_quad_lbl = tk.Label(gx, text="", font=(self.fam_base, 10, "bold"), anchor="w")
            self.q_quad_lbl.grid(row=6, column=0, columnspan=8, sticky="w")

            def show_quad(*_):
                vals = {k: v.get() for k, v in self.qv_idx.items()}
                q = task_quad({"imp": int(vals["imp"]) if vals["imp"].isdigit() else 0,
                               "need": int(vals["need"]) if vals["need"].isdigit() else 0})
                qq = next((x for x in TASK_QUAD if x[0] == q), None)
                self.q_quad_lbl.configure(text=f"分類：{qq[1]}　{qq[2]}" if qq else "分類：重要度と必要度を入れると決まります",
                                          fg=qq[3] if qq else "#868e96", wraplength=420, justify="left")
            for v_ in self.qv_idx.values():
                v_.trace_add("write", show_quad)
            g1.columnconfigure(1, weight=1)
            # ② いつやるか
            g2 = ttk.LabelFrame(colR, text="いつやるか（タスク設定）", padding=(8, 4))
            g2.pack(fill="x")
            self.v_qfreq = tk.StringVar()
            ff = ttk.Frame(g2)
            ff.pack(fill="x")
            for i, (val, lbl) in enumerate((("once_timed", "1回（時刻あり）"), ("once_day", "1回（時刻なし・デイリー）"),
                                            ("daily", "毎日"), ("weekdays", "平日"), ("weekly", "毎週"),
                                            ("monthly", "毎月"), ("iter", "反復（毎日・実施回数を表示）"))):
                rb = ttk.Radiobutton(ff, text=lbl, value=val, variable=self.v_qfreq, command=self._qpop_freq_state)
                rb.grid(row=0 if i < 2 else 1 if i < 6 else 2, column=(i * 2) if i < 2 else (i - 2) if i < 6 else 0,
                        columnspan=2 if i < 2 else 4 if i == 6 else 1, sticky="w", padx=(0, 10), pady=1)
            mf_ = ttk.Frame(ff)   # 複数回数実施（1日に1〜5回）
            mf_.grid(row=3, column=0, columnspan=4, sticky="w", pady=1)
            ttk.Radiobutton(mf_, text="複数回数実施（毎日・時刻なし）", value="multi", variable=self.v_qfreq,
                            command=self._qpop_freq_state).pack(side="left")
            ttk.Label(mf_, text="1日").pack(side="left", padx=(6, 2))
            self.qv_times = tk.StringVar(value="3")
            self.q_times_w = ttk.Spinbox(mf_, from_=1, to=5, textvariable=self.qv_times, width=3, state="readonly")
            self.q_times_w.pack(side="left")
            ttk.Label(mf_, text="回").pack(side="left", padx=(2, 0))
            self.qv = {k: tk.StringVar() for k in ("date", "a", "b", "dur", "iv", "until", "alarm")}
            rf_ = ttk.Frame(g2)
            rf_.pack(fill="x", pady=(4, 0))
            ttk.Label(rf_, text="間隔").grid(row=0, column=0, sticky="w")
            w_iv = ttk.Spinbox(rf_, from_=1, to=12, textvariable=self.qv["iv"], width=4)
            w_iv.grid(row=0, column=1, sticky="w", padx=(4, 12))
